namespace FSharp2.Compiler

open System
open System.Collections.Generic
open System.Collections.Immutable
open System.Diagnostics
open System.Globalization
open System.IO
open System.Security.Cryptography
open System.Text

module private Fingerprint =
    let text (value: string) =
        value
        |> Encoding.UTF8.GetBytes
        |> SHA256.HashData
        |> Convert.ToHexString
        |> fun hash -> hash.ToLowerInvariant()

    let parts (values: string seq) =
        values
        |> Seq.map (fun value ->
            value.Length.ToString(CultureInfo.InvariantCulture)
            + ":"
            + value
        )
        |> String.concat String.Empty
        |> text

module private TypeIdentity =
    let qualifiedName = StableIdentity.qualifiedTypeName

    let rec expression =
        function
        | TypedNamedType resolvedType ->
            Fingerprint.parts [
                "named"
                qualifiedName resolvedType.TypeName
                resolvedType.DeclarationId
            ]
        | TypedTypeParameter name ->
            Fingerprint.parts [
                "parameter"
                name
            ]
        | TypedGenericTypeApplication(genericType, arguments) ->
            Fingerprint.parts [
                "generic"
                expression genericType

                yield!
                    arguments
                    |> List.map expression
            ]
        | TypedByRefType elementType ->
            Fingerprint.parts [
                "byref"
                expression elementType
            ]
        | TypedTupleType elements ->
            Fingerprint.parts [
                "tuple"

                yield!
                    elements
                    |> List.map expression
            ]
        | TypedFunctionType(domain, range) ->
            Fingerprint.parts [
                "function"
                expression domain
                expression range
            ]

    let constraintIdentity =
        function
        | TypedSubtypeConstraint(typeParameter, superType) ->
            Fingerprint.parts [
                "subtype"
                typeParameter
                expression superType
            ]
        | TypedMemberConstraint(typeParameter, memberName, memberType) ->
            Fingerprint.parts [
                "member"
                typeParameter
                memberName
                expression memberType
            ]

    let methodConstraintIdentity =
        function
        | TypedAbbreviationConstraint constraintType ->
            Fingerprint.parts [
                "abbreviation"
                expression constraintType
            ]
        | TypedDirectConstraint constraint' ->
            Fingerprint.parts [
                "direct"
                constraintIdentity constraint'
            ]

    let cliType = StableIdentity.cliType

    let callArgument =
        function
        | TypedValueArgument name ->
            Fingerprint.parts [
                "value"
                name
            ]
        | TypedAddressOfArgument(rootName, memberPath) ->
            Fingerprint.parts [
                "address-of"
                rootName
                yield! memberPath
            ]

    let resumableCodeBody =
        function
        | TypedStoreCapturedResult(dataFieldName, resultFieldName, resultFieldStableId) ->
            Fingerprint.parts [
                "store-captured-result"
                dataFieldName
                resultFieldName
                resultFieldStableId
            ]
        | TypedInvokeCapturedUnitFunction -> "invoke-captured-unit-function"

    let resumableCode (expression: TypedResumableCodeExpression) =
        Fingerprint.parts [
            "resumable-code"
            cliType expression.DelegateType
            cliType expression.StateMachineType
            cliType expression.DataType
            expression.CaptureParameterIndex.ToString(CultureInfo.InvariantCulture)
            expression.CaptureName
            expression.StateMachineParameterName
            resumableCodeBody expression.Body
        ]

    let rec inlineBody =
        function
        | TypedIntegerLiteral value ->
            Fingerprint.parts [
                "integer"
                value.ToString(CultureInfo.InvariantCulture)
            ]
        | TypedStringLiteral value ->
            Fingerprint.parts [
                "string"
                value
            ]
        | TypedNullLiteral -> "null"
        | TypedUnitLiteral -> "unit"
        | TypedReceiverReference -> "receiver"
        | TypedParameterReference index ->
            Fingerprint.parts [
                "parameter"
                index.ToString(CultureInfo.InvariantCulture)
            ]
        | TypedLocalReference index ->
            Fingerprint.parts [
                "local"
                index.ToString(CultureInfo.InvariantCulture)
            ]
        | TypedLet(localIndex, _, isMutable, localType, value, body, _, _) ->
            Fingerprint.parts [
                "let"
                localIndex.ToString(CultureInfo.InvariantCulture)
                if isMutable then "mutable" else "immutable"
                cliType localType
                inlineBody value
                inlineBody body
            ]
        | TypedLocalAssignment(localIndex, localType, value) ->
            Fingerprint.parts [
                "local-assignment"
                localIndex.ToString(CultureInfo.InvariantCulture)
                cliType localType
                inlineBody value
            ]
        | TypedAddressOf(source, fields) ->
            let sourceIdentity =
                match source with
                | TypedParameterAddress(index, parameterType) ->
                    Fingerprint.parts [
                        "parameter"
                        index.ToString(CultureInfo.InvariantCulture)
                        cliType parameterType
                    ]
                | TypedLocalAddress(index, localType) ->
                    Fingerprint.parts [
                        "local"
                        index.ToString(CultureInfo.InvariantCulture)
                        cliType localType
                    ]

            Fingerprint.parts [
                "address-of"
                sourceIdentity

                yield!
                    fields
                    |> List.collect (fun field -> [
                        cliType field.DeclaringType
                        field.Name
                        cliType field.FieldType
                        field.TargetStableId
                        |> Option.defaultValue String.Empty
                    ])
            ]
        | TypedInstanceFieldGet(receiver, field) ->
            Fingerprint.parts [
                "instance-field-get"
                inlineBody receiver
                cliType field.DeclaringType
                field.Name
                cliType field.FieldType
                field.TargetStableId
                |> Option.defaultValue String.Empty
            ]
        | TypedStaticMethodCall(target, genericArguments, arguments) ->
            Fingerprint.parts [
                "static-call"
                target.StableId
                cliType target.DeclaringType

                yield!
                    genericArguments
                    |> List.map cliType

                yield!
                    arguments
                    |> List.map inlineBody
            ]
        | TypedObjectConstruction(target, arguments) ->
            Fingerprint.parts [
                "object-construction"
                cliType target.DeclaringType
                target.StableId

                yield!
                    target.ParameterTypes
                    |> List.map cliType

                yield!
                    arguments
                    |> List.map inlineBody
            ]
        | TypedDefaultValue(valueType, localIndex) ->
            Fingerprint.parts [
                "default-value"
                cliType valueType
                localIndex.ToString(CultureInfo.InvariantCulture)
            ]
        | TypedFunctionApplication(functionType,
                                   domainType,
                                   rangeType,
                                   functionExpression,
                                   argumentExpression) ->
            Fingerprint.parts [
                "function-application"
                cliType functionType
                cliType domainType
                cliType rangeType
                inlineBody functionExpression
                inlineBody argumentExpression
            ]
        | TypedInstanceMethodCall(target, receiver, arguments) ->
            Fingerprint.parts [
                "instance-call"
                cliType target.DeclaringType
                target.Name

                yield!
                    target.ParameterTypes
                    |> List.map cliType

                cliType target.ReturnType
                cliType target.ResultType
                inlineBody receiver

                yield!
                    arguments
                    |> List.map inlineBody
            ]
        | TypedBoundInstanceMethod expression ->
            Fingerprint.parts [
                "bound-instance-member"
                cliType expression.FunctionType
                cliType expression.DelegateType
                cliType expression.ReceiverType
                expression.TargetStableId
                expression.Target.Name
                cliType expression.DomainType
                cliType expression.RangeType
            ]
        | TypedUnitLambda expression ->
            Fingerprint.parts [
                "unit-lambda"
                cliType expression.FunctionType
                cliType expression.DelegateType
                expression.CaptureParameterIndex.ToString(CultureInfo.InvariantCulture)
                expression.CaptureName
                cliType expression.CaptureType
                cliType expression.DomainType
                cliType expression.RangeType
            ]
        | TypedFunctionLambda expression ->
            Fingerprint.parts [
                "function-lambda"
                cliType expression.FunctionType
                cliType expression.ConverterType
                expression.ParameterName
                cliType expression.ParameterType
                cliType expression.ReturnType

                yield!
                    expression.Captures
                    |> List.map (fun capture ->
                        Fingerprint.parts [
                            capture.OuterParameterIndex.ToString(CultureInfo.InvariantCulture)
                            capture.Name
                            cliType capture.Type
                            capture.Field.Name
                        ]
                    )

                inlineBody expression.Body
            ]
        | TypedDelegateLambda expression ->
            Fingerprint.parts [
                "delegate-lambda"
                cliType expression.DelegateType

                yield!
                    expression.Captures
                    |> List.map (fun capture ->
                        Fingerprint.parts [
                            capture.OuterParameterIndex.ToString(CultureInfo.InvariantCulture)
                            capture.Name
                            cliType capture.Type
                            capture.Field.Name
                        ]
                    )

                yield!
                    (expression.LambdaParameterNames, expression.LambdaParameterTypes)
                    ||> List.map2 (fun name parameterType ->
                        Fingerprint.parts [
                            name
                            cliType parameterType
                        ]
                    )

                cliType expression.LambdaReturnType
                inlineBody expression.LambdaBody
            ]
        | TypedValueTaskBind expression ->
            Fingerprint.parts [
                "value-task-bind"
                expression.BuilderName
                (match expression.ReturnKind with
                 | ComputationReturn -> "return"
                 | ComputationReturnFrom -> "return-from")
                expression.BinderParameterIndex.ToString(CultureInfo.InvariantCulture)
                expression.SourceParameterIndex.ToString(CultureInfo.InvariantCulture)
                cliType expression.InputType
                cliType expression.OutputType
                cliType expression.BinderType
                cliType expression.InputValueTaskType
                cliType expression.OutputValueTaskType
            ]
        | TypedValueTaskApply expression ->
            Fingerprint.parts [
                "value-task-apply"
                expression.BuilderName
                expression.ApplicableParameterIndex.ToString(CultureInfo.InvariantCulture)
                expression.InputParameterIndex.ToString(CultureInfo.InvariantCulture)
                cliType expression.InputType
                cliType expression.OutputType
                cliType expression.ApplierType
                cliType expression.ApplicableValueTaskType
                cliType expression.InputValueTaskType
                cliType expression.OutputValueTaskType
            ]
        | TypedValueTaskZip expression ->
            Fingerprint.parts [
                "value-task-zip"
                expression.BuilderName
                expression.LeftParameterIndex.ToString(CultureInfo.InvariantCulture)
                expression.RightParameterIndex.ToString(CultureInfo.InvariantCulture)
                cliType expression.LeftType
                cliType expression.RightType
                cliType expression.TupleType
                cliType expression.LeftValueTaskType
                cliType expression.RightValueTaskType
                cliType expression.OutputValueTaskType
            ]
        | TypedColdTaskParallelZip expression ->
            Fingerprint.parts [
                "cold-task-parallel-zip"
                inlineBody (TypedFunctionLambda expression.Function)
                inlineBody (TypedValueTaskZip expression.Zip)
            ]
        | TypedTaskTryFinally expression ->
            Fingerprint.parts [
                "task-try-finally"
                expression.WaitParameterIndex.ToString(CultureInfo.InvariantCulture)
                expression.WorkParameterIndex.ToString(CultureInfo.InvariantCulture)
                expression.CompensationParameterIndex.ToString(CultureInfo.InvariantCulture)
                cliType expression.ResultType
                cliType expression.NonGenericTaskType
                cliType expression.OutputTaskType
                cliType expression.CompensationType
            ]
        | TypedAsyncWhile expression ->
            Fingerprint.parts [
                "async-while"
                expression.GuardParameterIndex.ToString(CultureInfo.InvariantCulture)
                expression.ComputationParameterIndex.ToString(CultureInfo.InvariantCulture)
                cliType expression.AsyncBooleanType
                cliType expression.AsyncUnitType
            ]
        | TypedCancellableTaskSequential expression ->
            Fingerprint.parts [
                "cancellable-task-sequential"
                expression.SequenceParameterIndex.ToString(CultureInfo.InvariantCulture)
                cliType expression.ElementType
                cliType expression.SequenceType
                cliType expression.OutputFunctionType
                cliType expression.UnitType
            ]
        | TypedValueTaskOfUnit expression ->
            Fingerprint.parts [
                "value-task-of-unit"
                expression.BuilderName
                expression.SourceParameterIndex.ToString(CultureInfo.InvariantCulture)
                cliType expression.SourceValueTaskType
                cliType expression.UnitType
                cliType expression.OutputValueTaskType
            ]
        | TypedConditional(condition, ifTrue, ifFalse, _, _, _) ->
            Fingerprint.parts [
                "conditional"
                inlineBody condition
                inlineBody ifTrue
                inlineBody ifFalse
            ]
        | TypedUpcast(sourceType, targetType, _, expression) ->
            Fingerprint.parts [
                "upcast"
                cliType sourceType
                cliType targetType
                inlineBody expression
            ]
        | TypedSequential expressions ->
            Fingerprint.parts [
                "sequence"

                yield!
                    expressions
                    |> List.collect (fun (expression, expressionType, _) -> [
                        cliType expressionType
                        inlineBody expression
                    ])
            ]
        | TypedBooleanNegation(expression, _) ->
            Fingerprint.parts [
                "boolean-negation"
                inlineBody expression
            ]
        | TypedEquality(left, right, _) ->
            Fingerprint.parts [
                "equality"
                inlineBody left
                inlineBody right
            ]
        | TypedTryWith(body, handlerLocalIndex, handlerName, catchType, handler, _, _, _, _, _) ->
            Fingerprint.parts [
                "try-with"
                inlineBody body
                handlerLocalIndex.ToString(CultureInfo.InvariantCulture)
                handlerName
                cliType catchType
                inlineBody handler
            ]
        | TypedNullMatch(input, inputType, localIndex, bindingName, ifNull, ifNotNull, _, _, _, _) ->
            Fingerprint.parts [
                "null-match"
                inlineBody input
                cliType inputType
                localIndex.ToString(CultureInfo.InvariantCulture)
                bindingName
                inlineBody ifNull
                inlineBody ifNotNull
            ]
        | TypedTypeTestMatch(input,
                             targetType,
                             localIndex,
                             bindingName,
                             guard,
                             ifMatched,
                             ifNotMatched,
                             _,
                             _,
                             _,
                             _) ->
            Fingerprint.parts [
                "type-test-match"
                inlineBody input
                cliType targetType
                localIndex.ToString(CultureInfo.InvariantCulture)
                bindingName
                match guard with
                | Some(guardExpression, _) -> inlineBody guardExpression
                | None -> "no-guard"
                inlineBody ifMatched
                inlineBody ifNotMatched
            ]
        | TypedPatternMatch expression ->
            let operation =
                function
                | TypedPatternTypeTest(input, targetType, localIndex, localName) ->
                    Fingerprint.parts [
                        "type-test"
                        inlineBody input
                        cliType targetType
                        localIndex.ToString(CultureInfo.InvariantCulture)
                        localName
                    ]
                | TypedPatternBinding(input, inputType, localIndex, name) ->
                    Fingerprint.parts [
                        "binding"
                        inlineBody input
                        cliType inputType
                        localIndex.ToString(CultureInfo.InvariantCulture)
                        name
                    ]

            Fingerprint.parts [
                "pattern-match"
                inlineBody expression.Input
                cliType expression.InputType

                yield!
                    expression.Clauses
                    |> List.collect (fun clause -> [
                        yield!
                            clause.Operations
                            |> List.map operation
                        inlineBody clause.Body
                    ])
            ]
        | TypedResumableCode expression -> resumableCode expression
        | TypedResumableTryFinally expression ->
            Fingerprint.parts [
                "resumable-try-finally"
                cliType expression.ResumableCodeModuleType
                cliType expression.DelegateType
                cliType expression.DataType
                cliType expression.ResultType
                expression.ComputationParameterIndex.ToString(CultureInfo.InvariantCulture)
                expression.ComputationName
                resumableCode expression.Compensation
            ]
        | TypedObjectExpression(typeReference, baseType, constructorArguments, members, _) ->
            Fingerprint.parts [
                "object-expression"
                typeReference.DeclarationId
                cliType baseType

                yield!
                    constructorArguments
                    |> List.map inlineBody

                yield!
                    members
                    |> List.map (fun memberDeclaration ->
                        Fingerprint.parts [
                            if memberDeclaration.IsOverride then
                                "override"
                            else
                                "member"
                            memberDeclaration.ReceiverName
                            memberDeclaration.Name
                            cliType memberDeclaration.ReturnType

                            yield!
                                memberDeclaration.Parameters
                                |> List.map (fun parameter ->
                                    Fingerprint.parts [
                                        parameter.Name
                                        cliType parameter.Type
                                        "attributes"
                                        yield!
                                            parameter.Attributes
                                            |> List.map _.ExportFingerprint
                                    ]
                                )

                            inlineBody memberDeclaration.Body
                        ]
                    )
            ]
        | TypedTraitCall(receiverName, memberName, arguments) ->
            Fingerprint.parts [
                "trait-call"
                receiverName
                memberName
                yield!
                    arguments
                    |> List.map callArgument
            ]

    let attributeKind =
        function
        | AutoOpenAttribute -> "auto-open"
        | RequireQualifiedAccessAttribute -> "require-qualified-access"
        | StructAttribute -> "struct"
        | NoComparisonAttribute -> "no-comparison"
        | NoEqualityAttribute -> "no-equality"
        | DefaultValueAttribute -> "default-value"
        | InlineIfLambdaAttribute -> "inline-if-lambda"
        | NoEagerConstraintApplicationAttribute -> "no-eager-constraint-application"
        | EntryPointAttribute -> "entry-point"
        | CompilationMappingAttribute -> "compilation-mapping"
        | CompilationArgumentCountsAttribute -> "compilation-argument-counts"

    let attributeArgument =
        function
        | TypedBooleanAttributeArgument value -> if value then "bool:true" else "bool:false"
        | TypedSourceConstructAttributeArgument ObjectTypeConstruct ->
            "source-construct:object-type"
        | TypedSourceConstructAttributeArgument ModuleConstruct -> "source-construct:module"
        | TypedInt32ArrayAttributeArgument values ->
            values
            |> List.map (fun value -> value.ToString(CultureInfo.InvariantCulture))
            |> String.concat ","
            |> fun values ->
                "int32-array:"
                + values

    let customAttribute (attribute: TypedCustomAttribute) =
        Fingerprint.parts [
            attributeKind attribute.Kind

            yield!
                attribute.ConstructorArguments
                |> List.map attributeArgument
        ]

    let parameter (parameter: TypedParameter) =
        Fingerprint.parts [
            parameter.Name
            cliType parameter.Type
            "attributes"

            yield!
                parameter.Attributes
                |> List.map customAttribute
        ]

type private ObjectMethodKind =
    | InstanceObjectMethod
    | StaticObjectMethod

    member this.ExportIdentity =
        match this with
        | InstanceObjectMethod -> "instance"
        | StaticObjectMethod -> "static"

    member this.AllowedAttributeKinds =
        match this with
        | InstanceObjectMethod -> [
            DefaultValueAttribute
            NoEagerConstraintApplicationAttribute
          ]
        | StaticObjectMethod -> [ NoEagerConstraintApplicationAttribute ]

type private ObjectMethodCompletion = {
    Kind: ObjectMethodKind
    Name: string
    IsInline: bool
    IsPublic: bool
    GenericParameters: string list
    Constraints: TypedMethodConstraint list
    ArgumentCounts: int list
    ParsedAttributes: ParsedAttribute list
    ParsedParameters: ParsedParameter list
    Parameters: TypedParameter list
    ReturnType: CliType
    Body: TypedExpression
    EmitHiddenEntrySequencePoint: bool
    Range: SourceRange
}

type private CheckedSourceType = {
    Namespace: string
    Name: string
    StableId: string
    Methods: TypedMethodDeclaration list
}

type private CheckedSourceModuleMethod = {
    Namespace: string
    ModuleName: string
    ModuleStableId: string
    Declaration: TypedMethodDeclaration
}

type private CheckedSourceStruct = {
    Namespace: string
    Declaration: TypedStructTypeDeclaration
}

module private InlineExpansion =
    let private mapChildren transform =
        function
        | MemberCall(receiverName, memberName, arguments) ->
            MemberCall(
                receiverName,
                memberName,
                arguments
                |> List.map transform
            )
        | NamedCallArgument(name, value, range) -> NamedCallArgument(name, transform value, range)
        | StaticTypeMemberCall(receiverType, memberName, arguments) ->
            StaticTypeMemberCall(
                receiverType,
                memberName,
                arguments
                |> List.map transform
            )
        | GenericMemberCall(receiverName, memberName, typeArguments, arguments) ->
            GenericMemberCall(
                receiverName,
                memberName,
                typeArguments,
                arguments
                |> List.map transform
            )
        | MemberAssignment(rootName, memberPath, value) ->
            MemberAssignment(rootName, memberPath, transform value)
        | SequentialExpression expressions ->
            SequentialExpression(
                expressions
                |> List.map transform
            )
        | FunctionApplication(functionExpression, argumentExpression) ->
            FunctionApplication(transform functionExpression, transform argumentExpression)
        | ExpressionMemberCall(receiver, memberName, arguments) ->
            ExpressionMemberCall(
                transform receiver,
                memberName,
                arguments
                |> List.map transform
            )
        | ExpressionMemberAccess(receiver, memberName) ->
            ExpressionMemberAccess(transform receiver, memberName)
        | ConditionalExpression(condition,
                                ifTrue,
                                ifFalse,
                                conditionRange,
                                ifTrueRange,
                                ifFalseRange) ->
            ConditionalExpression(
                transform condition,
                transform ifTrue,
                transform ifFalse,
                conditionRange,
                ifTrueRange,
                ifFalseRange
            )
        | ExplicitUpcastExpression(expression, targetType) ->
            ExplicitUpcastExpression(transform expression, targetType)
        | SequentialValueExpression expressions ->
            SequentialValueExpression(
                expressions
                |> List.map (fun (expression, range) -> transform expression, range)
            )
        | LocalAssignment(name, value) -> LocalAssignment(name, transform value)
        | BooleanNegationExpression(expression, range) ->
            BooleanNegationExpression(transform expression, range)
        | EqualityExpression(left, right, range) ->
            EqualityExpression(transform left, transform right, range)
        | TryWithExpression(body,
                            bindingName,
                            handler,
                            tryRange,
                            withRange,
                            bodyRange,
                            handlerRange,
                            range) ->
            TryWithExpression(
                transform body,
                bindingName,
                transform handler,
                tryRange,
                withRange,
                bodyRange,
                handlerRange,
                range
            )
        | TryFinallyExpression(body,
                               compensation,
                               tryRange,
                               finallyRange,
                               bodyRange,
                               compensationRange,
                               range) ->
            TryFinallyExpression(
                transform body,
                transform compensation,
                tryRange,
                finallyRange,
                bodyRange,
                compensationRange,
                range
            )
        | MatchExpression(input, clauses, matchHeaderRange, range) ->
            MatchExpression(
                transform input,
                clauses
                |> List.map (fun (pattern, guard, body, bodyRange) ->
                    let guard =
                        guard
                        |> Option.map (fun (expression, guardRange) ->
                            transform expression, guardRange
                        )

                    pattern, guard, transform body, bodyRange
                ),
                matchHeaderRange,
                range
            )
        | LetExpression(bindingName, isMutable, isInline, value, body, bindingRange, bodyRange) ->
            LetExpression(
                bindingName,
                isMutable,
                isInline,
                transform value,
                transform body,
                bindingRange,
                bodyRange
            )
        | ComputationExpression(builderName, body, range) ->
            ComputationExpression(builderName, transform body, range)
        | ComputationBindingExpression(bindingName, input, body, bindingRange, bodyRange) ->
            ComputationBindingExpression(
                bindingName,
                transform input,
                transform body,
                bindingRange,
                bodyRange
            )
        | ComputationDoExpression(input, range) -> ComputationDoExpression(transform input, range)
        | WhileExpression(condition, body, conditionRange, bodyRange, range) ->
            WhileExpression(transform condition, transform body, conditionRange, bodyRange, range)
        | ForExpression(bindingName, sequence, body, bindingRange, sequenceRange, bodyRange, range) ->
            ForExpression(
                bindingName,
                transform sequence,
                transform body,
                bindingRange,
                sequenceRange,
                bodyRange,
                range
            )
        | LambdaExpression(parameterName, parameterType, body, range) ->
            LambdaExpression(parameterName, parameterType, transform body, range)
        | UnitLambdaExpression(body, range) -> UnitLambdaExpression(transform body, range)
        | TupleExpression(elements, range) ->
            TupleExpression(
                elements
                |> List.map transform,
                range
            )
        | StructTupleExpression(elements, range) ->
            StructTupleExpression(
                elements
                |> List.map transform,
                range
            )
        | TypeConstruction(constructedType, arguments, argumentRange) ->
            TypeConstruction(
                constructedType,
                arguments
                |> List.map transform,
                argumentRange
            )
        | BindReturnFromComputation(builderName, bindings, returnKind, returnFrom, range) ->
            BindReturnFromComputation(
                builderName,
                bindings
                |> List.map (fun (name, input) -> name, transform input),
                returnKind,
                transform returnFrom,
                range
            )
        | ObjectExpression(baseType, constructorArguments, members, range) ->
            ObjectExpression(
                baseType,
                constructorArguments
                |> List.map transform,
                members
                |> List.map (fun memberDeclaration -> {
                    memberDeclaration with
                        Body = transform memberDeclaration.Body
                }),
                range
            )
        | IntegerLiteral _
        | UnitLiteral
        | BooleanLiteral _
        | StringLiteral _
        | NullLiteral
        | ValueReference _
        | AddressOfExpression _
        | UnitApplication _
        | BoundInstanceMember _ as expression -> expression

    let rec private substitute replacements =
        function
        | ValueReference name as expression ->
            replacements
            |> Map.tryFind name
            |> Option.defaultValue expression
        | AddressOfExpression(rootName, memberPath) as expression ->
            match
                replacements
                |> Map.tryFind rootName
            with
            | Some(ValueReference replacement) -> AddressOfExpression(replacement, memberPath)
            | _ -> expression
        | UnitApplication functionName as expression ->
            match
                replacements
                |> Map.tryFind functionName
            with
            | Some functionExpression -> FunctionApplication(functionExpression, UnitLiteral)
            | None -> expression
        | MemberCall(receiverName, memberName, arguments) ->
            let arguments =
                arguments
                |> List.map (substitute replacements)

            match
                replacements
                |> Map.tryFind receiverName
            with
            | Some(ValueReference replacement) -> MemberCall(replacement, memberName, arguments)
            | Some receiver ->
                ExpressionMemberCall(substitute replacements receiver, memberName, arguments)
            | None -> MemberCall(receiverName, memberName, arguments)
        | GenericMemberCall(receiverName, memberName, typeArguments, arguments) ->
            let receiverName =
                match
                    replacements
                    |> Map.tryFind receiverName
                with
                | Some(ValueReference replacement) -> replacement
                | _ -> receiverName

            GenericMemberCall(
                receiverName,
                memberName,
                typeArguments,
                arguments
                |> List.map (substitute replacements)
            )
        | BoundInstanceMember(receiverName, memberName, _) as expression ->
            match
                replacements
                |> Map.tryFind receiverName
            with
            | Some receiver -> ExpressionMemberAccess(receiver, memberName)
            | None -> expression
        | MemberAssignment(rootName, memberPath, value) ->
            let rootName =
                match
                    replacements
                    |> Map.tryFind rootName
                with
                | Some(ValueReference replacement) -> replacement
                | _ -> rootName

            MemberAssignment(rootName, memberPath, substitute replacements value)
        | LocalAssignment(name, value) ->
            let name =
                match
                    replacements
                    |> Map.tryFind name
                with
                | Some(ValueReference replacement) -> replacement
                | _ -> name

            LocalAssignment(name, substitute replacements value)
        | LetExpression(bindingName, isMutable, isInline, value, body, bindingRange, bodyRange) ->
            LetExpression(
                bindingName,
                isMutable,
                isInline,
                substitute replacements value,
                substitute
                    (replacements
                     |> Map.remove bindingName)
                    body,
                bindingRange,
                bodyRange
            )
        | LambdaExpression(parameterName, parameterType, body, range) ->
            LambdaExpression(
                parameterName,
                parameterType,
                substitute
                    (replacements
                     |> Map.remove parameterName)
                    body,
                range
            )
        | TryWithExpression(body,
                            bindingName,
                            handler,
                            tryRange,
                            withRange,
                            bodyRange,
                            handlerRange,
                            range) ->
            TryWithExpression(
                substitute replacements body,
                bindingName,
                substitute
                    (replacements
                     |> Map.remove bindingName)
                    handler,
                tryRange,
                withRange,
                bodyRange,
                handlerRange,
                range
            )
        | expression -> mapChildren (substitute replacements) expression

    let private lambdaParameters (expression: ParsedExpression) =
        let rec collect parameters =
            function
            | LambdaExpression(parameterName, _, body, _) ->
                collect
                    (parameterName
                     :: parameters)
                    body
            | body -> List.rev parameters, body

        collect [] expression

    let private application
        (expression: ParsedExpression)
        : (string * ParsedExpression list) option =
        let rec collect arguments =
            function
            | FunctionApplication(functionExpression, argument) ->
                collect
                    (argument
                     :: arguments)
                    functionExpression
            | ValueReference functionName -> Some(functionName, arguments)
            | _ -> None

        collect [] expression

    let rec private replaceCalls functionName (parameters: string list) functionBody expression =
        let replacement =
            application expression
            |> Option.bind (fun (calledName, arguments) ->
                let arguments =
                    arguments
                    |> List.collect (
                        function
                        | TupleExpression(elements, _) -> elements
                        | argument -> [ argument ]
                    )

                if
                    calledName = functionName
                    && arguments.Length = parameters.Length
                then
                    List.zip parameters arguments
                    |> Map.ofList
                    |> fun replacements -> substitute replacements functionBody
                    |> Some
                else
                    None
            )

        match replacement with
        | Some expression -> expression
        | None ->
            match expression with
            | LetExpression(bindingName, isMutable, isInline, value, body, bindingRange, bodyRange) ->
                LetExpression(
                    bindingName,
                    isMutable,
                    isInline,
                    replaceCalls functionName parameters functionBody value,
                    (if bindingName = functionName then
                         body
                     else
                         replaceCalls functionName parameters functionBody body),
                    bindingRange,
                    bodyRange
                )
            | LambdaExpression(parameterName, parameterType, body, range) ->
                LambdaExpression(
                    parameterName,
                    parameterType,
                    (if parameterName = functionName then
                         body
                     else
                         replaceCalls functionName parameters functionBody body),
                    range
                )
            | expression ->
                mapChildren (replaceCalls functionName parameters functionBody) expression

    let expand expression =
        let mutable expandedLocalFunction = false

        let rec expandExpression =
            function
            | LetExpression(bindingName, false, true, value, body, _, _) ->
                expandedLocalFunction <- true

                let parameters, functionBody = lambdaParameters value

                body
                |> replaceCalls bindingName parameters functionBody
                |> expandExpression
            | expression -> mapChildren expandExpression expression

        expandExpression expression, expandedLocalFunction

    let sourceRange defaultRange =
        function
        | LetExpression(_, false, true, _, _, _, bodyRange) -> bodyRange
        | _ -> defaultRange

/// A deliberately small in-memory query owner. Query identities and cached
/// values are semantic/compiler state; final SRM state never enters these maps.
type internal CompilerService() =
    let querySchema = CompilerSchema.Query
    let lexicalCache = Dictionary<string, LexicalCore>(StringComparer.Ordinal)
    let parseCache = Dictionary<string, ParsedModule list>(StringComparer.Ordinal)
    let checkCache = Dictionary<string, TypedModule>(StringComparer.Ordinal)
    let lowerCache = Dictionary<string, LoweredCompilation>(StringComparer.Ordinal)
    let lastSuccessfulContent = Dictionary<string, string>(StringComparer.Ordinal)
    let mutable parseHits = 0
    let mutable parseMisses = 0
    let mutable syntaxProjections = 0
    let mutable checkHits = 0
    let mutable checkMisses = 0
    let mutable lowerHits = 0
    let mutable lowerMisses = 0

    let elapsedMicroseconds started =
        Stopwatch.GetElapsedTime(started).Ticks
        / 10L

    let normalizeDefines (defines: string seq) =
        defines
        |> Seq.distinct
        |> Seq.sortWith (fun left right -> StringComparer.Ordinal.Compare(left, right))
        |> Seq.toArray

    let prepareSource (language: LanguageVersionIdentity) defines (snapshot: SourceSnapshot) =
        let normalizedDefines = normalizeDefines defines

        let key =
            Fingerprint.parts [
                querySchema.ToString(CultureInfo.InvariantCulture)
                "lexical"
                language.CacheIdentity
                normalizedDefines.Length.ToString(CultureInfo.InvariantCulture)
                yield! normalizedDefines
                snapshot.Text
            ]

        match lexicalCache.TryGetValue(key) with
        | true, core -> {
            Document = LexicalPipeline.bind language snapshot core
            Decision = "hit"
          }
        | false, _ ->
            let core =
                snapshot.Text
                |> SourceText.fromString
                |> LexicalPipeline.prepareCore language normalizedDefines

            lexicalCache.Add(key, core)

            {
                Document = LexicalPipeline.bind language snapshot core
                Decision = "miss"
            }

    let lexicalDiagnostic (source: LexicalDocument) (diagnostic: SourceLexicalDiagnostic) =
        let startPosition = SourceMap.mapPosition source.SourceMap diagnostic.Range.Start
        let endPosition = SourceMap.mapPosition source.SourceMap diagnostic.Range.End

        {
            Code = diagnostic.Code
            Message = diagnostic.Message
            Path =
                startPosition.LogicalPath
                |> Option.defaultValue source.LogicalPath
                |> Some
            Range =
                Some {
                    Start = {
                        Offset = startPosition.Offset
                        Line = startPosition.Line
                        Column = startPosition.Column
                    }
                    End = {
                        Offset = endPosition.Offset
                        Line = endPosition.Line
                        Column = endPosition.Column
                    }
                }
        }

    let mappedCompilerDiagnostic (source: LexicalDocument) (diagnostic: CompilerDiagnostic) =
        match diagnostic.Range with
        | None -> diagnostic
        | Some range ->
            let startPosition = SourceMap.mapPosition source.SourceMap range.Start
            let endPosition = SourceMap.mapPosition source.SourceMap range.End

            {
                diagnostic with
                    Path =
                        startPosition.LogicalPath
                        |> Option.orElse diagnostic.Path
                    Range =
                        Some {
                            Start = {
                                Offset = startPosition.Offset
                                Line = startPosition.Line
                                Column = startPosition.Column
                            }
                            End = {
                                Offset = endPosition.Offset
                                Line = endPosition.Line
                                Column = endPosition.Column
                            }
                        }
            }

    let parse (source: LexicalDocument) =
        let key =
            Fingerprint.parts [
                querySchema.ToString(CultureInfo.InvariantCulture)
                "parse"
                source.LexicalFingerprint
            ]

        match parseCache.TryGetValue(key) with
        | true, parsed ->
            parseHits <-
                parseHits
                + 1

            Ok(
                parsed
                |> List.map (fun parsedModule -> {
                    parsedModule with
                        SourceChecksum = source.SourceChecksum
                }),
                key
            )
        | false, _ ->
            parseMisses <-
                parseMisses
                + 1

            let compatibilitySource = {
                Path = source.LogicalPath
                Text = source.CompatibilityText
                ContentFingerprint = source.ContentFingerprint
            }

            match SyntaxRouting.tryProject source with
            | Some parsed ->
                syntaxProjections <-
                    syntaxProjections
                    + 1

                parseCache.Add(key, parsed)
                Ok(parsed, key)
            | None ->
                match Frontend.parse [] compatibilitySource with
                | Error error -> Error(mappedCompilerDiagnostic source error)
                | Ok parsed ->
                    let rebound =
                        parsed
                        |> List.map (fun parsedModule -> {
                            parsedModule with
                                SourceChecksum = source.SourceChecksum
                        })

                    parseCache.Add(key, rebound)
                    Ok(rebound, key)

    let expressionChildren =
        function
        | NamedCallArgument(_, value, _) -> [ value ]
        | MemberCall(_, _, arguments)
        | StaticTypeMemberCall(_, _, arguments)
        | GenericMemberCall(_, _, _, arguments)
        | SequentialExpression arguments
        | TupleExpression(arguments, _)
        | StructTupleExpression(arguments, _)
        | TypeConstruction(_, arguments, _) -> arguments
        | MemberAssignment(_, _, value)
        | ExplicitUpcastExpression(value, _)
        | LocalAssignment(_, value)
        | BooleanNegationExpression(value, _)
        | ComputationExpression(_, value, _)
        | ComputationDoExpression(value, _)
        | UnitLambdaExpression(value, _) -> [ value ]
        | FunctionApplication(functionExpression, argumentExpression)
        | EqualityExpression(functionExpression, argumentExpression, _)
        | LetExpression(_, _, _, functionExpression, argumentExpression, _, _)
        | ComputationBindingExpression(_, functionExpression, argumentExpression, _, _)
        | WhileExpression(functionExpression, argumentExpression, _, _, _) -> [
            functionExpression
            argumentExpression
          ]
        | ExpressionMemberCall(receiver, _, arguments) ->
            receiver
            :: arguments
        | ExpressionMemberAccess(receiver, _) -> [ receiver ]
        | ConditionalExpression(condition, ifTrue, ifFalse, _, _, _) -> [
            condition
            ifTrue
            ifFalse
          ]
        | SequentialValueExpression expressions ->
            expressions
            |> List.map fst
        | TryWithExpression(body, _, handler, _, _, _, _, _)
        | TryFinallyExpression(body, handler, _, _, _, _, _) -> [
            body
            handler
          ]
        | MatchExpression(input, clauses, _, _) ->
            input
            :: (clauses
                |> List.collect (fun (_, guard, body, _) -> [
                    yield!
                        guard
                        |> Option.map fst
                        |> Option.toList

                    body
                ]))
        | ForExpression(_, sequence, body, _, _, _, _) -> [
            sequence
            body
          ]
        | LambdaExpression(_, _, body, _) -> [ body ]
        | BindReturnFromComputation(_, bindings, _, returnFrom, _) ->
            (bindings
             |> List.map snd)
            @ [ returnFrom ]
        | ObjectExpression(_, constructorArguments, members, _) ->
            constructorArguments
            @ (members
               |> List.map _.Body)
        | IntegerLiteral _
        | UnitLiteral
        | BooleanLiteral _
        | StringLiteral _
        | NullLiteral
        | ValueReference _
        | AddressOfExpression _
        | UnitApplication _
        | BoundInstanceMember _ -> []

    let rec matchPatternBindings =
        function
        | ParsedTypeTestPattern(_, name, _)
        | ParsedNamedPattern(name, _) -> Set.singleton name
        | ParsedTuplePattern(elements, _) ->
            elements
            |> List.fold
                (fun bindings element -> Set.union bindings (matchPatternBindings element))
                Set.empty
        | ParsedUnionCasePattern(_, argument, _) -> matchPatternBindings argument
        | ParsedNullPattern _
        | ParsedUnitPattern _ -> Set.empty

    let rec tryFindLaterModuleReference laterModuleNames boundNames expression =
        let tryFindWith bindings expressions =
            expressions
            |> List.tryPick (tryFindLaterModuleReference laterModuleNames bindings)

        match expression with
        | BoundInstanceMember(receiverName, _, receiverRange) when
            laterModuleNames
            |> Set.contains receiverName
            && (boundNames
                |> Set.contains receiverName
                |> not)
            ->
            Some(receiverName, receiverRange)
        | LetExpression(bindingName, _, _, value, body, _, _) ->
            match tryFindLaterModuleReference laterModuleNames boundNames value with
            | Some reference -> Some reference
            | None ->
                tryFindLaterModuleReference
                    laterModuleNames
                    (boundNames
                     |> Set.add bindingName)
                    body
        | LambdaExpression(parameterName, _, body, _) ->
            tryFindLaterModuleReference
                laterModuleNames
                (boundNames
                 |> Set.add parameterName)
                body
        | ComputationBindingExpression(bindingName, input, body, _, _) ->
            match tryFindLaterModuleReference laterModuleNames boundNames input with
            | Some reference -> Some reference
            | None ->
                tryFindLaterModuleReference
                    laterModuleNames
                    (boundNames
                     |> Set.add bindingName)
                    body
        | ForExpression(bindingName, sequence, body, _, _, _, _) ->
            match tryFindLaterModuleReference laterModuleNames boundNames sequence with
            | Some reference -> Some reference
            | None ->
                tryFindLaterModuleReference
                    laterModuleNames
                    (boundNames
                     |> Set.add bindingName)
                    body
        | TryWithExpression(body, bindingName, handler, _, _, _, _, _) ->
            match tryFindLaterModuleReference laterModuleNames boundNames body with
            | Some reference -> Some reference
            | None ->
                tryFindLaterModuleReference
                    laterModuleNames
                    (boundNames
                     |> Set.add bindingName)
                    handler
        | MatchExpression(input, clauses, _, _) ->
            match tryFindLaterModuleReference laterModuleNames boundNames input with
            | Some reference -> Some reference
            | None ->
                clauses
                |> List.tryPick (fun (pattern, guard, body, _) ->
                    let clauseBindings = Set.union boundNames (matchPatternBindings pattern)

                    match
                        guard
                        |> Option.bind (fun (guardExpression, _) ->
                            tryFindLaterModuleReference
                                laterModuleNames
                                clauseBindings
                                guardExpression
                        )
                    with
                    | Some reference -> Some reference
                    | None -> tryFindLaterModuleReference laterModuleNames clauseBindings body
                )
        | BindReturnFromComputation(_, bindings, _, returnFrom, _) ->
            let rec tryFindBindings currentBindings =
                function
                | [] -> tryFindLaterModuleReference laterModuleNames currentBindings returnFrom
                | (bindingName, input) :: remaining ->
                    match tryFindLaterModuleReference laterModuleNames currentBindings input with
                    | Some reference -> Some reference
                    | None ->
                        tryFindBindings
                            (currentBindings
                             |> Set.add bindingName)
                            remaining

            tryFindBindings boundNames bindings
        | ObjectExpression(_, constructorArguments, members, _) ->
            match tryFindWith boundNames constructorArguments with
            | Some reference -> Some reference
            | None ->
                members
                |> List.tryPick (fun memberDeclaration ->
                    let memberBindings =
                        memberDeclaration.ParameterNames
                        |> List.fold
                            (fun bindings parameterName ->
                                bindings
                                |> Set.add parameterName
                            )
                            (boundNames
                             |> Set.add memberDeclaration.ReceiverName)

                    tryFindLaterModuleReference
                        laterModuleNames
                        memberBindings
                        memberDeclaration.Body
                )
        | _ ->
            expression
            |> expressionChildren
            |> tryFindWith boundNames

    let editDistance (left: string) (right: string) =
        let left = left.ToLowerInvariant()
        let right = right.ToLowerInvariant()

        let distances =
            Array2D.zeroCreate<int>
                (left.Length
                 + 1)
                (right.Length
                 + 1)

        for leftIndex = 0 to left.Length do
            distances.[leftIndex, 0] <- leftIndex

        for rightIndex = 0 to right.Length do
            distances.[0, rightIndex] <- rightIndex

        for leftIndex = 1 to left.Length do
            for rightIndex = 1 to right.Length do
                let substitutionCost =
                    if
                        left.[leftIndex
                              - 1] = right.[rightIndex
                                            - 1]
                    then
                        0
                    else
                        1

                distances.[leftIndex, rightIndex] <-
                    min
                        (min
                            (distances.[leftIndex
                                        - 1,
                                        rightIndex]
                             + 1)
                            (distances.[leftIndex,
                                        rightIndex
                                        - 1]
                             + 1))
                        (distances.[leftIndex
                                    - 1,
                                    rightIndex
                                    - 1]
                         + substitutionCost)

        distances.[left.Length, right.Length]

    let undefinedModuleMessage (references: ReferenceTypeIndex) (name: string) =
        let message = $"The value, namespace, type or module '{name}' is not defined."

        let maximumDistance =
            max
                1
                (name.Length
                 / 2)

        let suggestions =
            references.SourceSuggestionNames
            |> List.mapi (fun index candidate -> candidate, editDistance name candidate, index)
            |> List.filter (fun (_, distance, _) ->
                distance
                <= maximumDistance
            )
            |> List.sortBy (fun (_, distance, index) -> distance, index)
            |> List.truncate 3
            |> List.map (fun (candidate, _, _) -> candidate)

        match suggestions with
        | [] -> message
        | _ ->
            message
            + " Maybe you want one of the following:"
            + (suggestions
               |> List.map (fun suggestion ->
                   "\u001d   "
                   + suggestion
               )
               |> String.concat String.Empty)

    let resolve
        (references: ReferenceTypeIndex)
        (sourcePath: string)
        (documentIndex: int)
        (precedingValues: Map<string, string>)
        (laterModuleNames: Set<string>)
        (parsed: ParsedModule)
        =
        let declarationIdentity name suffix =
            parsed.StableId
            + suffix
            + name

        let rec resolveDeclarations visibleValues =
            function
            | [] -> Ok visibleValues
            | declaration :: remaining ->
                let unresolvedValue =
                    match declaration with
                    | ParsedMethod({
                                       Body = ValueReference name
                                       BodyRange = range
                                   } as methodDeclaration) when
                        visibleValues
                        |> Map.containsKey name
                        |> not
                        && (
                            match methodDeclaration.Kind with
                            | ParsedMethodKind.EntryPoint parameterName
                            | ParsedMethodKind.RegularFunction parameterName
                            | ParsedMethodKind.RegularTypedFunction(parameterName, _) ->
                                parameterName
                                <> name
                            | ParsedMethodKind.Regular -> true
                        )
                        ->
                        Some(name, range, $"The value or constructor '{name}' is not defined.")
                    | ParsedMethod methodDeclaration ->
                        let boundNames =
                            visibleValues
                            |> Map.keys
                            |> Set.ofSeq

                        let boundNames =
                            match methodDeclaration.Kind with
                            | ParsedMethodKind.EntryPoint parameterName
                            | ParsedMethodKind.RegularFunction parameterName
                            | ParsedMethodKind.RegularTypedFunction(parameterName, _) ->
                                boundNames
                                |> Set.add parameterName
                            | ParsedMethodKind.Regular -> boundNames

                        methodDeclaration.Body
                        |> tryFindLaterModuleReference laterModuleNames boundNames
                        |> Option.map (fun (name, range) ->
                            name, range, undefinedModuleMessage references name
                        )
                    | ParsedLiteralField _
                    | ParsedNestedModule _
                    | ParsedTypeAbbreviation _
                    | ParsedStaticType _
                    | ParsedObjectType _
                    | ParsedStructType _ -> None

                match unresolvedValue with
                | Some(_, range, message) ->
                    Error {
                        Code = "FS0039"
                        Message = message
                        Path = Some sourcePath
                        Range = Some range
                    }
                | None ->
                    let nextVisibleValues =
                        match declaration with
                        | ParsedMethod methodDeclaration ->
                            visibleValues
                            |> Map.add
                                methodDeclaration.Name
                                (declarationIdentity methodDeclaration.Name "/method:")
                        | ParsedLiteralField fieldDeclaration ->
                            visibleValues
                            |> Map.add
                                fieldDeclaration.Name
                                (declarationIdentity fieldDeclaration.Name "/literal-field:")
                        | ParsedNestedModule _
                        | ParsedTypeAbbreviation _
                        | ParsedStaticType _
                        | ParsedObjectType _
                        | ParsedStructType _ -> visibleValues

                    resolveDeclarations nextVisibleValues remaining

        match resolveDeclarations precedingValues parsed.Declarations with
        | Error diagnostic -> Error diagnostic
        | Ok visibleValues ->
            let contentFingerprint =
                [
                    parsed.ContentFingerprint

                    yield!
                        visibleValues
                        |> Map.toList
                        |> List.collect (fun (name, stableId) -> [
                            name
                            stableId
                        ])
                ]
                |> Fingerprint.parts

            Ok {
                SourcePath = sourcePath
                DocumentIndex = documentIndex
                Syntax = parsed
                VisibleValues = visibleValues
                ContentFingerprint = contentFingerprint
            }

    let check
        (references: ReferenceTypeIndex)
        (precedingModules: TypedModule list)
        (resolved: ResolvedModule)
        =
        let sourcePath = resolved.SourcePath
        let documentIndex = resolved.DocumentIndex
        let parsed = resolved.Syntax

        let key =
            Fingerprint.parts [
                querySchema.ToString(CultureInfo.InvariantCulture)
                references.Fingerprint

                yield!
                    precedingModules
                    |> List.collect (fun precedingModule -> [
                        precedingModule.StableId
                        precedingModule.ExportFingerprint
                    ])

                parsed.StableId
                parsed.ContentFingerprint
            ]

        match checkCache.TryGetValue(key) with
        | true, typed ->
            checkHits <-
                checkHits
                + 1

            Ok(
                {
                    typed with
                        DocumentIndex = documentIndex
                        SourceChecksum = parsed.SourceChecksum
                },
                key
            )
        | false, _ ->
            checkMisses <-
                checkMisses
                + 1

            let diagnostic range message =
                Error {
                    Code = "FSC2P1001"
                    Message = message
                    Path = Some sourcePath
                    Range = Some range
                }

            let checkedSourceTypes = ResizeArray<CheckedSourceType>()
            let checkedSourceStructs = ResizeArray<CheckedSourceStruct>()
            let checkedSourceModuleMethods = ResizeArray<CheckedSourceModuleMethod>()

            let addCheckedDeclaration namespaceName moduleName moduleStableId =
                function
                | TypedStaticType declaration ->
                    checkedSourceTypes.Add {
                        Namespace = namespaceName
                        Name = declaration.Name
                        StableId = declaration.StableId
                        Methods = declaration.Methods
                    }
                | TypedObjectType({ Container = OrdinaryTypedObjectType } as declaration) ->
                    checkedSourceTypes.Add {
                        Namespace = namespaceName
                        Name = declaration.Name
                        StableId = declaration.StableId
                        Methods =
                            declaration.Methods
                            |> List.choose (
                                function
                                | TypedStaticObjectMethod methodDeclaration ->
                                    Some methodDeclaration
                                | TypedInstanceObjectMethod _ -> None
                            )
                    }
                | TypedObjectType _ -> ()
                | TypedStructType declaration ->
                    checkedSourceStructs.Add {
                        Namespace = namespaceName
                        Declaration = declaration
                    }
                | TypedMethod declaration ->
                    checkedSourceModuleMethods.Add {
                        Namespace = namespaceName
                        ModuleName = moduleName
                        ModuleStableId = moduleStableId
                        Declaration = declaration
                    }
                | TypedLiteralField _
                | TypedNestedModule _
                | TypedTypeAbbreviation _ -> ()

            for precedingModule in precedingModules do
                for declaration in precedingModule.Declarations do
                    addCheckedDeclaration
                        precedingModule.Namespace
                        precedingModule.Name
                        precedingModule.StableId
                        declaration

            let typeAbbreviations =
                parsed.Declarations
                |> List.choose (
                    function
                    | ParsedTypeAbbreviation declaration -> Some(declaration.Name, declaration)
                    | ParsedMethod _
                    | ParsedLiteralField _
                    | ParsedNestedModule _
                    | ParsedStaticType _
                    | ParsedObjectType _
                    | ParsedStructType _ -> None
                )
                |> Map.ofList

            let localTypes = Dictionary<TypeNameArity, ResolvedTypeName>()

            for declaration in parsed.Declarations do
                match ParsedDeclaration.tryTypeIdentity parsed.StableId declaration with
                | Some(key, declarationId) ->
                    let isValueType =
                        match declaration with
                        | ParsedStructType _ -> true
                        | ParsedMethod _
                        | ParsedLiteralField _
                        | ParsedNestedModule _
                        | ParsedTypeAbbreviation _
                        | ParsedStaticType _
                        | ParsedObjectType _ -> false

                    let resolved: ResolvedTypeName = {
                        TypeName = {
                            Namespace = parsed.Namespace
                            Name = key.Name
                        }
                        DeclarationId = declarationId
                        AssemblyName = String.Empty
                        IsValueType = isValueType
                    }

                    localTypes.TryAdd(key, resolved)
                    |> ignore
                | None -> ()

            let resolveNamedType
                (genericArity: int)
                (typeName: QualifiedTypeName)
                (range: SourceRange)
                =
                let localKey = ReferenceTypeName.simpleKey typeName.Name genericArity

                match
                    String.IsNullOrEmpty(typeName.Namespace), localTypes.TryGetValue(localKey)
                with
                | true, (true, resolved) -> Ok(TypedNamedType resolved)
                | _ ->
                    match
                        references.Resolve(
                            parsed.Namespace,
                            parsed.OpenedNamespaces,
                            typeName,
                            genericArity
                        )
                    with
                    | Ok resolved -> Ok(TypedNamedType resolved)
                    | Error message -> diagnostic range message

            let rec resolveType (declaredParameters: HashSet<string>) =
                function
                | ParsedTypeParameter(name, range) ->
                    if declaredParameters.Contains(name) then
                        Ok(TypedTypeParameter name)
                    else
                        diagnostic range $"the type parameter '{name}' is not declared"
                | ParsedWildcardType range ->
                    diagnostic range "a wildcard type requires an expected type"
                | ParsedFlexibleType(_, range) ->
                    diagnostic range "a flexible type must be generalized by its member declaration"
                | ParsedNamedType(typeName, range) -> resolveNamedType 0 typeName range
                | ParsedGenericTypeApplication(ParsedNamedType(typeName, _), [ argument ], _) when
                    String.IsNullOrEmpty(typeName.Namespace)
                    && typeName.Name = "byref"
                    ->
                    resolveType declaredParameters argument
                    |> Result.map TypedByRefType
                | ParsedGenericTypeApplication(genericType, arguments, _) ->
                    let typedGenericType =
                        match genericType with
                        | ParsedNamedType(typeName, range) ->
                            let resolvedTypeName =
                                if
                                    arguments.Length = 1
                                    && String.IsNullOrEmpty(typeName.Namespace)
                                    && typeName.Name = "option"
                                then
                                    {
                                        Namespace = "Microsoft.FSharp.Core"
                                        Name = "FSharpOption"
                                    }
                                else
                                    typeName

                            resolveNamedType arguments.Length resolvedTypeName range
                        | _ -> resolveType declaredParameters genericType

                    match typedGenericType with
                    | Error error -> Error error
                    | Ok typedGenericType ->
                        let rec resolveArguments resolved =
                            function
                            | [] -> Ok(List.rev resolved)
                            | argument :: remaining ->
                                match resolveType declaredParameters argument with
                                | Error error -> Error error
                                | Ok typedArgument ->
                                    resolveArguments
                                        (typedArgument
                                         :: resolved)
                                        remaining

                        resolveArguments [] arguments
                        |> Result.map (fun typedArguments ->
                            TypedGenericTypeApplication(typedGenericType, typedArguments)
                        )
                | ParsedTupleType(elements, _) ->
                    let rec resolveElements resolved =
                        function
                        | [] -> Ok(List.rev resolved)
                        | element :: remaining ->
                            match resolveType declaredParameters element with
                            | Error error -> Error error
                            | Ok typedElement ->
                                resolveElements
                                    (typedElement
                                     :: resolved)
                                    remaining

                    resolveElements [] elements
                    |> Result.map TypedTupleType
                | ParsedFunctionType(domain, range, _) ->
                    match resolveType declaredParameters domain with
                    | Error error -> Error error
                    | Ok typedDomain ->
                        resolveType declaredParameters range
                        |> Result.map (fun typedRange -> TypedFunctionType(typedDomain, typedRange))

            let rec substituteType (substitutions: Map<string, ParsedTypeExpression>) expression =
                match expression with
                | ParsedTypeParameter(name, _) ->
                    substitutions
                    |> Map.tryFind name
                    |> Option.defaultValue expression
                | ParsedFlexibleType(superType, range) ->
                    ParsedFlexibleType(substituteType substitutions superType, range)
                | ParsedWildcardType _
                | ParsedNamedType _ -> expression
                | ParsedGenericTypeApplication(genericType, arguments, range) ->
                    ParsedGenericTypeApplication(
                        substituteType substitutions genericType,
                        arguments
                        |> List.map (substituteType substitutions),
                        range
                    )
                | ParsedTupleType(elements, range) ->
                    ParsedTupleType(
                        elements
                        |> List.map (substituteType substitutions),
                        range
                    )
                | ParsedFunctionType(domain, range, sourceRange) ->
                    ParsedFunctionType(
                        substituteType substitutions domain,
                        substituteType substitutions range,
                        sourceRange
                    )

            let rec expandTypeAbbreviations expanding expression =
                let expand = expandTypeAbbreviations expanding

                match expression with
                | ParsedGenericTypeApplication(ParsedNamedType(typeName, _), arguments, _) when
                    String.IsNullOrEmpty(typeName.Namespace)
                    ->
                    let expandedArguments =
                        arguments
                        |> List.map expand

                    match
                        typeAbbreviations
                        |> Map.tryFind typeName.Name
                    with
                    | Some abbreviation when
                        abbreviation.TypeParameters.Length = expandedArguments.Length
                        && not (
                            expanding
                            |> Set.contains typeName.Name
                        )
                        ->
                        abbreviation.Target.Type
                        |> substituteType (
                            List.zip abbreviation.TypeParameters expandedArguments
                            |> Map.ofList
                        )
                        |> expandTypeAbbreviations (
                            expanding
                            |> Set.add typeName.Name
                        )
                    | _ ->
                        match expression with
                        | ParsedGenericTypeApplication(genericType, _, range) ->
                            ParsedGenericTypeApplication(
                                expand genericType,
                                expandedArguments,
                                range
                            )
                        | _ -> expression
                | ParsedNamedType(typeName, _) when String.IsNullOrEmpty(typeName.Namespace) ->
                    match
                        typeAbbreviations
                        |> Map.tryFind typeName.Name
                    with
                    | Some abbreviation when
                        List.isEmpty abbreviation.TypeParameters
                        && not (
                            expanding
                            |> Set.contains typeName.Name
                        )
                        ->
                        abbreviation.Target.Type
                        |> expandTypeAbbreviations (
                            expanding
                            |> Set.add typeName.Name
                        )
                    | _ -> expression
                | ParsedGenericTypeApplication(genericType, arguments, range) ->
                    ParsedGenericTypeApplication(
                        expand genericType,
                        arguments
                        |> List.map expand,
                        range
                    )
                | ParsedTupleType(elements, range) ->
                    ParsedTupleType(
                        elements
                        |> List.map expand,
                        range
                    )
                | ParsedFunctionType(domain, range, sourceRange) ->
                    ParsedFunctionType(expand domain, expand range, sourceRange)
                | ParsedFlexibleType(superType, range) ->
                    ParsedFlexibleType(expand superType, range)
                | ParsedTypeParameter _
                | ParsedWildcardType _
                | ParsedNamedType _ -> expression

            let rec collectResults completed remaining =
                match remaining with
                | [] -> Ok(List.rev completed)
                | result :: tail ->
                    match result with
                    | Error diagnostic -> Error diagnostic
                    | Ok value ->
                        collectResults
                            (value
                             :: completed)
                            tail

            let knownAttributeKind (attribute: ParsedAttribute) =
                let name = attribute.AttributeType.Name

                match name with
                | "AutoOpen"
                | "AutoOpenAttribute" -> Some AutoOpenAttribute
                | "RequireQualifiedAccess"
                | "RequireQualifiedAccessAttribute" -> Some RequireQualifiedAccessAttribute
                | "Struct"
                | "StructAttribute" -> Some StructAttribute
                | "NoComparison"
                | "NoComparisonAttribute" -> Some NoComparisonAttribute
                | "NoEquality"
                | "NoEqualityAttribute" -> Some NoEqualityAttribute
                | "DefaultValue"
                | "DefaultValueAttribute" -> Some DefaultValueAttribute
                | "InlineIfLambda"
                | "InlineIfLambdaAttribute" -> Some InlineIfLambdaAttribute
                | "NoEagerConstraintApplication"
                | "NoEagerConstraintApplicationAttribute" ->
                    Some NoEagerConstraintApplicationAttribute
                | _ -> None

            let typeCustomAttribute
                ownerStableId
                allowedKinds
                (index: int)
                (attribute: ParsedAttribute)
                =
                let unsupported message = diagnostic attribute.Range message

                let create kind arguments =
                    let stableId =
                        ownerStableId
                        + "/attribute:"
                        + index.ToString(CultureInfo.InvariantCulture)

                    Ok {
                        StableId = stableId
                        Kind = kind
                        ConstructorArguments = arguments
                        ExportFingerprint =
                            Fingerprint.parts [
                                stableId
                                TypeIdentity.attributeKind kind
                                yield!
                                    arguments
                                    |> List.map TypeIdentity.attributeArgument
                            ]
                    }

                match knownAttributeKind attribute with
                | None -> unsupported "the declaration attribute is not yet supported"
                | Some kind when
                    not (
                        allowedKinds
                        |> List.contains kind
                    )
                    ->
                    unsupported "the attribute is not valid on this declaration"
                | Some DefaultValueAttribute ->
                    match attribute.ConstructorArguments with
                    | [] -> create DefaultValueAttribute []
                    | [ ParsedBooleanAttributeArgument value ] ->
                        create DefaultValueAttribute [ TypedBooleanAttributeArgument value ]
                    | _ ->
                        unsupported
                            "DefaultValueAttribute requires zero arguments or one boolean argument"
                | Some kind ->
                    if List.isEmpty attribute.ConstructorArguments then
                        create kind []
                    else
                        unsupported "the declaration attribute does not accept arguments"

            let typeCustomAttributes ownerStableId allowedKinds attributes =
                attributes
                |> List.mapi (typeCustomAttribute ownerStableId allowedKinds)
                |> collectResults []

            let isInlineIfLambdaParameterType =
                function
                | CliNamedType typeReference ->
                    references.IsFSharpDelegate(typeReference.DeclarationId)
                | CliGenericType(typeReference, arguments) ->
                    (arguments.Length = 2
                     && typeReference.AssemblyName = "FSharp.Core"
                     && typeReference.TypeName.Namespace = "Microsoft.FSharp.Core"
                     && typeReference.TypeName.Name = "FSharpFunc`2")
                    || references.IsFSharpDelegate(typeReference.DeclarationId)
                | _ -> false

            let attachTypedParameterAttributes
                methodStableId
                (parsedParameters: ParsedParameter list)
                (parameters: TypedParameter list)
                =
                if
                    parsedParameters.Length
                    <> parameters.Length
                then
                    invalidOp "parsed and typed parameter counts must match"

                List.zip parsedParameters parameters
                |> List.mapi (fun index (parsedParameter, parameter) ->
                    let parameterStableId =
                        methodStableId
                        + "/parameter:"
                        + index.ToString(CultureInfo.InvariantCulture)
                        + ":"
                        + parameter.Name

                    typeCustomAttributes
                        parameterStableId
                        [ InlineIfLambdaAttribute ]
                        parsedParameter.Attributes
                    |> Result.bind (fun attributes ->
                        if
                            attributes
                            |> List.exists (fun attribute ->
                                attribute.Kind = InlineIfLambdaAttribute
                            )
                            && not (isInlineIfLambdaParameterType parameter.Type)
                        then
                            Error {
                                Code = "FS3519"
                                Message =
                                    "The 'InlineIfLambda' attribute may only be used on parameters of inlined functions of methods whose type is a function or F# delegate type."
                                Path = Some sourcePath
                                Range = Some parsedParameter.Range
                            }
                        else
                            Ok {
                                parameter with
                                    Attributes = attributes
                            }
                    )
                )
                |> collectResults []

            let rec inferMethodTypeArgument
                (substitutions: CliType option array)
                templateType
                actualType
                =
                match templateType with
                | CliMethodTypeParameter index ->
                    if
                        index < 0
                        || index
                           >= substitutions.Length
                    then
                        false
                    else
                        match substitutions.[index] with
                        | None ->
                            substitutions.[index] <- Some actualType
                            true
                        | Some inferredType -> inferredType = actualType
                | CliGenericType(templateReference, templateArguments) ->
                    match actualType with
                    | CliGenericType(actualReference, actualArguments) when
                        templateReference = actualReference
                        && templateArguments.Length = actualArguments.Length
                        ->
                        (templateArguments, actualArguments)
                        ||> List.forall2 (inferMethodTypeArgument substitutions)
                    | _ -> false
                | CliByRef templateElementType ->
                    match actualType with
                    | CliByRef actualElementType ->
                        inferMethodTypeArgument substitutions templateElementType actualElementType
                    | _ -> false
                | CliArray templateElementType ->
                    match actualType with
                    | CliArray actualElementType ->
                        inferMethodTypeArgument substitutions templateElementType actualElementType
                    | _ -> false
                | _ -> templateType = actualType

            let rec substituteMethodTypeArguments (substitutions: CliType option array) =
                function
                | CliMethodTypeParameter index ->
                    substitutions.[index]
                    |> Option.defaultWith (fun () ->
                        invalidOp "a static-call method type parameter was not inferred"
                    )
                | CliGenericType(typeReference, arguments) ->
                    CliGenericType(
                        typeReference,
                        arguments
                        |> List.map (substituteMethodTypeArguments substitutions)
                    )
                | CliByRef elementType ->
                    CliByRef(substituteMethodTypeArguments substitutions elementType)
                | CliArray elementType ->
                    CliArray(substituteMethodTypeArguments substitutions elementType)
                | cliType -> cliType

            let methodAbbreviationConstraintTemplates (methodDeclaration: TypedMethodDeclaration) =
                let parameterIndex =
                    methodDeclaration.GenericParameters
                    |> List.mapi (fun index name -> name, index)
                    |> Map.ofList

                let rec toCliType =
                    function
                    | TypedTypeParameter name ->
                        parameterIndex
                        |> Map.tryFind name
                        |> Option.map CliMethodTypeParameter
                    | TypedNamedType resolvedType ->
                        Some(
                            CliNamedType {
                                DeclarationId = resolvedType.DeclarationId
                                AssemblyName = resolvedType.AssemblyName
                                TypeName = resolvedType.TypeName
                                IsValueType = resolvedType.IsValueType
                            }
                        )
                    | TypedGenericTypeApplication(TypedNamedType resolvedType, arguments) ->
                        let convertedArguments =
                            arguments
                            |> List.map toCliType

                        if
                            convertedArguments
                            |> List.forall Option.isSome
                        then
                            Some(
                                CliGenericType(
                                    {
                                        DeclarationId = resolvedType.DeclarationId
                                        AssemblyName = resolvedType.AssemblyName
                                        TypeName = {
                                            Namespace = resolvedType.TypeName.Namespace
                                            Name =
                                                resolvedType.TypeName.Name
                                                + "`"
                                                + arguments.Length.ToString(
                                                    CultureInfo.InvariantCulture
                                                )
                                        }
                                        IsValueType = resolvedType.IsValueType
                                    },
                                    convertedArguments
                                    |> List.choose id
                                )
                            )
                        else
                            None
                    | TypedByRefType elementType ->
                        toCliType elementType
                        |> Option.map CliByRef
                    | TypedGenericTypeApplication _
                    | TypedTupleType _
                    | TypedFunctionType _ -> None

                methodDeclaration.Constraints
                |> List.choose (
                    function
                    | TypedAbbreviationConstraint constraintType -> toCliType constraintType
                    | TypedDirectConstraint _ -> None
                )

            let tryInferStaticMethod
                (sourceType: CheckedSourceType)
                (methodDeclaration: TypedMethodDeclaration)
                (argumentTypes: CliType list)
                (expectedReturnType: CliType option)
                (constraintWitnesses: CliType list)
                =
                if
                    methodDeclaration.Parameters.Length
                    <> argumentTypes.Length
                then
                    None
                else
                    let substitutions = Array.create methodDeclaration.GenericParameters.Length None

                    let parametersMatch =
                        (methodDeclaration.Parameters
                         |> List.map _.Type,
                         argumentTypes)
                        ||> List.forall2 (inferMethodTypeArgument substitutions)

                    let returnTypeMatches =
                        match expectedReturnType with
                        | None -> true
                        | Some expectedReturnType ->
                            inferMethodTypeArgument
                                substitutions
                                methodDeclaration.ReturnType
                                expectedReturnType

                    let constraintTemplates =
                        methodAbbreviationConstraintTemplates methodDeclaration

                    if
                        parametersMatch
                        && returnTypeMatches
                    then
                        for constraintTemplate in constraintTemplates do
                            constraintWitnesses
                            |> List.tryPick (fun witness ->
                                let inferred = Array.copy substitutions

                                if inferMethodTypeArgument inferred constraintTemplate witness then
                                    Some inferred
                                else
                                    None
                            )
                            |> Option.iter (fun inferred ->
                                Array.blit inferred 0 substitutions 0 substitutions.Length
                            )

                    if
                        parametersMatch
                        && returnTypeMatches
                        && (substitutions
                            |> Array.forall Option.isSome)
                    then
                        let genericArguments =
                            substitutions
                            |> Array.choose id
                            |> Array.toList

                        let returnType =
                            substituteMethodTypeArguments substitutions methodDeclaration.ReturnType

                        let appliedConstraints =
                            constraintTemplates
                            |> List.map (substituteMethodTypeArguments substitutions)

                        Some(
                            {
                                DeclaringType =
                                    CliNamedType {
                                        DeclarationId = sourceType.StableId
                                        AssemblyName = String.Empty
                                        TypeName = {
                                            Namespace = sourceType.Namespace
                                            Name = sourceType.Name
                                        }
                                        IsValueType = false
                                    }
                                StableId = methodDeclaration.StableId
                                Name = methodDeclaration.Name
                                GenericArity = methodDeclaration.GenericParameters.Length
                                ParameterTypes =
                                    methodDeclaration.Parameters
                                    |> List.map _.Type
                                ReturnType = methodDeclaration.ReturnType
                            },
                            genericArguments,
                            returnType,
                            appliedConstraints
                        )
                    else
                        None

            let rec inferReferenceMethodTypeArgument
                (declaringTypeArguments: CliType list)
                (methodSubstitutions: CliType option array)
                templateType
                actualType
                =
                match templateType with
                | CliTypeParameter index ->
                    index >= 0
                    && index < declaringTypeArguments.Length
                    && declaringTypeArguments.[index] = actualType
                | CliMethodTypeParameter index ->
                    if
                        index < 0
                        || index
                           >= methodSubstitutions.Length
                    then
                        false
                    else
                        match methodSubstitutions.[index] with
                        | None ->
                            methodSubstitutions.[index] <- Some actualType
                            true
                        | Some inferredType -> inferredType = actualType
                | CliGenericType(templateReference, templateArguments) ->
                    match actualType with
                    | CliGenericType(actualReference, actualArguments) when
                        templateReference = actualReference
                        && templateArguments.Length = actualArguments.Length
                        ->
                        (templateArguments, actualArguments)
                        ||> List.forall2 (
                            inferReferenceMethodTypeArgument
                                declaringTypeArguments
                                methodSubstitutions
                        )
                    | _ -> false
                | CliByRef templateElementType ->
                    match actualType with
                    | CliByRef actualElementType ->
                        inferReferenceMethodTypeArgument
                            declaringTypeArguments
                            methodSubstitutions
                            templateElementType
                            actualElementType
                    | _ -> false
                | CliObject ->
                    match actualType with
                    | CliString
                    | CliObject
                    | CliArray _ -> true
                    | CliNamedType typeReference
                    | CliGenericType(typeReference, _) -> not typeReference.IsValueType
                    | _ -> false
                | _ -> templateType = actualType

            let rec substituteReferenceMethodTypeArguments
                (declaringTypeArguments: CliType list)
                (methodSubstitutions: CliType option array)
                =
                function
                | CliTypeParameter index ->
                    if
                        index < 0
                        || index
                           >= declaringTypeArguments.Length
                    then
                        invalidOp "a static-call declaring-type parameter was not supplied"
                    else
                        declaringTypeArguments.[index]
                | CliMethodTypeParameter index ->
                    if
                        index < 0
                        || index
                           >= methodSubstitutions.Length
                    then
                        invalidOp "a static-call method type parameter was out of range"
                    else
                        methodSubstitutions.[index]
                        |> Option.defaultWith (fun () ->
                            invalidOp "a static-call method type parameter was not inferred"
                        )
                | CliGenericType(typeReference, arguments) ->
                    CliGenericType(
                        typeReference,
                        arguments
                        |> List.map (
                            substituteReferenceMethodTypeArguments
                                declaringTypeArguments
                                methodSubstitutions
                        )
                    )
                | CliByRef elementType ->
                    CliByRef(
                        substituteReferenceMethodTypeArguments
                            declaringTypeArguments
                            methodSubstitutions
                            elementType
                    )
                | CliArray elementType ->
                    CliArray(
                        substituteReferenceMethodTypeArguments
                            declaringTypeArguments
                            methodSubstitutions
                            elementType
                    )
                | cliType -> cliType

            let tryInferReferenceStaticMethod
                declaringType
                declaringTypeArguments
                (methodDefinition: ReferenceMethodDefinition)
                (argumentTypes: CliType list)
                (expectedReturnType: CliType option)
                =
                let requiredParameterCount =
                    methodDefinition.ParameterTypes.Length
                    - methodDefinition.OptionalParameterCount

                if
                    argumentTypes.Length < requiredParameterCount
                    || argumentTypes.Length > methodDefinition.ParameterTypes.Length
                then
                    None
                else
                    let methodSubstitutions = Array.create methodDefinition.GenericArity None

                    let providedParameterTypes =
                        methodDefinition.ParameterTypes
                        |> List.truncate argumentTypes.Length

                    let parametersMatch =
                        (providedParameterTypes, argumentTypes)
                        ||> List.forall2 (
                            inferReferenceMethodTypeArgument
                                declaringTypeArguments
                                methodSubstitutions
                        )

                    let returnTypeMatches =
                        match expectedReturnType with
                        | None -> true
                        | Some expectedReturnType ->
                            inferReferenceMethodTypeArgument
                                declaringTypeArguments
                                methodSubstitutions
                                methodDefinition.ReturnType
                                expectedReturnType

                    if
                        parametersMatch
                        && returnTypeMatches
                        && (methodSubstitutions
                            |> Array.forall Option.isSome)
                    then
                        let genericArguments =
                            methodSubstitutions
                            |> Array.choose id
                            |> Array.toList

                        let returnType =
                            substituteReferenceMethodTypeArguments
                                declaringTypeArguments
                                methodSubstitutions
                                methodDefinition.ReturnType

                        Some(
                            {
                                DeclaringType = declaringType
                                StableId = methodDefinition.StableId
                                Name = methodDefinition.Name
                                GenericArity = methodDefinition.GenericArity
                                ParameterTypes = methodDefinition.ParameterTypes
                                ReturnType = methodDefinition.ReturnType
                            },
                            genericArguments,
                            returnType
                        )
                    else
                        None

            let tryInferNamedReferenceStaticMethod
                declaringType
                declaringTypeArguments
                (methodDefinition: ReferenceMethodDefinition)
                (arguments: (string option * CliType) list)
                =
                let parameterCount = methodDefinition.ParameterTypes.Length

                let requiredParameterCount =
                    parameterCount
                    - methodDefinition.OptionalParameterCount

                if arguments.Length > parameterCount then
                    None
                else
                    let assignments = Array.create parameterCount false
                    let methodSubstitutions = Array.create methodDefinition.GenericArity None
                    let bindings = ResizeArray<int * CliType option>()
                    let mutable nextPositionalIndex = 0
                    let mutable sawNamedArgument = false
                    let mutable matches = true

                    let tryOptionalValueType =
                        function
                        | CliGenericType(typeReference, [ valueType ]) when
                            typeReference.AssemblyName = "FSharp.Core"
                            && typeReference.TypeName.Namespace = "Microsoft.FSharp.Core"
                            && typeReference.TypeName.Name = "FSharpOption`1"
                            ->
                            Some valueType
                        | _ -> None

                    for argumentName, argumentType in arguments do
                        let parameterIndex =
                            match argumentName with
                            | Some name ->
                                sawNamedArgument <- true

                                methodDefinition.MetadataParameterNames
                                |> List.tryFindIndex (fun parameterName -> parameterName = name)
                            | None when sawNamedArgument -> None
                            | None ->
                                while (nextPositionalIndex < parameterCount
                                       && assignments.[nextPositionalIndex]) do
                                    nextPositionalIndex <-
                                        nextPositionalIndex
                                        + 1

                                if nextPositionalIndex < parameterCount then
                                    Some nextPositionalIndex
                                else
                                    None

                        match parameterIndex with
                        | None -> matches <- false
                        | Some index when assignments.[index] -> matches <- false
                        | Some index ->
                            assignments.[index] <- true

                            if argumentName.IsNone then
                                nextPositionalIndex <- index + 1

                            let parameterType = methodDefinition.ParameterTypes.[index]

                            let isOptionalParameter =
                                index
                                >= requiredParameterCount

                            let inferenceType, optionalWrapperType =
                                match argumentName, isOptionalParameter with
                                | Some _, true ->
                                    match tryOptionalValueType parameterType with
                                    | Some valueType -> valueType, Some parameterType
                                    | None ->
                                        matches <- false
                                        parameterType, None
                                | _ -> parameterType, None

                            if
                                not (
                                    inferReferenceMethodTypeArgument
                                        declaringTypeArguments
                                        methodSubstitutions
                                        inferenceType
                                        argumentType
                                )
                            then
                                matches <- false

                            bindings.Add(index, optionalWrapperType)

                    if
                        matches
                        && (assignments
                            |> Array.take requiredParameterCount
                            |> Array.forall id)
                        && (methodSubstitutions
                            |> Array.forall Option.isSome)
                    then
                        let genericArguments =
                            methodSubstitutions
                            |> Array.choose id
                            |> Array.toList

                        let substitute =
                            substituteReferenceMethodTypeArguments
                                declaringTypeArguments
                                methodSubstitutions

                        let returnType = substitute methodDefinition.ReturnType

                        Some(
                            {
                                DeclaringType = declaringType
                                StableId = methodDefinition.StableId
                                Name = methodDefinition.Name
                                GenericArity = methodDefinition.GenericArity
                                ParameterTypes = methodDefinition.ParameterTypes
                                ReturnType = methodDefinition.ReturnType
                            },
                            genericArguments,
                            returnType,
                            (bindings
                             |> Seq.map (fun (index, wrapperType) ->
                                 index,
                                 wrapperType
                                 |> Option.map substitute
                             )
                             |> List.ofSeq)
                        )
                    else
                        None

            let tryApplyExplicitMethodTypeArguments
                (genericArity: int)
                (parameterTypes: CliType list)
                (optionalParameterCount: int)
                returnType
                (genericArguments: CliType list)
                (argumentTypes: CliType list)
                =
                let requiredParameterCount =
                    parameterTypes.Length
                    - optionalParameterCount

                if
                    genericArity
                    <> genericArguments.Length
                    || argumentTypes.Length < requiredParameterCount
                    || argumentTypes.Length > parameterTypes.Length
                then
                    None
                else
                    let substitutions =
                        genericArguments
                        |> List.map Some
                        |> List.toArray

                    let parametersMatch =
                        (parameterTypes
                         |> List.truncate argumentTypes.Length,
                         argumentTypes)
                        ||> List.forall2 (inferMethodTypeArgument substitutions)

                    if parametersMatch then
                        Some(substituteMethodTypeArguments substitutions returnType)
                    else
                        None

            let tryApplyExplicitSourceStaticMethod
                (sourceType: CheckedSourceType)
                (methodDeclaration: TypedMethodDeclaration)
                genericArguments
                argumentTypes
                =
                tryApplyExplicitMethodTypeArguments
                    methodDeclaration.GenericParameters.Length
                    (methodDeclaration.Parameters
                     |> List.map _.Type)
                    0
                    methodDeclaration.ReturnType
                    genericArguments
                    argumentTypes
                |> Option.map (fun returnType ->
                    {
                        DeclaringType =
                            CliNamedType {
                                DeclarationId = sourceType.StableId
                                AssemblyName = String.Empty
                                TypeName = {
                                    Namespace = sourceType.Namespace
                                    Name = sourceType.Name
                                }
                                IsValueType = false
                            }
                        StableId = methodDeclaration.StableId
                        Name = methodDeclaration.Name
                        GenericArity = methodDeclaration.GenericParameters.Length
                        ParameterTypes =
                            methodDeclaration.Parameters
                            |> List.map _.Type
                        ReturnType = methodDeclaration.ReturnType
                    },
                    genericArguments,
                    returnType
                )

            let tryApplyExplicitReferenceStaticMethod
                declaringType
                (methodDefinition: ReferenceMethodDefinition)
                genericArguments
                argumentTypes
                =
                tryApplyExplicitMethodTypeArguments
                    methodDefinition.GenericArity
                    methodDefinition.ParameterTypes
                    methodDefinition.OptionalParameterCount
                    methodDefinition.ReturnType
                    genericArguments
                    argumentTypes
                |> Option.map (fun returnType ->
                    {
                        DeclaringType = declaringType
                        StableId = methodDefinition.StableId
                        Name = methodDefinition.Name
                        GenericArity = methodDefinition.GenericArity
                        ParameterTypes = methodDefinition.ParameterTypes
                        ReturnType = methodDefinition.ReturnType
                    },
                    genericArguments,
                    returnType
                )

            let resolveStaticMethod
                (constraintWitnesses: ResizeArray<CliType>)
                receiverName
                memberName
                argumentTypes
                expectedReturnType
                range
                =
                let visibleNamespaces =
                    parsed.Namespace
                    :: parsed.OpenedNamespaces
                    |> Set.ofList

                let visibleSourceTypes =
                    checkedSourceTypes
                    |> Seq.filter (fun sourceType ->
                        sourceType.Name = receiverName
                        && visibleNamespaces.Contains(sourceType.Namespace)
                    )

                let sourceCandidates =
                    visibleSourceTypes
                    |> Seq.collect (fun sourceType ->
                        sourceType.Methods
                        |> Seq.choose (fun methodDeclaration ->
                            if methodDeclaration.Name = memberName then
                                tryInferStaticMethod
                                    sourceType
                                    methodDeclaration
                                    argumentTypes
                                    expectedReturnType
                                    (constraintWitnesses
                                     |> Seq.toList)
                            else
                                None
                        )
                    )
                    |> Seq.toList

                let candidates =
                    if
                        visibleSourceTypes
                        |> Seq.isEmpty
                    then
                        match
                            references.Resolve(
                                parsed.Namespace,
                                parsed.OpenedNamespaces,
                                {
                                    Namespace = String.Empty
                                    Name = receiverName
                                },
                                0
                            )
                        with
                        | Error _ -> []
                        | Ok resolvedType ->
                            let referenceCandidates =
                                references.Methods(resolvedType.DeclarationId, memberName, true)
                                |> List.choose (fun methodDefinition ->
                                    tryInferReferenceStaticMethod
                                        (CliNamedType methodDefinition.DeclaringType)
                                        []
                                        methodDefinition
                                        argumentTypes
                                        expectedReturnType
                                )
                                |> List.map (fun (target, genericArguments, returnType) ->
                                    target, genericArguments, returnType, []
                                )

                            let intrinsicCandidates =
                                match
                                    resolvedType.TypeName.Namespace,
                                    resolvedType.TypeName.Name,
                                    memberName,
                                    argumentTypes
                                with
                                | "System", "Object", "ReferenceEquals", [ CliObject; CliObject ]
                                | "System", "Object", "__fsharp2_isNull", [ CliObject; CliObject ] -> [
                                    {
                                        DeclaringType =
                                            CliNamedType {
                                                DeclarationId = resolvedType.DeclarationId
                                                AssemblyName = resolvedType.AssemblyName
                                                TypeName = resolvedType.TypeName
                                                IsValueType = resolvedType.IsValueType
                                            }
                                        StableId =
                                            resolvedType.DeclarationId
                                            + "|method|ReferenceEquals|generic|0|object|object|return|bool"
                                            + (if memberName = "__fsharp2_isNull" then
                                                   "|intrinsic|isNull"
                                               else
                                                   String.Empty)
                                        Name = "ReferenceEquals"
                                        GenericArity = 0
                                        ParameterTypes = [
                                            CliObject
                                            CliObject
                                        ]
                                        ReturnType = CliBoolean
                                    },
                                    [],
                                    CliBoolean,
                                    []
                                  ]
                                | _ -> []

                            intrinsicCandidates
                            @ referenceCandidates
                            |> List.distinctBy (fun
                                                    (methodReference,
                                                     genericArguments,
                                                     returnType,
                                                     _) ->
                                methodReference.StableId, genericArguments, returnType
                            )
                    else
                        sourceCandidates

                match candidates with
                | [ target, genericArguments, returnType, appliedConstraints ] ->
                    for appliedConstraint in appliedConstraints do
                        if not (constraintWitnesses.Contains(appliedConstraint)) then
                            constraintWitnesses.Add(appliedConstraint)

                    Ok(target, genericArguments, returnType)
                | [] ->
                    diagnostic
                        range
                        $"no visible static member '{receiverName}.{memberName}' matches the argument types"
                | _ ->
                    diagnostic
                        range
                        $"the static member call '{receiverName}.{memberName}' is ambiguous"

            let resolveNamedReferenceStaticMethod receiverName memberName argumentTypes range =
                match
                    references.Resolve(
                        parsed.Namespace,
                        parsed.OpenedNamespaces,
                        {
                            Namespace = String.Empty
                            Name = receiverName
                        },
                        0
                    )
                with
                | Error _ ->
                    diagnostic
                        range
                        $"no visible static member '{receiverName}.{memberName}' matches the named arguments"
                | Ok resolvedType ->
                    let candidates =
                        references.Methods(resolvedType.DeclarationId, memberName, true)
                        |> List.choose (fun methodDefinition ->
                            tryInferNamedReferenceStaticMethod
                                (CliNamedType methodDefinition.DeclaringType)
                                []
                                methodDefinition
                                argumentTypes
                        )

                    match candidates with
                    | [ candidate ] -> Ok candidate
                    | [] ->
                        diagnostic
                            range
                            $"no visible static member '{receiverName}.{memberName}' matches the named arguments"
                    | _ ->
                        diagnostic
                            range
                            $"the static member call '{receiverName}.{memberName}' is ambiguous"

            let resolveStaticMethodOnType declaringType memberName argumentTypes range =
                let typeOwner =
                    match declaringType with
                    | CliNamedType typeReference -> Some(typeReference, [])
                    | CliGenericType(typeReference, typeArguments) ->
                        Some(typeReference, typeArguments)
                    | _ -> None

                match typeOwner with
                | None ->
                    diagnostic
                        range
                        $"the static member receiver '{TypeIdentity.cliType declaringType}' is not a named type"
                | Some(typeReference, typeArguments) ->
                    let indexedMethods =
                        references.Methods(typeReference.DeclarationId, memberName, true)

                    let candidates =
                        indexedMethods
                        |> List.choose (fun methodDefinition ->
                            tryInferReferenceStaticMethod
                                declaringType
                                typeArguments
                                methodDefinition
                                argumentTypes
                                None
                        )

                    match candidates with
                    | [ candidate ] -> Ok candidate
                    | [] ->
                        diagnostic
                            range
                            $"no static member '{TypeIdentity.cliType declaringType}.{memberName}' matches the argument types"
                    | _ ->
                        diagnostic
                            range
                            $"the static member call '{TypeIdentity.cliType declaringType}.{memberName}' is ambiguous"

            let resolveExplicitStaticMethod
                receiverName
                memberName
                genericArguments
                argumentTypes
                range
                =
                let visibleNamespaces =
                    parsed.Namespace
                    :: parsed.OpenedNamespaces
                    |> Set.ofList

                let visibleSourceTypes =
                    checkedSourceTypes
                    |> Seq.filter (fun sourceType ->
                        sourceType.Name = receiverName
                        && visibleNamespaces.Contains(sourceType.Namespace)
                    )

                let sourceCandidates =
                    visibleSourceTypes
                    |> Seq.collect (fun sourceType ->
                        sourceType.Methods
                        |> Seq.choose (fun methodDeclaration ->
                            if methodDeclaration.Name = memberName then
                                tryApplyExplicitSourceStaticMethod
                                    sourceType
                                    methodDeclaration
                                    genericArguments
                                    argumentTypes
                            else
                                None
                        )
                    )
                    |> Seq.toList

                let candidates =
                    if
                        visibleSourceTypes
                        |> Seq.isEmpty
                    then
                        match
                            references.Resolve(
                                parsed.Namespace,
                                parsed.OpenedNamespaces,
                                {
                                    Namespace = String.Empty
                                    Name = receiverName
                                },
                                0
                            )
                        with
                        | Error _ -> []
                        | Ok resolvedType ->
                            references.Methods(resolvedType.DeclarationId, memberName, true)
                            |> List.choose (fun methodDefinition ->
                                tryApplyExplicitReferenceStaticMethod
                                    (CliNamedType methodDefinition.DeclaringType)
                                    methodDefinition
                                    genericArguments
                                    argumentTypes
                            )
                    else
                        sourceCandidates

                match candidates with
                | [ candidate ] -> Ok candidate
                | [] ->
                    diagnostic
                        range
                        $"no visible static member '{receiverName}.{memberName}' matches the explicit type and argument types"
                | _ ->
                    diagnostic
                        range
                        $"the static member call '{receiverName}.{memberName}' is ambiguous"

            let rec typeDeclaration =
                function
                | ParsedMethod declaration when
                    match declaration.Kind, declaration.Body with
                    | ParsedMethodKind.EntryPoint _, _
                    | ParsedMethodKind.RegularFunction _, _
                    | ParsedMethodKind.RegularTypedFunction _, _
                    | ParsedMethodKind.Regular, FunctionApplication _ -> true
                    | _ -> false
                    ->
                    let isEntryPoint =
                        match declaration.Kind with
                        | ParsedMethodKind.EntryPoint _ -> true
                        | ParsedMethodKind.Regular
                        | ParsedMethodKind.RegularFunction _
                        | ParsedMethodKind.RegularTypedFunction _ -> false

                    let parameter =
                        match declaration.Kind with
                        | ParsedMethodKind.EntryPoint parameterName
                        | ParsedMethodKind.RegularFunction parameterName ->
                            Some(parameterName, ParsedWildcardType declaration.Range)
                        | ParsedMethodKind.RegularTypedFunction(parameterName, parameterType) ->
                            Some(parameterName, parameterType)
                        | ParsedMethodKind.Regular -> None

                    let syntheticObjectType =
                        ParsedObjectType {
                            Container = OrdinaryObjectType
                            Name = parsed.Name
                            BaseType = None
                            Methods = [
                                ParsedStaticObjectMethod {
                                    Attributes = []
                                    IsEntryPoint = isEntryPoint
                                    IsInline = false
                                    IsPublic = true
                                    Name = declaration.Name
                                    TypeParameters = []
                                    Constraints = []
                                    ArgumentCounts =
                                        match parameter with
                                        | Some _ -> [ 1 ]
                                        | None -> []
                                    Parameters =
                                        match parameter with
                                        | Some(parameterName, parameterType) -> [
                                            {
                                                Attributes = []
                                                Name = parameterName
                                                Type = parameterType
                                                Range = parameterType.Range
                                            }
                                          ]
                                        | None -> []
                                    ReturnType = None
                                    Body = declaration.Body
                                    BodyRange = declaration.BodyRange
                                    Range = declaration.Range
                                }
                            ]
                            ConstructorRange = declaration.Range
                            Range = declaration.Range
                        }

                    typeDeclaration syntheticObjectType
                    |> Result.bind (fun typedDeclaration ->
                        match typedDeclaration with
                        | TypedObjectType {
                                              Methods = [ TypedStaticObjectMethod typedMethod ]
                                          } when not isEntryPoint ->
                            match declaration.DeclaredType, typedMethod.ReturnType with
                            | None, _
                            | Some ParsedInt32, CliInt32 -> Ok(TypedMethod typedMethod)
                            | Some ParsedInt32, CliString ->
                                let mismatchRange =
                                    match declaration.Body with
                                    | FunctionApplication(_, StringLiteral value) ->
                                        let literalLength =
                                            value.Length
                                            + 2

                                        {
                                            Start = {
                                                declaration.BodyRange.End with
                                                    Offset =
                                                        declaration.BodyRange.End.Offset
                                                        - literalLength
                                                    Column =
                                                        declaration.BodyRange.End.Column
                                                        - literalLength
                                            }
                                            End = declaration.BodyRange.End
                                        }
                                    | _ -> declaration.BodyRange

                                Error {
                                    Code = "FS0001"
                                    Message =
                                        String.concat Environment.NewLine [
                                            "This expression was expected to have type"
                                            "    'int'    "
                                            "but here has type"
                                            "    'string'"
                                        ]
                                    Path = Some sourcePath
                                    Range = Some mismatchRange
                                }
                            | Some ParsedInt32, _ ->
                                diagnostic
                                    declaration.BodyRange
                                    "the method body does not match its declared integer type"
                        | TypedObjectType {
                                              Methods = [ TypedStaticObjectMethod({
                                                                                      ReturnType = CliInt32
                                                                                  } as typedMethod) ]
                                          } ->
                            Ok(
                                TypedMethod {
                                    typedMethod with
                                        StableId =
                                            typedMethod.StableId
                                            + "/entry-point"
                                        ExportFingerprint =
                                            Fingerprint.parts [
                                                typedMethod.ExportFingerprint
                                                "entry-point"
                                            ]
                                }
                            )
                        | TypedObjectType {
                                              Methods = [ TypedStaticObjectMethod _ ]
                                          } ->
                            diagnostic
                                declaration.BodyRange
                                "an entry-point body must return an integer exit code"
                        | _ ->
                            diagnostic
                                declaration.Range
                                "the shared static-member checker returned an invalid entry point"
                    )
                | ParsedMethod declaration ->
                    match declaration.DeclaredType, declaration.Body with
                    | Some ParsedInt32, StringLiteral _ ->
                        Error {
                            Code = "FS0001"
                            Message =
                                String.concat Environment.NewLine [
                                    "This expression was expected to have type"
                                    "    'int'    "
                                    "but here has type"
                                    "    'string'"
                                ]
                            Path = Some sourcePath
                            Range = Some declaration.BodyRange
                        }

                    | _, IntegerLiteral value ->
                        let stableId =
                            parsed.StableId
                            + "/method:"
                            + declaration.Name
                            + (if declaration.IsUnitFunction then
                                   ":unit->int32"
                               else
                                   ":int32")

                        let exportFingerprint = Fingerprint.text stableId

                        Ok(
                            TypedMethod {
                                StableId = stableId
                                Name = declaration.Name
                                IsPublic = true
                                GenericParameters = []
                                Constraints = []
                                Attributes = []
                                Parameters = []
                                ReturnType = CliInt32
                                Body = TypedIntegerLiteral value
                                EmitHiddenEntrySequencePoint = false
                                ExportFingerprint = exportFingerprint
                                Range =
                                    if declaration.IsUnitFunction then
                                        declaration.BodyRange
                                    else
                                        declaration.Range
                            }
                        )
                    | None, StringLiteral _ ->
                        Error {
                            Code = "FSC2P1001"
                            Message =
                                "string-valued declarations are not yet supported by the prototype"
                            Path = Some sourcePath
                            Range = Some declaration.BodyRange
                        }
                    | _, MemberCall _ ->
                        diagnostic
                            declaration.BodyRange
                            "trait calls are supported only in static inline members"
                    | _, ValueReference _
                    | _, NamedCallArgument _
                    | _, AddressOfExpression _
                    | _, UnitApplication _ ->
                        diagnostic
                            declaration.BodyRange
                            "value references are supported only in parameterized members"
                    | _, UnitLiteral
                    | _, BooleanLiteral _
                    | _, NullLiteral
                    | _, GenericMemberCall _
                    | _, StaticTypeMemberCall _
                    | _, BoundInstanceMember _
                    | _, MemberAssignment _
                    | _, SequentialExpression _
                    | _, FunctionApplication _
                    | _, ExpressionMemberCall _
                    | _, ExpressionMemberAccess _
                    | _, ConditionalExpression _
                    | _, ExplicitUpcastExpression _
                    | _, SequentialValueExpression _
                    | _, LocalAssignment _
                    | _, BooleanNegationExpression _
                    | _, EqualityExpression _
                    | _, TryWithExpression _
                    | _, TryFinallyExpression _
                    | _, LetExpression _
                    | _, ComputationExpression _
                    | _, ComputationBindingExpression _
                    | _, ComputationDoExpression _
                    | _, WhileExpression _
                    | _, ForExpression _
                    | _, LambdaExpression _
                    | _, UnitLambdaExpression _
                    | _, TupleExpression _
                    | _, StructTupleExpression _
                    | _, TypeConstruction _
                    | _, BindReturnFromComputation _
                    | _, ObjectExpression _
                    | _, MatchExpression _ ->
                        diagnostic
                            declaration.BodyRange
                            "this expression form is supported only in instance members"
                | ParsedLiteralField declaration ->
                    let stableId =
                        parsed.StableId
                        + "/literal-field:"
                        + declaration.Name

                    Ok(
                        TypedLiteralField {
                            StableId = stableId
                            Name = declaration.Name
                            Value = declaration.Value
                            ExportFingerprint =
                                Fingerprint.text (
                                    stableId
                                    + "="
                                    + declaration.Value
                                )
                        }
                    )
                | ParsedNestedModule declaration ->
                    let stableId =
                        (parsed.StableId, declaration.ModulePath)
                        ||> List.fold (fun parentStableId moduleName ->
                            parentStableId
                            + "/nested-module:"
                            + moduleName
                        )

                    let compiledName =
                        let key = ReferenceTypeName.simpleKey declaration.Name 0

                        if localTypes.ContainsKey(key) then
                            declaration.Name
                            + "Module"
                        else
                            declaration.Name

                    let rec toClosedCliType range =
                        function
                        | TypedNamedType resolvedType when
                            resolvedType.TypeName.Namespace = "System"
                            && resolvedType.TypeName.Name = "Int32"
                            ->
                            Ok CliInt32
                        | TypedNamedType resolvedType when
                            resolvedType.TypeName.Namespace = "System"
                            && resolvedType.TypeName.Name = "Boolean"
                            ->
                            Ok CliBoolean
                        | TypedNamedType resolvedType when
                            resolvedType.TypeName.Namespace = "System"
                            && resolvedType.TypeName.Name = "String"
                            ->
                            Ok CliString
                        | TypedNamedType resolvedType when
                            resolvedType.TypeName.Namespace = "System"
                            && resolvedType.TypeName.Name = "Object"
                            ->
                            Ok CliObject
                        | TypedNamedType resolvedType ->
                            Ok(
                                CliNamedType {
                                    DeclarationId = resolvedType.DeclarationId
                                    AssemblyName = resolvedType.AssemblyName
                                    TypeName = resolvedType.TypeName
                                    IsValueType = resolvedType.IsValueType
                                }
                            )
                        | TypedGenericTypeApplication(TypedNamedType resolvedType, arguments) ->
                            arguments
                            |> List.map (toClosedCliType range)
                            |> collectResults []
                            |> Result.map (fun argumentTypes ->
                                CliGenericType(
                                    {
                                        DeclarationId = resolvedType.DeclarationId
                                        AssemblyName = resolvedType.AssemblyName
                                        TypeName = {
                                            Namespace = resolvedType.TypeName.Namespace
                                            Name =
                                                resolvedType.TypeName.Name
                                                + "`"
                                                + arguments.Length.ToString(
                                                    CultureInfo.InvariantCulture
                                                )
                                        }
                                        IsValueType = resolvedType.IsValueType
                                    },
                                    argumentTypes
                                )
                            )
                        | typedType ->
                            diagnostic
                                range
                                $"the nested-module value type '{TypeIdentity.expression typedType}' is not yet supported"

                    let typeConstruction constructedType range =
                        let resolvedType =
                            constructedType
                            |> expandTypeAbbreviations Set.empty
                            |> resolveType (HashSet<string>(StringComparer.Ordinal))
                            |> Result.bind (toClosedCliType range)

                        resolvedType
                        |> Result.bind (fun constructedCliType ->
                            let declaringType, declaringTypeArguments =
                                match constructedCliType with
                                | CliNamedType typeReference -> Some typeReference, []
                                | CliGenericType(typeReference, arguments) ->
                                    Some typeReference, arguments
                                | _ -> None, []

                            let localCandidate =
                                declaringType
                                |> Option.bind (fun typeReference ->
                                    if
                                        List.isEmpty declaringTypeArguments
                                        && (checkedSourceTypes
                                            |> Seq.exists (fun sourceType ->
                                                sourceType.StableId = typeReference.DeclarationId
                                            ))
                                    then
                                        Some {
                                            DeclaringType = constructedCliType
                                            StableId =
                                                typeReference.DeclarationId
                                                + "/constructor:unit"
                                            ParameterTypes = []
                                            ParamArrayElementType = None
                                        }
                                    else
                                        None
                                )

                            let referenceCandidates =
                                declaringType
                                |> Option.map (fun typeReference ->
                                    references.Methods(
                                        typeReference.DeclarationId,
                                        ".ctor",
                                        false
                                    )
                                    |> List.choose (fun constructor ->
                                        if
                                            constructor.GenericArity = 0
                                            && List.isEmpty constructor.ParameterTypes
                                        then
                                            Some {
                                                DeclaringType = constructedCliType
                                                StableId = constructor.StableId
                                                ParameterTypes = []
                                                ParamArrayElementType = None
                                            }
                                        else
                                            None
                                    )
                                )
                                |> Option.defaultValue []

                            match localCandidate, referenceCandidates with
                            | Some target, [] -> Ok(target, constructedCliType)
                            | None, [ target ] -> Ok(target, constructedCliType)
                            | None, [] ->
                                diagnostic
                                    range
                                    "no visible parameterless constructor matches the nested-module value"
                            | _ ->
                                diagnostic range "the nested-module value constructor is ambiguous"
                        )

                    let rec typeValues
                        (bindings: Map<string, TypedModuleValueDeclaration>)
                        (completed: TypedModuleValueDeclaration list)
                        (remainingValues: ParsedModuleValueDeclaration list)
                        =
                        match remainingValues with
                        | [] -> Ok(List.rev completed)
                        | value :: remaining when
                            bindings
                            |> Map.containsKey value.Name
                            ->
                            diagnostic value.Range $"the module value '{value.Name}' is duplicated"
                        | value :: remaining ->
                            let valueStableId =
                                stableId
                                + "/value:"
                                + value.Name

                            let typedValue =
                                match value.Body with
                                | TypeConstruction(constructedType, [], argumentRange) ->
                                    typeConstruction constructedType argumentRange
                                    |> Result.map (fun (target, valueType) ->
                                        valueType, TypedModuleValueConstruction target
                                    )
                                | UnitApplication constructedTypeName ->
                                    typeConstruction
                                        (ParsedNamedType(
                                            {
                                                Namespace = String.Empty
                                                Name = constructedTypeName
                                            },
                                            value.BodyRange
                                        ))
                                        value.BodyRange
                                    |> Result.map (fun (target, valueType) ->
                                        valueType, TypedModuleValueConstruction target
                                    )
                                | ValueReference targetName ->
                                    match
                                        bindings
                                        |> Map.tryFind targetName
                                    with
                                    | Some target ->
                                        Ok(target.Type, TypedModuleValueAlias target.StableId)
                                    | None ->
                                        diagnostic
                                            value.BodyRange
                                            $"the module value '{targetName}' is not defined before this binding"
                                | _ ->
                                    diagnostic
                                        value.BodyRange
                                        "nested-module values currently require a parameterless construction or an earlier value alias"

                            match typedValue with
                            | Error error -> Error error
                            | Ok(valueType, initializer) ->
                                let typed: TypedModuleValueDeclaration = {
                                    StableId = valueStableId
                                    Name = value.Name
                                    Type = valueType
                                    Initializer = initializer
                                    ExportFingerprint =
                                        Fingerprint.parts [
                                            valueStableId
                                            "type"
                                            TypeIdentity.cliType valueType
                                        ]
                                    Range = value.Range
                                }

                                typeValues
                                    (bindings
                                     |> Map.add value.Name typed)
                                    (typed
                                     :: completed)
                                    remaining

                    let typeMethods () =
                        match declaration.Methods with
                        | [] -> Ok []
                        | methods ->
                            let syntheticObjectType =
                                ParsedObjectType {
                                    Container = OrdinaryObjectType
                                    Name =
                                        declaration.Name
                                        + "ModuleFunctions"
                                    BaseType = None
                                    Methods =
                                        methods
                                        |> List.map ParsedStaticObjectMethod
                                    ConstructorRange = declaration.Range
                                    Range = declaration.Range
                                }

                            typeDeclaration syntheticObjectType
                            |> Result.bind (fun typedDeclaration ->
                                match typedDeclaration with
                                | TypedObjectType typedObjectType ->
                                    typedObjectType.Methods
                                    |> List.map (fun methodDeclaration ->
                                        match methodDeclaration with
                                        | TypedStaticObjectMethod typedMethod -> Ok typedMethod
                                        | TypedInstanceObjectMethod _ ->
                                            diagnostic
                                                declaration.Range
                                                "a nested-module function was typed as an instance member"
                                    )
                                    |> collectResults []
                                | _ ->
                                    diagnostic
                                        declaration.Range
                                        "a nested-module function did not produce a method container"
                            )

                    let typeModules () =
                        declaration.Modules
                        |> List.map (fun nestedModule ->
                            typeDeclaration (ParsedNestedModule nestedModule)
                            |> Result.bind (fun typedDeclaration ->
                                match typedDeclaration with
                                | TypedNestedModule typedModule -> Ok typedModule
                                | _ ->
                                    diagnostic
                                        nestedModule.Range
                                        "a recursive nested module did not produce a module declaration"
                            )
                        )
                        |> collectResults []

                    let typeExtensions () =
                        declaration.Extensions
                        |> List.map (fun extension ->
                            typeDeclaration (ParsedObjectType extension)
                            |> Result.bind (fun typedDeclaration ->
                                match typedDeclaration with
                                | TypedObjectType typedExtension -> Ok typedExtension
                                | _ ->
                                    diagnostic
                                        extension.Range
                                        "a nested-module augmentation did not produce an extension declaration"
                            )
                        )
                        |> collectResults []

                    match
                        typeCustomAttributes
                            stableId
                            [
                                AutoOpenAttribute
                                RequireQualifiedAccessAttribute
                            ]
                            declaration.Attributes,
                        typeValues Map.empty [] declaration.Values,
                        typeMethods (),
                        typeExtensions (),
                        typeModules ()
                    with
                    | Error error, _, _, _, _
                    | _, Error error, _, _, _
                    | _, _, Error error, _, _
                    | _, _, _, Error error, _
                    | _, _, _, _, Error error -> Error error
                    | Ok attributes, Ok values, Ok methods, Ok extensions, Ok modules ->
                        Ok(
                            TypedNestedModule {
                                StableId = stableId
                                Name = declaration.Name
                                CompiledName = compiledName
                                Attributes = attributes
                                Values = values
                                Methods = methods
                                Extensions = extensions
                                Modules = modules
                                ExportFingerprint =
                                    Fingerprint.parts [
                                        stableId
                                        "compiled-name"
                                        compiledName
                                        "attributes"

                                        yield!
                                            attributes
                                            |> List.map _.ExportFingerprint

                                        "values"

                                        yield!
                                            values
                                            |> List.map _.ExportFingerprint

                                        "methods"

                                        yield!
                                            methods
                                            |> List.map _.ExportFingerprint

                                        "extensions"

                                        yield!
                                            extensions
                                            |> List.map _.ExportFingerprint

                                        "modules"

                                        yield!
                                            modules
                                            |> List.map _.ExportFingerprint
                                    ]
                                Range = declaration.Range
                            }
                        )
                | ParsedTypeAbbreviation declaration ->
                    let stableId =
                        parsed.StableId
                        + "/type-abbreviation:"
                        + declaration.Name

                    let declaredParameters =
                        HashSet<string>(declaration.TypeParameters, StringComparer.Ordinal)

                    let resolveConstraint =
                        function
                        | ParsedSubtypeConstraint(typeParameter, superType, range) ->
                            if not (declaredParameters.Contains(typeParameter)) then
                                diagnostic
                                    range
                                    $"the constrained type parameter '{typeParameter}' is not declared"
                            else
                                resolveType declaredParameters superType
                                |> Result.map (fun typedSuperType ->
                                    TypedSubtypeConstraint(typeParameter, typedSuperType)
                                )
                        | ParsedMemberConstraint(typeParameter, memberName, memberType, range) ->
                            if not (declaredParameters.Contains(typeParameter)) then
                                diagnostic
                                    range
                                    $"the constrained type parameter '{typeParameter}' is not declared"
                            else
                                resolveType declaredParameters memberType
                                |> Result.map (fun typedMemberType ->
                                    TypedMemberConstraint(
                                        typeParameter,
                                        memberName,
                                        typedMemberType
                                    )
                                )

                    let rec resolveConstraints resolved =
                        function
                        | [] -> Ok(List.rev resolved)
                        | constraint' :: remaining ->
                            match resolveConstraint constraint' with
                            | Error error -> Error error
                            | Ok typedConstraint ->
                                resolveConstraints
                                    (typedConstraint
                                     :: resolved)
                                    remaining

                    if
                        declaredParameters.Count
                        <> declaration.TypeParameters.Length
                    then
                        diagnostic declaration.Range "generic type parameters must be unique"
                    else
                        match resolveConstraints [] declaration.Constraints with
                        | Error error -> Error error
                        | Ok constraints ->
                            match resolveType declaredParameters declaration.Target.Type with
                            | Error error -> Error error
                            | Ok targetType ->
                                let targetIdentity =
                                    Fingerprint.parts [
                                        stableId
                                        "parameters"
                                        yield! declaration.TypeParameters
                                        "constraints"

                                        yield!
                                            constraints
                                            |> List.map TypeIdentity.constraintIdentity

                                        "target"
                                        TypeIdentity.expression targetType
                                        if declaration.Target.AllowsNull then "null" else "non-null"
                                    ]

                                Ok(
                                    TypedTypeAbbreviation {
                                        StableId = stableId
                                        Name = declaration.Name
                                        TypeParameters = declaration.TypeParameters
                                        Constraints = constraints
                                        TargetType = targetType
                                        AllowsNull = declaration.Target.AllowsNull
                                        ExportFingerprint = targetIdentity
                                        Range = declaration.Range
                                    }
                                )
                | ParsedStaticType declaration ->
                    let stableId =
                        parsed.StableId
                        + "/type:"
                        + declaration.Name

                    let typeConstrainedMethod (methodDeclaration: ParsedStaticMethodDeclaration) =
                        let explicitTypeParametersAreUnique =
                            (methodDeclaration.TypeParameters
                             |> Set.ofList
                             |> Set.count) = methodDeclaration.TypeParameters.Length

                        let usedTypeParameterNames =
                            HashSet<string>(
                                methodDeclaration.TypeParameters,
                                StringComparer.Ordinal
                            )

                        let mutable inferredTypeParameterIndex = 0

                        let rec nextInferredTypeParameterName () =
                            let index = inferredTypeParameterIndex

                            inferredTypeParameterIndex <-
                                inferredTypeParameterIndex
                                + 1

                            let candidate =
                                if index < 26 then
                                    char (
                                        int 'a'
                                        + index
                                    )
                                    |> string
                                else
                                    "a"
                                    + index.ToString(CultureInfo.InvariantCulture)

                            if usedTypeParameterNames.Add(candidate) then
                                candidate
                            else
                                nextInferredTypeParameterName ()

                        let generalizedParameters, inferredTypeParameters =
                            (([], []), methodDeclaration.Parameters)
                            ||> List.fold (fun (parameters, inferred) parameter ->
                                match parameter.Type with
                                | ParsedWildcardType range ->
                                    let name = nextInferredTypeParameterName ()

                                    ({
                                        parameter with
                                            Type = ParsedTypeParameter(name, range)
                                     }
                                     :: parameters,
                                     name
                                     :: inferred)
                                | _ ->
                                    parameter
                                    :: parameters,
                                    inferred
                            )
                            |> fun (parameters, inferred) -> List.rev parameters, List.rev inferred

                        let methodTypeParameters =
                            methodDeclaration.TypeParameters
                            @ inferredTypeParameters

                        let methodParameters =
                            HashSet<string>(methodTypeParameters, StringComparer.Ordinal)

                        let methodParameterIndex =
                            methodTypeParameters
                            |> List.mapi (fun index name -> name, index)
                            |> Map.ofList

                        let rec toCliType range =
                            function
                            | TypedTypeParameter name ->
                                match
                                    methodParameterIndex
                                    |> Map.tryFind name
                                with
                                | Some index -> Ok(CliMethodTypeParameter index)
                                | None ->
                                    diagnostic
                                        range
                                        $"the method type parameter '{name}' is not declared"
                            | TypedNamedType resolvedType when
                                resolvedType.TypeName.Namespace = "System"
                                && resolvedType.TypeName.Name = "Boolean"
                                ->
                                Ok CliBoolean
                            | TypedNamedType resolvedType when
                                resolvedType.TypeName.Namespace = "Microsoft.FSharp.Core"
                                && resolvedType.TypeName.Name = "Unit"
                                ->
                                Ok CliVoid
                            | TypedNamedType resolvedType ->
                                Ok(
                                    CliNamedType {
                                        DeclarationId = resolvedType.DeclarationId
                                        AssemblyName = resolvedType.AssemblyName
                                        TypeName = resolvedType.TypeName
                                        IsValueType = resolvedType.IsValueType
                                    }
                                )
                            | TypedByRefType elementType ->
                                toCliType range elementType
                                |> Result.bind (fun cliElementType ->
                                    match cliElementType with
                                    | CliVoid -> diagnostic range "a byref element cannot be void"
                                    | _ -> Ok(CliByRef cliElementType)
                                )
                            | typedType ->
                                diagnostic
                                    range
                                    $"the CLI type '{TypeIdentity.expression typedType}' is not yet supported"

                        let resolveMethodConstraint =
                            function
                            | ParsedAbbreviationConstraint constraintType ->
                                resolveType methodParameters constraintType
                                |> Result.map TypedAbbreviationConstraint
                            | ParsedDirectConstraint directConstraint ->
                                match directConstraint with
                                | ParsedSubtypeConstraint(typeParameter, superType, range) ->
                                    if not (methodParameters.Contains(typeParameter)) then
                                        diagnostic
                                            range
                                            $"the constrained type parameter '{typeParameter}' is not declared"
                                    else
                                        resolveType methodParameters superType
                                        |> Result.map (fun typedSuperType ->
                                            TypedDirectConstraint(
                                                TypedSubtypeConstraint(
                                                    typeParameter,
                                                    typedSuperType
                                                )
                                            )
                                        )
                                | ParsedMemberConstraint(typeParameter,
                                                         memberName,
                                                         memberType,
                                                         range) ->
                                    if not (methodParameters.Contains(typeParameter)) then
                                        diagnostic
                                            range
                                            $"the constrained type parameter '{typeParameter}' is not declared"
                                    else
                                        resolveType methodParameters memberType
                                        |> Result.map (fun typedMemberType ->
                                            TypedDirectConstraint(
                                                TypedMemberConstraint(
                                                    typeParameter,
                                                    memberName,
                                                    typedMemberType
                                                )
                                            )
                                        )

                        let rec resolveMethodConstraints resolved =
                            function
                            | [] -> Ok(List.rev resolved)
                            | constraint' :: remaining ->
                                match resolveMethodConstraint constraint' with
                                | Error error -> Error error
                                | Ok typedConstraint ->
                                    resolveMethodConstraints
                                        (typedConstraint
                                         :: resolved)
                                        remaining

                        let rec typeParameters
                            (typed: TypedParameter list)
                            (remainingParameters: ParsedParameter list)
                            =
                            match remainingParameters with
                            | [] -> Ok(List.rev typed)
                            | parameter :: remaining ->
                                match resolveType methodParameters parameter.Type with
                                | Error error -> Error error
                                | Ok typedType ->
                                    match toCliType parameter.Range typedType with
                                    | Error error -> Error error
                                    | Ok cliType ->
                                        typeParameters
                                            ({
                                                Name = parameter.Name
                                                Type = cliType
                                                Attributes = []
                                             }
                                             :: typed)
                                            remaining

                        let inferTraitReturnType memberName argumentTypes =
                            let tryAbbreviation constraintType =
                                match constraintType with
                                | ParsedGenericTypeApplication(ParsedNamedType(aliasName, _),
                                                               arguments,
                                                               _) ->
                                    match
                                        typeAbbreviations
                                        |> Map.tryFind aliasName.Name
                                    with
                                    | Some abbreviation when
                                        abbreviation.TypeParameters.Length = arguments.Length
                                        ->
                                        let substitutions =
                                            List.zip abbreviation.TypeParameters arguments
                                            |> Map.ofList

                                        Some(abbreviation, substitutions)
                                    | _ -> None
                                | _ -> None

                            let matchingMemberType =
                                methodDeclaration.Constraints
                                |> List.tryPick (fun constraint' ->
                                    match constraint' with
                                    | ParsedAbbreviationConstraint constraintType ->
                                        match tryAbbreviation constraintType with
                                        | Some(abbreviation, substitutions) ->
                                            abbreviation.Constraints
                                            |> List.tryPick (
                                                function
                                                | ParsedMemberConstraint(_,
                                                                         constrainedMemberName,
                                                                         memberType,
                                                                         _) when
                                                    constrainedMemberName = memberName
                                                    ->
                                                    Some(substituteType substitutions memberType)
                                                | _ -> None
                                            )
                                        | _ -> None
                                    | ParsedDirectConstraint(ParsedMemberConstraint(_,
                                                                                    constrainedMemberName,
                                                                                    memberType,
                                                                                    _)) when
                                        constrainedMemberName = memberName
                                        ->
                                        Some memberType
                                    | _ -> None
                                )

                            let subtypeTypes =
                                methodDeclaration.Constraints
                                |> List.collect (fun constraint' ->
                                    match constraint' with
                                    | ParsedAbbreviationConstraint constraintType ->
                                        match tryAbbreviation constraintType with
                                        | Some(abbreviation, substitutions) ->
                                            abbreviation.Constraints
                                            |> List.choose (
                                                function
                                                | ParsedSubtypeConstraint(_, superType, _) ->
                                                    Some(substituteType substitutions superType)
                                                | _ -> None
                                            )
                                        | None -> []
                                    | ParsedDirectConstraint(ParsedSubtypeConstraint(_,
                                                                                     superType,
                                                                                     _)) -> [
                                        superType
                                      ]
                                    | _ -> []
                                )

                            let referencedType =
                                function
                                | CliNamedType typeReference
                                | CliGenericType(typeReference, _) -> Some typeReference
                                | _ -> None

                            let referencedMemberCandidates cliType =
                                let visited = HashSet<string>(StringComparer.Ordinal)

                                let rec collect cliType =
                                    match referencedType cliType with
                                    | Some typeReference when
                                        visited.Add(typeReference.DeclarationId)
                                        ->
                                        let declared =
                                            references.Methods(
                                                typeReference.DeclarationId,
                                                memberName,
                                                false
                                            )

                                        let inherited = [
                                            yield!
                                                references.Interfaces(typeReference.DeclarationId)

                                            match
                                                references.BaseType(typeReference.DeclarationId)
                                            with
                                            | Some baseType -> yield baseType
                                            | None -> ()
                                        ]

                                        declared
                                        @ (inherited
                                           |> List.collect collect)
                                    | _ -> []

                                collect cliType
                                |> List.filter (fun candidate ->
                                    candidate.ParameterTypes = argumentTypes
                                )

                            let resolveReturnType returnType =
                                returnType
                                |> expandTypeAbbreviations Set.empty
                                |> resolveType methodParameters
                                |> Result.bind (toCliType methodDeclaration.BodyRange)

                            match matchingMemberType with
                            | Some(ParsedFunctionType(_, returnType, _)) ->
                                resolveReturnType returnType
                            | Some returnType -> resolveReturnType returnType
                            | None ->
                                let resolvedSubtypeTypes =
                                    subtypeTypes
                                    |> List.map (fun subtypeType ->
                                        resolveType methodParameters subtypeType
                                        |> Result.bind (toCliType methodDeclaration.BodyRange)
                                    )
                                    |> collectResults []

                                match resolvedSubtypeTypes with
                                | Error error -> Error error
                                | Ok resolvedSubtypeTypes ->
                                    let candidates =
                                        resolvedSubtypeTypes
                                        |> List.collect referencedMemberCandidates
                                        |> List.distinctBy _.StableId

                                    match candidates with
                                    | [ candidate ] -> Ok candidate.ReturnType
                                    | [] ->
                                        diagnostic
                                            methodDeclaration.BodyRange
                                            $"no method constraint supplies '{memberName}'"
                                    | _ ->
                                        diagnostic
                                            methodDeclaration.BodyRange
                                            $"the subtype constraints supply an ambiguous '{memberName}' member"

                        if not explicitTypeParametersAreUnique then
                            diagnostic
                                methodDeclaration.Range
                                "method type parameters must be unique"
                        else
                            match
                                resolveMethodConstraints [] methodDeclaration.Constraints,
                                typeParameters [] generalizedParameters,
                                methodDeclaration.Body
                            with
                            | Error error, _, _
                            | _, Error error, _ -> Error error
                            | Ok constraints, Ok parameters, ValueReference name ->
                                match
                                    parameters
                                    |> List.tryFindIndex (fun parameter -> parameter.Name = name)
                                with
                                | None ->
                                    diagnostic
                                        methodDeclaration.BodyRange
                                        $"the value '{name}' is not a static-member parameter"
                                | Some parameterIndex ->
                                    let returnType = parameters.[parameterIndex].Type

                                    let methodStableId =
                                        stableId
                                        + "/method:"
                                        + methodDeclaration.Name

                                    match
                                        attachTypedParameterAttributes
                                            methodStableId
                                            methodDeclaration.Parameters
                                            parameters
                                    with
                                    | Error error -> Error error
                                    | Ok parameters ->
                                        let exportFingerprint =
                                            Fingerprint.parts [
                                                methodStableId
                                                if methodDeclaration.IsInline then
                                                    "inline"
                                                else
                                                    "non-inline"
                                                "generic-parameters"
                                                yield! methodTypeParameters
                                                "constraints"

                                                yield!
                                                    constraints
                                                    |> List.map
                                                        TypeIdentity.methodConstraintIdentity

                                                "parameters"
                                                yield!
                                                    parameters
                                                    |> List.map TypeIdentity.parameter
                                                "return"
                                                TypeIdentity.cliType returnType
                                                "parameter-reference"
                                                name
                                            ]

                                        Ok {
                                            StableId = methodStableId
                                            Name = methodDeclaration.Name
                                            IsPublic = true
                                            GenericParameters = methodTypeParameters
                                            Constraints = constraints
                                            Attributes = []
                                            Parameters = parameters
                                            ReturnType = returnType
                                            Body = TypedParameterReference parameterIndex
                                            EmitHiddenEntrySequencePoint = false
                                            ExportFingerprint = exportFingerprint
                                            Range = methodDeclaration.Range
                                        }
                            | Ok constraints,
                              Ok parameters,
                              MemberCall(receiverName, memberName, arguments) ->
                                let argumentName =
                                    function
                                    | TypedValueArgument name
                                    | TypedAddressOfArgument(name, _) -> name

                                let typedArguments =
                                    arguments
                                    |> List.choose (
                                        function
                                        | ValueReference name -> Some(TypedValueArgument name)
                                        | AddressOfExpression(rootName, memberPath) ->
                                            Some(TypedAddressOfArgument(rootName, memberPath))
                                        | _ -> None
                                    )

                                if
                                    typedArguments.Length
                                    <> arguments.Length
                                then
                                    diagnostic
                                        methodDeclaration.BodyRange
                                        "a trait-call argument is not a method parameter"
                                elif
                                    parameters
                                    |> List.exists (fun parameter -> parameter.Name = receiverName)
                                    |> not
                                then
                                    diagnostic
                                        methodDeclaration.BodyRange
                                        $"the receiver '{receiverName}' is not a method parameter"
                                elif
                                    typedArguments
                                    |> List.exists (fun argument ->
                                        let argumentName = argumentName argument

                                        parameters
                                        |> List.exists (fun parameter ->
                                            parameter.Name = argumentName
                                        )
                                        |> not
                                    )
                                then
                                    diagnostic
                                        methodDeclaration.BodyRange
                                        "a trait-call argument is not a method parameter"
                                else
                                    let argumentTypes =
                                        typedArguments
                                        |> List.map (fun argument ->
                                            let argumentName = argumentName argument

                                            parameters
                                            |> List.find (fun parameter ->
                                                parameter.Name = argumentName
                                            )
                                            |> _.Type
                                        )

                                    match inferTraitReturnType memberName argumentTypes with
                                    | Error error -> Error error
                                    | Ok returnType ->
                                        let methodStableId =
                                            stableId
                                            + "/method:"
                                            + methodDeclaration.Name

                                        match
                                            attachTypedParameterAttributes
                                                methodStableId
                                                methodDeclaration.Parameters
                                                parameters
                                        with
                                        | Error error -> Error error
                                        | Ok parameters ->
                                            let exportFingerprint =
                                                Fingerprint.parts [
                                                    methodStableId
                                                    if methodDeclaration.IsInline then
                                                        "inline"
                                                    else
                                                        "non-inline"
                                                    "generic-parameters"
                                                    yield! methodTypeParameters
                                                    "constraints"

                                                    yield!
                                                        constraints
                                                        |> List.map
                                                            TypeIdentity.methodConstraintIdentity

                                                    "parameters"

                                                    yield!
                                                        parameters
                                                        |> List.map TypeIdentity.parameter

                                                    "return"
                                                    TypeIdentity.cliType returnType
                                                    "trait-call"
                                                    receiverName
                                                    memberName

                                                    yield!
                                                        typedArguments
                                                        |> List.map TypeIdentity.callArgument
                                                ]

                                            Ok {
                                                StableId = methodStableId
                                                Name = methodDeclaration.Name
                                                IsPublic = true
                                                GenericParameters = methodTypeParameters
                                                Constraints = constraints
                                                Attributes = []
                                                Parameters = parameters
                                                ReturnType = returnType
                                                Body =
                                                    TypedTraitCall(
                                                        receiverName,
                                                        memberName,
                                                        typedArguments
                                                    )
                                                EmitHiddenEntrySequencePoint = false
                                                ExportFingerprint = exportFingerprint
                                                Range = methodDeclaration.Range
                                            }
                            | Ok _, Ok _, IntegerLiteral _
                            | Ok _, Ok _, UnitLiteral
                            | Ok _, Ok _, BooleanLiteral _
                            | Ok _, Ok _, StringLiteral _
                            | Ok _, Ok _, NullLiteral
                            | Ok _, Ok _, NamedCallArgument _
                            | Ok _, Ok _, GenericMemberCall _
                            | Ok _, Ok _, StaticTypeMemberCall _
                            | Ok _, Ok _, AddressOfExpression _
                            | Ok _, Ok _, UnitApplication _
                            | Ok _, Ok _, BoundInstanceMember _
                            | Ok _, Ok _, MemberAssignment _
                            | Ok _, Ok _, SequentialExpression _
                            | Ok _, Ok _, FunctionApplication _
                            | Ok _, Ok _, ExpressionMemberCall _
                            | Ok _, Ok _, ExpressionMemberAccess _
                            | Ok _, Ok _, ConditionalExpression _
                            | Ok _, Ok _, ExplicitUpcastExpression _
                            | Ok _, Ok _, SequentialValueExpression _
                            | Ok _, Ok _, LocalAssignment _
                            | Ok _, Ok _, BooleanNegationExpression _
                            | Ok _, Ok _, EqualityExpression _
                            | Ok _, Ok _, TryWithExpression _
                            | Ok _, Ok _, TryFinallyExpression _
                            | Ok _, Ok _, LetExpression _
                            | Ok _, Ok _, ComputationExpression _
                            | Ok _, Ok _, ComputationBindingExpression _
                            | Ok _, Ok _, ComputationDoExpression _
                            | Ok _, Ok _, WhileExpression _
                            | Ok _, Ok _, ForExpression _
                            | Ok _, Ok _, LambdaExpression _
                            | Ok _, Ok _, UnitLambdaExpression _
                            | Ok _, Ok _, TupleExpression _
                            | Ok _, Ok _, StructTupleExpression _
                            | Ok _, Ok _, TypeConstruction _
                            | Ok _, Ok _, BindReturnFromComputation _
                            | Ok _, Ok _, ObjectExpression _
                            | Ok _, Ok _, MatchExpression _ ->
                                diagnostic
                                    methodDeclaration.BodyRange
                                    "static inline members require a constrained trait call"

                    let typeMethod (methodDeclaration: ParsedStaticMethodDeclaration) =
                        if List.isEmpty methodDeclaration.Constraints then
                            let syntheticObjectType =
                                ParsedObjectType {
                                    Container = OrdinaryObjectType
                                    Name = declaration.Name
                                    BaseType = None
                                    Methods = [ ParsedStaticObjectMethod methodDeclaration ]
                                    ConstructorRange = declaration.Range
                                    Range = declaration.Range
                                }

                            typeDeclaration syntheticObjectType
                            |> Result.bind (fun typedDeclaration ->
                                match typedDeclaration with
                                | TypedObjectType typedObjectType ->
                                    match typedObjectType.Methods with
                                    | [ TypedStaticObjectMethod typedMethod ] -> Ok typedMethod
                                    | _ ->
                                        diagnostic
                                            methodDeclaration.Range
                                            "the shared static-member checker returned an invalid method set"
                                | _ ->
                                    diagnostic
                                        methodDeclaration.Range
                                        "the shared static-member checker returned an invalid declaration"
                            )
                        else
                            typeConstrainedMethod methodDeclaration

                    match
                        declaration.Methods
                        |> List.map typeMethod
                        |> collectResults []
                    with
                    | Error error -> Error error
                    | Ok methods ->
                        Ok(
                            TypedStaticType {
                                StableId = stableId
                                IsPublic = declaration.IsPublic
                                Name = declaration.Name
                                Methods = methods
                                ExportFingerprint =
                                    Fingerprint.parts [
                                        if declaration.IsPublic then "public" else "internal"
                                        yield!
                                            methods
                                            |> List.map _.ExportFingerprint
                                    ]
                                Range = declaration.Range
                            }
                        )
                | ParsedObjectType declaration ->
                    let stableId =
                        match declaration.Container with
                        | OrdinaryObjectType ->
                            parsed.StableId
                            + "/type:"
                            + declaration.Name
                        | ParsedCurrentModuleAugmentation targetTypeName ->
                            parsed.StableId
                            + "/augmentation:"
                            + StableIdentity.qualifiedTypeName targetTypeName
                        | ParsedExtensionModule(moduleName, _, targetTypeName) ->
                            parsed.StableId
                            + "/module:"
                            + moduleName
                            + "/extension:"
                            + StableIdentity.qualifiedTypeName targetTypeName

                    let rec collectTypeParameters collected =
                        function
                        | ParsedTypeParameter(name, _) ->
                            if
                                collected
                                |> List.contains name
                            then
                                collected
                            else
                                collected
                                @ [ name ]
                        | ParsedFlexibleType(superType, _) ->
                            collectTypeParameters collected superType
                        | ParsedWildcardType _
                        | ParsedNamedType _ -> collected
                        | ParsedGenericTypeApplication(genericType, arguments, _) ->
                            (collectTypeParameters collected genericType, arguments)
                            ||> List.fold collectTypeParameters
                        | ParsedTupleType(elements, _) ->
                            (collected, elements)
                            ||> List.fold collectTypeParameters
                        | ParsedFunctionType(domain, range, _) ->
                            domain
                            |> collectTypeParameters collected
                            |> fun parameters -> collectTypeParameters parameters range

                    let requiredReferenceType genericArity namespaceName name =
                        match
                            references.Resolve(
                                parsed.Namespace,
                                parsed.OpenedNamespaces,
                                {
                                    Namespace = namespaceName
                                    Name = name
                                },
                                genericArity
                            )
                        with
                        | Ok resolvedType -> {
                            DeclarationId = resolvedType.DeclarationId
                            AssemblyName = resolvedType.AssemblyName
                            TypeName = {
                                Namespace = resolvedType.TypeName.Namespace
                                Name =
                                    resolvedType.TypeName.Name
                                    + (if genericArity = 0 then
                                           String.Empty
                                       else
                                           "`"
                                           + genericArity.ToString(CultureInfo.InvariantCulture))
                            }
                            IsValueType = resolvedType.IsValueType
                          }
                        | Error message ->
                            invalidOp
                                $"the required reference type '{namespaceName}.{name}' is unavailable: {message}"

                    let fsharpUnitType = requiredReferenceType 0 "Microsoft.FSharp.Core" "Unit"

                    let fsharpFunctionType =
                        requiredReferenceType 2 "Microsoft.FSharp.Core" "FSharpFunc"

                    let isFSharpFunctionTypeReference (typeReference: CliTypeReference) =
                        typeReference.AssemblyName = "FSharp.Core"
                        && typeReference.TypeName.Namespace = "Microsoft.FSharp.Core"
                        && typeReference.TypeName.Name = "FSharpFunc`2"

                    let rec toCliType methodParameterIndex range =
                        function
                        | TypedTypeParameter name ->
                            match
                                methodParameterIndex
                                |> Map.tryFind name
                            with
                            | Some index -> Ok(CliMethodTypeParameter index)
                            | None ->
                                diagnostic
                                    range
                                    $"the inferred method type parameter '{name}' is not declared"
                        | TypedNamedType resolvedType when
                            resolvedType.TypeName.Namespace = "System"
                            && resolvedType.TypeName.Name = "Int32"
                            ->
                            Ok CliInt32
                        | TypedNamedType resolvedType when
                            resolvedType.TypeName.Namespace = "System"
                            && resolvedType.TypeName.Name = "Boolean"
                            ->
                            Ok CliBoolean
                        | TypedNamedType resolvedType when
                            resolvedType.TypeName.Namespace = "System"
                            && resolvedType.TypeName.Name = "String"
                            ->
                            Ok CliString
                        | TypedNamedType resolvedType when
                            resolvedType.TypeName.Namespace = "System"
                            && resolvedType.TypeName.Name = "Object"
                            ->
                            Ok CliObject
                        | TypedNamedType resolvedType when
                            resolvedType.TypeName.Namespace = "Microsoft.FSharp.Core"
                            && resolvedType.TypeName.Name = "Unit"
                            ->
                            Ok(CliNamedType fsharpUnitType)
                        | TypedGenericTypeApplication(TypedNamedType resolvedType, arguments) ->
                            arguments
                            |> List.map (toCliType methodParameterIndex range)
                            |> collectResults []
                            |> Result.map (fun argumentTypes ->
                                CliGenericType(
                                    {
                                        DeclarationId = resolvedType.DeclarationId
                                        AssemblyName = resolvedType.AssemblyName
                                        TypeName = {
                                            Namespace = resolvedType.TypeName.Namespace
                                            Name =
                                                resolvedType.TypeName.Name
                                                + "`"
                                                + arguments.Length.ToString(
                                                    CultureInfo.InvariantCulture
                                                )
                                        }
                                        IsValueType = resolvedType.IsValueType
                                    },
                                    argumentTypes
                                )
                            )
                        | TypedNamedType resolvedType ->
                            Ok(
                                CliNamedType {
                                    DeclarationId = resolvedType.DeclarationId
                                    AssemblyName = resolvedType.AssemblyName
                                    TypeName = resolvedType.TypeName
                                    IsValueType = resolvedType.IsValueType
                                }
                            )
                        | TypedFunctionType(domain, rangeType) ->
                            match
                                toCliType methodParameterIndex range domain,
                                toCliType methodParameterIndex range rangeType
                            with
                            | Error error, _
                            | _, Error error -> Error error
                            | Ok domainType, Ok rangeType ->
                                Ok(
                                    CliGenericType(
                                        fsharpFunctionType,
                                        [
                                            domainType
                                            rangeType
                                        ]
                                    )
                                )
                        | TypedByRefType elementType ->
                            toCliType methodParameterIndex range elementType
                            |> Result.bind (fun cliElementType ->
                                match cliElementType with
                                | CliVoid -> diagnostic range "a byref element cannot be void"
                                | _ -> Ok(CliByRef cliElementType)
                            )
                        | typedType ->
                            diagnostic
                                range
                                $"the instance-member CLI type '{TypeIdentity.expression typedType}' is not yet supported"

                    let toCliReturnType methodParameterIndex range typedType =
                        match typedType with
                        | TypedNamedType resolvedType when
                            resolvedType.TypeName.Namespace = "Microsoft.FSharp.Core"
                            && resolvedType.TypeName.Name = "Unit"
                            ->
                            Ok CliVoid
                        | _ -> toCliType methodParameterIndex range typedType

                    let collectMethodTypeParameters
                        explicitTypeParameters
                        (parameters: ParsedParameter list)
                        returnType
                        =
                        let fromParameters =
                            (explicitTypeParameters, parameters)
                            ||> List.fold (fun collected parameter ->
                                collectTypeParameters collected parameter.Type
                            )

                        match returnType with
                        | Some returnType -> collectTypeParameters fromParameters returnType
                        | None -> fromParameters

                    let inferObjectMethodParameterTypes expression =
                        let containsGenericParameter cliType =
                            let rec loop =
                                function
                                | CliTypeParameter _
                                | CliMethodTypeParameter _ -> true
                                | CliByRef elementType -> loop elementType
                                | CliArray elementType -> loop elementType
                                | CliGenericType(_, arguments) ->
                                    arguments
                                    |> List.exists loop
                                | CliInt32
                                | CliBoolean
                                | CliString
                                | CliObject
                                | CliNativeInt
                                | CliVoid
                                | CliNamedType _ -> false

                            loop cliType

                        let addConstraint name cliType constraints =
                            if containsGenericParameter cliType then
                                constraints
                            else
                                constraints
                                |> Map.change
                                    name
                                    (fun existing ->
                                        existing
                                        |> Option.defaultValue Set.empty
                                        |> Set.add cliType
                                        |> Some
                                    )

                        let collectStaticCallConstraints
                            (genericArity: int option)
                            receiverName
                            memberName
                            (arguments: ParsedExpression list)
                            constraints
                            =
                            match
                                references.Resolve(
                                    parsed.Namespace,
                                    parsed.OpenedNamespaces,
                                    {
                                        Namespace = String.Empty
                                        Name = receiverName
                                    },
                                    0
                                )
                            with
                            | Error _ -> constraints
                            | Ok resolvedType ->
                                let candidates =
                                    references.Methods(resolvedType.DeclarationId, memberName, true)
                                    |> List.filter (fun methodDefinition ->
                                        arguments.Length
                                        >= methodDefinition.ParameterTypes.Length
                                           - methodDefinition.OptionalParameterCount
                                        && arguments.Length
                                           <= methodDefinition.ParameterTypes.Length
                                        && (genericArity
                                            |> Option.forall (fun arity ->
                                                methodDefinition.GenericArity = arity
                                            ))
                                    )

                                arguments
                                |> List.mapi (fun index argument -> index, argument)
                                |> List.fold
                                    (fun state (index, argument) ->
                                        match argument with
                                        | ValueReference parameterName ->
                                            let candidateTypes =
                                                candidates
                                                |> List.map (fun candidate ->
                                                    candidate.ParameterTypes.[index]
                                                )
                                                |> List.filter (
                                                    containsGenericParameter
                                                    >> not
                                                )
                                                |> List.distinct

                                            match candidateTypes with
                                            | [ candidateType ] ->
                                                addConstraint parameterName candidateType state
                                            | _ -> state
                                        | _ -> state
                                    )
                                    constraints

                        let rec collect constraints =
                            function
                            | MemberCall(receiverName, memberName, arguments) ->
                                let constraints =
                                    collectStaticCallConstraints
                                        None
                                        receiverName
                                        memberName
                                        arguments
                                        constraints

                                (constraints, arguments)
                                ||> List.fold collect
                            | StaticTypeMemberCall(_, _, arguments) ->
                                (constraints, arguments)
                                ||> List.fold collect
                            | GenericMemberCall(receiverName, memberName, typeArguments, arguments) ->
                                let constraints =
                                    collectStaticCallConstraints
                                        (Some typeArguments.Length)
                                        receiverName
                                        memberName
                                        arguments
                                        constraints

                                (constraints, arguments)
                                ||> List.fold collect
                            | TypeConstruction(_, arguments, _) ->
                                (constraints, arguments)
                                ||> List.fold collect
                            | BindReturnFromComputation(_, bindings, _, returnFrom, _) ->
                                let constraints =
                                    (constraints, bindings)
                                    ||> List.fold (fun state (_, input) -> collect state input)

                                collect constraints returnFrom
                            | MemberAssignment(_, _, value)
                            | NamedCallArgument(_, value, _)
                            | LocalAssignment(_, value)
                            | BooleanNegationExpression(value, _)
                            | ExplicitUpcastExpression(value, _) -> collect constraints value
                            | EqualityExpression(left, right, _) ->
                                let constraints = collect constraints left
                                collect constraints right
                            | SequentialExpression expressions ->
                                (constraints, expressions)
                                ||> List.fold collect
                            | SequentialValueExpression expressions ->
                                (constraints, expressions)
                                ||> List.fold (fun state (value, _) -> collect state value)
                            | FunctionApplication(functionExpression, argumentExpression) ->
                                let constraints = collect constraints functionExpression
                                collect constraints argumentExpression
                            | ExpressionMemberAccess(receiver, _) -> collect constraints receiver
                            | ExpressionMemberCall(receiver, _, arguments) ->
                                let constraints = collect constraints receiver

                                (constraints, arguments)
                                ||> List.fold collect
                            | ConditionalExpression(condition, ifTrue, ifFalse, _, _, _) ->
                                let constraints = collect constraints condition
                                let constraints = collect constraints ifTrue
                                collect constraints ifFalse
                            | TryWithExpression(body, _, handler, _, _, _, _, _) ->
                                let constraints = collect constraints body
                                collect constraints handler
                            | TryFinallyExpression(body, compensation, _, _, _, _, _) ->
                                let constraints = collect constraints body
                                collect constraints compensation
                            | MatchExpression(input, clauses, _, _) ->
                                let constraints = collect constraints input

                                (constraints, clauses)
                                ||> List.fold (fun state (_, guard, body, _) ->
                                    let state =
                                        match guard with
                                        | Some(guardExpression, _) -> collect state guardExpression
                                        | None -> state

                                    collect state body
                                )
                            | LetExpression(_, _, _, value, body, _, _) ->
                                let constraints = collect constraints value
                                collect constraints body
                            | ComputationExpression(_, body, _) -> collect constraints body
                            | ComputationBindingExpression(_, input, body, _, _) ->
                                let constraints = collect constraints input
                                collect constraints body
                            | ComputationDoExpression(input, _) -> collect constraints input
                            | WhileExpression(condition, body, _, _, _) ->
                                let constraints = collect constraints condition
                                collect constraints body
                            | ForExpression(_, sequence, body, _, _, _, _) ->
                                let constraints = collect constraints sequence
                                collect constraints body
                            | LambdaExpression(_, _, body, _)
                            | UnitLambdaExpression(body, _) -> collect constraints body
                            | TupleExpression(elements, _)
                            | StructTupleExpression(elements, _) ->
                                (constraints, elements)
                                ||> List.fold collect
                            | ObjectExpression(_, arguments, members, _) ->
                                let constraints =
                                    (constraints, arguments)
                                    ||> List.fold collect

                                (constraints, members)
                                ||> List.fold (fun state memberDeclaration ->
                                    collect state memberDeclaration.Body
                                )
                            | IntegerLiteral _
                            | UnitLiteral
                            | BooleanLiteral _
                            | StringLiteral _
                            | NullLiteral
                            | ValueReference _
                            | AddressOfExpression _
                            | UnitApplication _
                            | BoundInstanceMember _ -> constraints

                        collect Map.empty expression
                        |> Map.toList
                        |> List.choose (fun (name, candidates) ->
                            if candidates.Count = 1 then
                                candidates
                                |> Seq.exactlyOne
                                |> fun candidate -> Some(name, candidate)
                            else
                                None
                        )
                        |> Map.ofList

                    let typeObjectMethodParameters
                        methodParameterIndex
                        declaredMethodParameters
                        inferredParameterTypes
                        (parameters: ParsedParameter list)
                        =
                        parameters
                        |> List.map (fun parameter ->
                            (match parameter.Type with
                             | ParsedWildcardType _ ->
                                 match
                                     inferredParameterTypes
                                     |> Map.tryFind parameter.Name
                                 with
                                 | Some parameterType -> Ok parameterType
                                 | None ->
                                     diagnostic
                                         parameter.Range
                                         $"the type of parameter '{parameter.Name}' could not be inferred"
                             | _ ->
                                 parameter.Type
                                 |> expandTypeAbbreviations Set.empty
                                 |> resolveType declaredMethodParameters
                                 |> Result.bind (toCliType methodParameterIndex parameter.Range))
                            |> Result.map (fun parameterType ->
                                ({
                                    Name = parameter.Name
                                    Type = parameterType
                                    Attributes = []
                                }
                                : TypedParameter)
                            )
                        )
                        |> collectResults []

                    let typeObjectMethodReturnType
                        methodParameterIndex
                        declaredMethodParameters
                        returnType
                        =
                        match returnType with
                        | None -> Ok None
                        | Some returnType ->
                            returnType
                            |> expandTypeAbbreviations Set.empty
                            |> resolveType declaredMethodParameters
                            |> Result.bind (toCliReturnType methodParameterIndex returnType.Range)
                            |> Result.map Some

                    let finishObjectMethod (completion: ObjectMethodCompletion) =
                        let parameterIdentity =
                            match completion.Parameters with
                            | [] -> "unit"
                            | _ ->
                                completion.Parameters
                                |> List.map (fun parameter -> TypeIdentity.cliType parameter.Type)
                                |> String.concat "*"

                        let methodStableId =
                            stableId
                            + "/method:"
                            + completion.Name
                            + ":"
                            + parameterIdentity
                            + "->"
                            + TypeIdentity.cliType completion.ReturnType

                        match
                            typeCustomAttributes
                                methodStableId
                                completion.Kind.AllowedAttributeKinds
                                completion.ParsedAttributes,
                            attachTypedParameterAttributes
                                methodStableId
                                completion.ParsedParameters
                                completion.Parameters
                        with
                        | Error error, _
                        | _, Error error -> Error error
                        | Ok attributes, Ok parameters ->
                            let attributes =
                                match completion.ArgumentCounts with
                                | _ :: _ :: _ ->
                                    let attributeStableId =
                                        methodStableId
                                        + "/attribute:compilation-argument-counts"

                                    let constructorArguments = [
                                        TypedInt32ArrayAttributeArgument completion.ArgumentCounts
                                    ]

                                    attributes
                                    @ [
                                        {
                                            StableId = attributeStableId
                                            Kind = CompilationArgumentCountsAttribute
                                            ConstructorArguments = constructorArguments
                                            ExportFingerprint =
                                                Fingerprint.parts [
                                                    attributeStableId
                                                    TypeIdentity.attributeKind
                                                        CompilationArgumentCountsAttribute

                                                    yield!
                                                        constructorArguments
                                                        |> List.map TypeIdentity.attributeArgument
                                                ]
                                        }
                                    ]
                                | _ -> attributes

                            let exportFingerprint =
                                Fingerprint.parts [
                                    methodStableId
                                    completion.Kind.ExportIdentity
                                    if completion.IsInline then "inline" else "non-inline"
                                    if completion.IsPublic then "public" else "internal"
                                    "generic-parameters"
                                    yield! completion.GenericParameters
                                    "constraints"

                                    yield!
                                        completion.Constraints
                                        |> List.map TypeIdentity.methodConstraintIdentity

                                    "attributes"

                                    yield!
                                        attributes
                                        |> List.map TypeIdentity.customAttribute

                                    "parameters"

                                    yield!
                                        parameters
                                        |> List.map TypeIdentity.parameter

                                    "return"
                                    TypeIdentity.cliType completion.ReturnType

                                    if completion.IsInline then
                                        "inline-body"
                                        TypeIdentity.inlineBody completion.Body
                                    else
                                        "non-inline-body-hidden"
                                ]

                            Ok {
                                StableId = methodStableId
                                Name = completion.Name
                                IsPublic = completion.IsPublic
                                GenericParameters = completion.GenericParameters
                                Constraints = completion.Constraints
                                Attributes = attributes
                                Parameters = parameters
                                ReturnType = completion.ReturnType
                                Body = completion.Body
                                EmitHiddenEntrySequencePoint =
                                    completion.EmitHiddenEntrySequencePoint
                                ExportFingerprint = exportFingerprint
                                Range = completion.Range
                            }

                    let typeStaticMethod (methodDeclaration: ParsedStaticMethodDeclaration) =
                        let constraintWitnesses = ResizeArray<CliType>()

                        let expandedBodyRange =
                            InlineExpansion.sourceRange
                                methodDeclaration.BodyRange
                                methodDeclaration.Body

                        let expandedBody, emitHiddenEntrySequencePoint =
                            InlineExpansion.expand methodDeclaration.Body

                        let methodDeclaration = {
                            methodDeclaration with
                                Body = expandedBody
                                BodyRange = expandedBodyRange
                        }

                        let explicitTypeParametersAreUnique =
                            (methodDeclaration.TypeParameters
                             |> Set.ofList
                             |> Set.count) = methodDeclaration.TypeParameters.Length

                        if not explicitTypeParametersAreUnique then
                            diagnostic
                                methodDeclaration.Range
                                "method type parameters must be unique"
                        elif not (List.isEmpty methodDeclaration.Constraints) then
                            diagnostic
                                methodDeclaration.Range
                                "constraints on static object members are not yet supported"
                        else
                            let inferredParameterTypes =
                                let inferred =
                                    inferObjectMethodParameterTypes methodDeclaration.Body

                                if methodDeclaration.IsEntryPoint then
                                    match methodDeclaration.Parameters with
                                    | [ parameter ] ->
                                        inferred
                                        |> Map.add parameter.Name (CliArray CliString)
                                    | _ -> inferred
                                else
                                    inferred

                            let usedTypeParameterNames =
                                HashSet<string>(
                                    collectMethodTypeParameters
                                        methodDeclaration.TypeParameters
                                        methodDeclaration.Parameters
                                        methodDeclaration.ReturnType,
                                    StringComparer.Ordinal
                                )

                            let mutable inferredTypeParameterIndex = 0

                            let rec nextInferredTypeParameterName () =
                                let index = inferredTypeParameterIndex

                                inferredTypeParameterIndex <-
                                    inferredTypeParameterIndex
                                    + 1

                                let candidate =
                                    if index < 26 then
                                        char (
                                            int 'a'
                                            + index
                                        )
                                        |> string
                                    else
                                        "a"
                                        + index.ToString(CultureInfo.InvariantCulture)

                                if usedTypeParameterNames.Add(candidate) then
                                    candidate
                                else
                                    nextInferredTypeParameterName ()

                            let generalizedParameters =
                                methodDeclaration.Parameters
                                |> List.map (fun parameter ->
                                    match parameter.Type with
                                    | ParsedWildcardType range when
                                        inferredParameterTypes
                                        |> Map.containsKey parameter.Name
                                        |> not
                                          ->
                                          {
                                              parameter with
                                                  Type =
                                                      ParsedTypeParameter(
                                                          nextInferredTypeParameterName (),
                                                          range
                                                      )
                                          }
                                    | _ -> parameter
                                )

                            let methodTypeParameters =
                                collectMethodTypeParameters
                                    methodDeclaration.TypeParameters
                                    generalizedParameters
                                    methodDeclaration.ReturnType

                            let declaredMethodParameters =
                                HashSet<string>(methodTypeParameters, StringComparer.Ordinal)

                            let methodParameterIndex =
                                methodTypeParameters
                                |> List.mapi (fun index name -> name, index)
                                |> Map.ofList

                            let typedParameters =
                                typeObjectMethodParameters
                                    methodParameterIndex
                                    declaredMethodParameters
                                    inferredParameterTypes
                                    generalizedParameters

                            let declaredReturnType =
                                typeObjectMethodReturnType
                                    methodParameterIndex
                                    declaredMethodParameters
                                    methodDeclaration.ReturnType

                            match typedParameters, declaredReturnType with
                            | Error error, _
                            | _, Error error -> Error error
                            | Ok parameters, Ok _ when
                                (parameters
                                 |> List.map _.Name
                                 |> Set.ofList
                                 |> Set.count)
                                <> parameters.Length
                                ->
                                diagnostic
                                    methodDeclaration.Range
                                    "static-member parameter names must be unique"
                            | Ok parameters, Ok declaredReturnType ->
                                let rec substituteTypeArguments (arguments: CliType list) =
                                    function
                                    | CliTypeParameter index when index < arguments.Length ->
                                        arguments.[index]
                                    | CliGenericType(typeReference, typeArguments) ->
                                        CliGenericType(
                                            typeReference,
                                            typeArguments
                                            |> List.map (substituteTypeArguments arguments)
                                        )
                                    | CliByRef elementType ->
                                        CliByRef(substituteTypeArguments arguments elementType)
                                    | CliArray elementType ->
                                        CliArray(substituteTypeArguments arguments elementType)
                                    | cliType -> cliType

                                let rec resolveAddressFields
                                    (fields: TypedFieldAddress list)
                                    (ownerType: CliType)
                                    =
                                    function
                                    | [] -> Ok(List.rev fields, ownerType)
                                    | fieldName :: remaining ->
                                        let ownerType =
                                            match ownerType with
                                            | CliByRef elementType -> elementType
                                            | cliType -> cliType

                                        let ownerReference, typeArguments =
                                            (match ownerType with
                                             | CliNamedType typeReference -> Some(typeReference, [])
                                             | CliGenericType(typeReference, arguments) ->
                                                 Some(typeReference, arguments)
                                             | _ -> None)
                                            |> Option.defaultWith (fun () ->
                                                invalidOp
                                                    "an address-of field owner must be a named type"
                                            )

                                        match
                                            checkedSourceStructs
                                            |> Seq.tryFind (fun sourceStruct ->
                                                sourceStruct.Declaration.StableId = ownerReference.DeclarationId
                                            )
                                        with
                                        | None ->
                                            diagnostic
                                                methodDeclaration.BodyRange
                                                $"the address-of field owner '{TypeIdentity.cliType ownerType}' is not a local struct"
                                        | Some sourceStruct ->
                                            match
                                                sourceStruct.Declaration.Fields
                                                |> List.tryFind (fun field ->
                                                    field.Name = fieldName
                                                )
                                            with
                                            | None ->
                                                diagnostic
                                                    methodDeclaration.BodyRange
                                                    $"the struct '{sourceStruct.Declaration.Name}' has no field '{fieldName}'"
                                            | Some field when not field.IsMutable ->
                                                diagnostic
                                                    methodDeclaration.BodyRange
                                                    $"the address-of field '{fieldName}' is not mutable"
                                            | Some field ->
                                                let fieldType =
                                                    field.Type
                                                    |> substituteTypeArguments typeArguments

                                                resolveAddressFields
                                                    (({
                                                        DeclaringType = ownerType
                                                        Name = field.Name
                                                        FieldType = field.Type
                                                        TargetStableId = Some field.StableId
                                                     }
                                                     : TypedFieldAddress)
                                                     :: fields)
                                                    fieldType
                                                    remaining

                                let rewriteFunctionLambdaCaptures
                                    lambdaParameterCount
                                    (captures: TypedFunctionLambdaCapture list)
                                    expression
                                    =
                                    let rec rewrite =
                                        function
                                        | TypedParameterReference index when
                                            index
                                            >= lambdaParameterCount
                                            ->
                                            match
                                                captures
                                                |> List.tryFind (fun capture ->
                                                    capture.OuterParameterIndex = index
                                                                                  - lambdaParameterCount
                                                )
                                            with
                                            | Some capture ->
                                                TypedInstanceFieldGet(
                                                    TypedReceiverReference,
                                                    capture.Field
                                                )
                                            | None -> TypedParameterReference index
                                        | TypedLet(localIndex,
                                                   name,
                                                   isMutable,
                                                   localType,
                                                   value,
                                                   body,
                                                   bindingRange,
                                                   bodyRange) ->
                                            TypedLet(
                                                localIndex,
                                                name,
                                                isMutable,
                                                localType,
                                                rewrite value,
                                                rewrite body,
                                                bindingRange,
                                                bodyRange
                                            )
                                        | TypedLocalAssignment(localIndex, localType, value) ->
                                            TypedLocalAssignment(
                                                localIndex,
                                                localType,
                                                rewrite value
                                            )
                                        | TypedInstanceFieldGet(receiver, field) ->
                                            TypedInstanceFieldGet(rewrite receiver, field)
                                        | TypedStaticMethodCall(target, genericArguments, arguments) ->
                                            TypedStaticMethodCall(
                                                target,
                                                genericArguments,
                                                arguments
                                                |> List.map rewrite
                                            )
                                        | TypedObjectConstruction(target, arguments) ->
                                            TypedObjectConstruction(
                                                target,
                                                arguments
                                                |> List.map rewrite
                                            )
                                        | TypedFunctionApplication(functionType,
                                                                   domainType,
                                                                   rangeType,
                                                                   functionExpression,
                                                                   argumentExpression) ->
                                            TypedFunctionApplication(
                                                functionType,
                                                domainType,
                                                rangeType,
                                                rewrite functionExpression,
                                                rewrite argumentExpression
                                            )
                                        | TypedInstanceMethodCall(target, receiver, arguments) ->
                                            TypedInstanceMethodCall(
                                                target,
                                                rewrite receiver,
                                                arguments
                                                |> List.map rewrite
                                            )
                                        | TypedConditional(condition,
                                                           ifTrue,
                                                           ifFalse,
                                                           conditionRange,
                                                           ifTrueRange,
                                                           ifFalseRange) ->
                                            TypedConditional(
                                                rewrite condition,
                                                rewrite ifTrue,
                                                rewrite ifFalse,
                                                conditionRange,
                                                ifTrueRange,
                                                ifFalseRange
                                            )
                                        | TypedUpcast(sourceType,
                                                      targetType,
                                                      targetResolvedType,
                                                      value) ->
                                            TypedUpcast(
                                                sourceType,
                                                targetType,
                                                targetResolvedType,
                                                rewrite value
                                            )
                                        | TypedSequential expressions ->
                                            TypedSequential(
                                                expressions
                                                |> List.map (fun (value, valueType, range) ->
                                                    rewrite value, valueType, range
                                                )
                                            )
                                        | TypedBooleanNegation(value, range) ->
                                            TypedBooleanNegation(rewrite value, range)
                                        | TypedEquality(left, right, range) ->
                                            TypedEquality(rewrite left, rewrite right, range)
                                        | TypedTryWith(body,
                                                       handlerLocalIndex,
                                                       handlerName,
                                                       catchType,
                                                       handler,
                                                       tryRange,
                                                       withRange,
                                                       bodyRange,
                                                       handlerRange,
                                                       range) ->
                                            TypedTryWith(
                                                rewrite body,
                                                handlerLocalIndex,
                                                handlerName,
                                                catchType,
                                                rewrite handler,
                                                tryRange,
                                                withRange,
                                                bodyRange,
                                                handlerRange,
                                                range
                                            )
                                        | TypedNullMatch(input,
                                                         inputType,
                                                         localIndex,
                                                         bindingName,
                                                         ifNull,
                                                         ifNotNull,
                                                         matchHeaderRange,
                                                         ifNullRange,
                                                         ifNotNullRange,
                                                         range) ->
                                            TypedNullMatch(
                                                rewrite input,
                                                inputType,
                                                localIndex,
                                                bindingName,
                                                rewrite ifNull,
                                                rewrite ifNotNull,
                                                matchHeaderRange,
                                                ifNullRange,
                                                ifNotNullRange,
                                                range
                                            )
                                        | TypedTypeTestMatch(input,
                                                             targetType,
                                                             localIndex,
                                                             bindingName,
                                                             guard,
                                                             ifMatched,
                                                             ifNotMatched,
                                                             matchHeaderRange,
                                                             ifMatchedRange,
                                                             ifNotMatchedRange,
                                                             range) ->
                                            TypedTypeTestMatch(
                                                rewrite input,
                                                targetType,
                                                localIndex,
                                                bindingName,
                                                (guard
                                                 |> Option.map (fun (value, guardRange) ->
                                                     rewrite value, guardRange
                                                 )),
                                                rewrite ifMatched,
                                                rewrite ifNotMatched,
                                                matchHeaderRange,
                                                ifMatchedRange,
                                                ifNotMatchedRange,
                                                range
                                            )
                                        | TypedObjectExpression(typeReference,
                                                                baseType,
                                                                constructorArguments,
                                                                members,
                                                                range) ->
                                            TypedObjectExpression(
                                                typeReference,
                                                baseType,
                                                constructorArguments
                                                |> List.map rewrite,
                                                members
                                                |> List.map (fun memberDeclaration -> {
                                                    memberDeclaration with
                                                        Body = rewrite memberDeclaration.Body
                                                }),
                                                range
                                            )
                                        | expression -> expression

                                    rewrite expression

                                let contextualFunctionCallCandidates receiverName memberName =
                                    match declaredReturnType with
                                    | None -> []
                                    | Some expectedReturnType ->
                                        match
                                            references.Resolve(
                                                parsed.Namespace,
                                                parsed.OpenedNamespaces,
                                                {
                                                    Namespace = String.Empty
                                                    Name = receiverName
                                                },
                                                0
                                            )
                                        with
                                        | Error _ -> []
                                        | Ok resolvedType ->
                                            references.Methods(
                                                resolvedType.DeclarationId,
                                                memberName,
                                                true
                                            )
                                            |> List.choose (fun methodDefinition ->
                                                let requiredParameterCount =
                                                    methodDefinition.ParameterTypes.Length
                                                    - methodDefinition.OptionalParameterCount

                                                if
                                                    requiredParameterCount > 1
                                                    || methodDefinition.ParameterTypes.Length < 1
                                                then
                                                    None
                                                else
                                                    let substitutions =
                                                        Array.create
                                                            methodDefinition.GenericArity
                                                            None

                                                    let returnTypeMatches =
                                                        inferReferenceMethodTypeArgument
                                                            []
                                                            substitutions
                                                            methodDefinition.ReturnType
                                                            expectedReturnType

                                                    if
                                                        not returnTypeMatches
                                                        || (substitutions
                                                            |> Array.exists Option.isNone)
                                                    then
                                                        None
                                                    else
                                                        let substitute =
                                                            substituteReferenceMethodTypeArguments
                                                                []
                                                                substitutions

                                                        let parameterType =
                                                            methodDefinition.ParameterTypes.Head
                                                            |> substitute

                                                        match parameterType with
                                                        | CliGenericType(functionReference,
                                                                         [ _; _ ]) when
                                                            isFSharpFunctionTypeReference
                                                                functionReference
                                                            ->
                                                            let target = {
                                                                DeclaringType =
                                                                    CliNamedType
                                                                        methodDefinition.DeclaringType
                                                                StableId =
                                                                    methodDefinition.StableId
                                                                Name = methodDefinition.Name
                                                                GenericArity =
                                                                    methodDefinition.GenericArity
                                                                ParameterTypes =
                                                                    methodDefinition.ParameterTypes
                                                                ReturnType =
                                                                    methodDefinition.ReturnType
                                                            }

                                                            Some(
                                                                target,
                                                                substitutions
                                                                |> Array.choose id
                                                                |> Array.toList,
                                                                parameterType,
                                                                substitute
                                                                    methodDefinition.ReturnType
                                                            )
                                                        | _ -> None
                                            )

                                let isSingleValueMemberCall
                                    expectedReceiver
                                    expectedMember
                                    expectedValue
                                    =
                                    function
                                    | MemberCall(actualReceiver,
                                                 actualMember,
                                                 [ ValueReference actualValue ])
                                    | ExpressionMemberCall(ValueReference actualReceiver,
                                                           actualMember,
                                                           [ ValueReference actualValue ]) ->
                                        actualReceiver = expectedReceiver
                                        && actualMember = expectedMember
                                        && actualValue = expectedValue
                                    | _ -> false

                                let isUnitMemberCall expectedReceiver expectedMember =
                                    function
                                    | MemberCall(actualReceiver, actualMember, [])
                                    | ExpressionMemberCall(ValueReference actualReceiver,
                                                           actualMember,
                                                           []) ->
                                        actualReceiver = expectedReceiver
                                        && actualMember = expectedMember
                                    | _ -> false

                                let visibleSourceModuleMethods name =
                                    let visibleScopes =
                                        parsed.OpenedNamespaces
                                        |> Set.ofList

                                    checkedSourceModuleMethods
                                    |> Seq.filter (fun sourceMethod ->
                                        let qualifiedModuleName =
                                            if String.IsNullOrEmpty(sourceMethod.Namespace) then
                                                sourceMethod.ModuleName
                                            else
                                                sourceMethod.Namespace
                                                + "."
                                                + sourceMethod.ModuleName

                                        sourceMethod.Declaration.Name = name
                                        && (sourceMethod.ModuleStableId = parsed.StableId
                                            || visibleScopes.Contains(sourceMethod.ModuleName)
                                            || visibleScopes.Contains(qualifiedModuleName))
                                    )
                                    |> List.ofSeq

                                let hasVisibleSourceModuleMethod name =
                                    visibleSourceModuleMethods name
                                    |> List.isEmpty
                                    |> not

                                let resolveSourceModuleMethodCandidates
                                    name
                                    (methods: seq<CheckedSourceModuleMethod>)
                                    argumentTypes
                                    expectedReturnType
                                    range
                                    =
                                    let candidates =
                                        methods
                                        |> Seq.choose (fun sourceMethod ->
                                            tryInferStaticMethod
                                                {
                                                    Namespace = sourceMethod.Namespace
                                                    Name = sourceMethod.ModuleName
                                                    StableId = sourceMethod.ModuleStableId
                                                    Methods = [ sourceMethod.Declaration ]
                                                }
                                                sourceMethod.Declaration
                                                argumentTypes
                                                expectedReturnType
                                                (constraintWitnesses
                                                 |> Seq.toList)
                                        )
                                        |> Seq.distinctBy (fun
                                                               (target,
                                                                genericArguments,
                                                                returnType,
                                                                _) ->
                                            target.StableId, genericArguments, returnType
                                        )
                                        |> List.ofSeq

                                    match candidates with
                                    | [] -> None
                                    | [ target, genericArguments, returnType, appliedConstraints ] ->
                                        for appliedConstraint in appliedConstraints do
                                            if
                                                not (
                                                    constraintWitnesses.Contains(appliedConstraint)
                                                )
                                            then
                                                constraintWitnesses.Add(appliedConstraint)

                                        Some(Ok(target, genericArguments, returnType))
                                    | _ ->
                                        Some(
                                            diagnostic
                                                range
                                                $"the callable value '{name}' is ambiguous"
                                        )

                                let resolveSourceModuleMethod
                                    name
                                    argumentTypes
                                    expectedReturnType
                                    range
                                    =
                                    resolveSourceModuleMethodCandidates
                                        name
                                        (visibleSourceModuleMethods name)
                                        argumentTypes
                                        expectedReturnType
                                        range

                                let resolveQualifiedSourceModuleMethod
                                    moduleName
                                    name
                                    argumentTypes
                                    expectedReturnType
                                    range
                                    =
                                    let methods =
                                        checkedSourceModuleMethods
                                        |> Seq.filter (fun sourceMethod ->
                                            let qualifiedModuleName =
                                                if
                                                    String.IsNullOrEmpty(sourceMethod.Namespace)
                                                then
                                                    sourceMethod.ModuleName
                                                else
                                                    sourceMethod.Namespace
                                                    + "."
                                                    + sourceMethod.ModuleName

                                            sourceMethod.Declaration.Name = name
                                            && (sourceMethod.ModuleName = moduleName
                                                || qualifiedModuleName = moduleName)
                                        )

                                    resolveSourceModuleMethodCandidates
                                        name
                                        methods
                                        argumentTypes
                                        expectedReturnType
                                        range

