                    TargetStableId = None
                }

                [
                    yield!
                        expression.Captures
                        |> List.map (fun capture ->
                            LoadArgument(methodArgumentIndex kind capture.OuterParameterIndex)
                        )

                    NewObject constructor
                    LoadFunctionPointer invoke
                    NewObject delegateConstructor
                ]

            let valueTaskOfUnitInstructions
                (methodDeclaration: TypedMethodDeclaration)
                kind
                (expression: TypedValueTaskOfUnitExpression)
                =
                let layout = valueTaskOfUnitHelperLayout methodDeclaration expression

                let definition = layout.DefinitionExpression

                let nonGenericTaskType = CliNamedType expression.NonGenericTaskTypeReference

                let definitionNonGenericTaskType =
                    CliNamedType definition.NonGenericTaskTypeReference

                let taskUnitType =
                    CliGenericType(expression.TaskTypeReference, [ expression.UnitType ])

                let definitionTaskUnitType =
                    CliGenericType(definition.TaskTypeReference, [ definition.UnitType ])

                let continuationHelper = {
                    DeclaringType = CliDeclaringType layout.MethodType
                    Name = "Continue"
                    GenericArity = 0
                    IsInstance = false
                    ParameterTypes = [
                        definitionNonGenericTaskType
                        CliObject
                    ]
                    ReturnType = definitionTaskUnitType
                    TargetStableId = None
                }

                let asTask = {
                    DeclaringType = CliDeclaringType expression.SourceValueTaskType
                    Name = "AsTask"
                    GenericArity = 0
                    IsInstance = true
                    ParameterTypes = []
                    ReturnType = nonGenericTaskType
                    TargetStableId = None
                }

                let continuationDelegateType =
                    CliGenericType(
                        expression.FuncTypeReference,
                        [
                            nonGenericTaskType
                            CliObject
                            taskUnitType
                        ]
                    )

                let continuationDelegateConstructor = {
                    DeclaringType = CliDeclaringType continuationDelegateType
                    Name = ".ctor"
                    GenericArity = 0
                    IsInstance = true
                    ParameterTypes = [
                        CliObject
                        CliNativeInt
                    ]
                    ReturnType = CliVoid
                    TargetStableId = None
                }

                let continuationDefinitionDelegateType =
                    CliGenericType(
                        definition.FuncTypeReference,
                        [
                            definitionNonGenericTaskType
                            CliObject
                            CliMethodTypeParameter 0
                        ]
                    )

                let continueWith = {
                    DeclaringType = CliDeclaringType nonGenericTaskType
                    Name = "ContinueWith"
                    GenericArity = 1
                    IsInstance = true
                    ParameterTypes = [
                        continuationDefinitionDelegateType
                        CliObject
                        expression.CancellationTokenType
                        expression.TaskContinuationOptionsType
                        expression.TaskSchedulerType
                    ]
                    ReturnType =
                        CliGenericType(expression.TaskTypeReference, [ CliMethodTypeParameter 0 ])
                    TargetStableId = None
                }

                let cancellationTokenNone = {
                    DeclaringType = CliDeclaringType expression.CancellationTokenType
                    Name = "get_None"
                    GenericArity = 0
                    IsInstance = false
                    ParameterTypes = []
                    ReturnType = expression.CancellationTokenType
                    TargetStableId = None
                }

                let taskSchedulerDefault = {
                    DeclaringType = CliDeclaringType expression.TaskSchedulerType
                    Name = "get_Default"
                    GenericArity = 0
                    IsInstance = false
                    ParameterTypes = []
                    ReturnType = expression.TaskSchedulerType
                    TargetStableId = None
                }

                let unwrap = {
                    DeclaringType =
                        CliDeclaringType(CliNamedType expression.TaskExtensionsTypeReference)
                    Name = "Unwrap"
                    GenericArity = 1
                    IsInstance = false
                    ParameterTypes = [
                        CliGenericType(
                            expression.TaskTypeReference,
                            [
                                CliGenericType(
                                    expression.TaskTypeReference,
                                    [ CliMethodTypeParameter 0 ]
                                )
                            ]
                        )
                    ]
                    ReturnType =
                        CliGenericType(expression.TaskTypeReference, [ CliMethodTypeParameter 0 ])
                    TargetStableId = None
                }

                let valueTaskConstructor = {
                    DeclaringType = CliDeclaringType expression.OutputValueTaskType
                    Name = ".ctor"
                    GenericArity = 0
                    IsInstance = true
                    ParameterTypes = [
                        CliGenericType(expression.TaskTypeReference, [ CliTypeParameter 0 ])
                    ]
                    ReturnType = CliVoid
                    TargetStableId = None
                }

                [
                    LoadArgumentAddress(methodArgumentIndex kind expression.SourceParameterIndex)
                    CallMethod asTask
                    LoadNull
                    LoadFunctionPointer continuationHelper
                    NewObject continuationDelegateConstructor
                    LoadNull
                    CallMethod cancellationTokenNone
                    LoadInt32(
                        int System.Threading.Tasks.TaskContinuationOptions.ExecuteSynchronously
                    )
                    CallMethod taskSchedulerDefault
                    CallGenericMethod(continueWith, [ taskUnitType ])
                    CallGenericMethod(unwrap, [ expression.UnitType ])
                    NewObject valueTaskConstructor
                ]

            let asyncWhileInstructions
                (methodDeclaration: TypedMethodDeclaration)
                kind
                (expression: TypedAsyncWhileExpression)
                =
                let layout = asyncWhileHelperLayout methodDeclaration expression

                let delayConstructor = {
                    DeclaringType = CliDeclaringType layout.DelayType
                    Name = ".ctor"
                    GenericArity = 0
                    IsInstance = true
                    ParameterTypes = [
                        expression.AsyncBooleanType
                        expression.AsyncUnitType
                    ]
                    ReturnType = CliVoid
                    TargetStableId =
                        Some(
                            layout.DelayStableId
                            + "/constructor"
                        )
                }

                let delayInvoke = {
                    DeclaringType = CliDeclaringType layout.DelayType
                    Name = "Invoke"
                    GenericArity = 0
                    IsInstance = true
                    ParameterTypes = [ expression.UnitType ]
                    ReturnType = expression.AsyncUnitType
                    TargetStableId =
                        Some(
                            layout.DelayStableId
                            + "/method:Invoke"
                        )
                }

                let converterType =
                    CliGenericType(
                        expression.ConverterTypeReference,
                        [
                            expression.UnitType
                            expression.AsyncUnitType
                        ]
                    )

                let converterConstructor = {
                    DeclaringType = CliDeclaringType converterType
                    Name = ".ctor"
                    GenericArity = 0
                    IsInstance = true
                    ParameterTypes = [
                        CliObject
                        CliNativeInt
                    ]
                    ReturnType = CliVoid
                    TargetStableId = None
                }

                let functionType =
                    CliGenericType(
                        expression.FSharpFunctionTypeReference,
                        [
                            expression.UnitType
                            expression.AsyncUnitType
                        ]
                    )

                let fromConverter = {
                    DeclaringType = CliDeclaringType functionType
                    Name = "FromConverter"
                    GenericArity = 0
                    IsInstance = false
                    ParameterTypes = [
                        CliGenericType(
                            expression.ConverterTypeReference,
                            [
                                CliTypeParameter 0
                                CliTypeParameter 1
                            ]
                        )
                    ]
                    ReturnType =
                        CliGenericType(
                            expression.FSharpFunctionTypeReference,
                            [
                                CliTypeParameter 0
                                CliTypeParameter 1
                            ]
                        )
                    TargetStableId = None
                }

                let builderType = CliNamedType expression.AsyncBuilderTypeReference

                let defaultAsyncBuilder = {
                    DeclaringType =
                        CliDeclaringType(
                            CliNamedType expression.ExtraTopLevelOperatorsTypeReference
                        )
                    Name = "get_DefaultAsyncBuilder"
                    GenericArity = 0
                    IsInstance = false
                    ParameterTypes = []
                    ReturnType = builderType
                    TargetStableId = None
                }

                let delay = {
                    DeclaringType = CliDeclaringType builderType
                    Name = "Delay"
                    GenericArity = 1
                    IsInstance = true
                    ParameterTypes = [
                        CliGenericType(
                            expression.FSharpFunctionTypeReference,
                            [
                                expression.UnitType
                                CliGenericType(
                                    expression.AsyncTypeReference,
                                    [ CliMethodTypeParameter 0 ]
                                )
                            ]
                        )
                    ]
                    ReturnType =
                        CliGenericType(expression.AsyncTypeReference, [ CliMethodTypeParameter 0 ])
                    TargetStableId = None
                }

                [
                    CallMethod defaultAsyncBuilder
                    LoadArgument(methodArgumentIndex kind expression.GuardParameterIndex)
                    LoadArgument(methodArgumentIndex kind expression.ComputationParameterIndex)
                    NewObject delayConstructor
                    LoadFunctionPointer delayInvoke
                    NewObject converterConstructor
                    CallMethod fromConverter
                    CallGenericMethod(delay, [ expression.UnitType ])
                ]

            let cancellableTaskSequentialInstructions
                (methodDeclaration: TypedMethodDeclaration)
                kind
                (expression: TypedCancellableTaskSequentialExpression)
                =
                let layout = cancellableTaskSequentialHelperLayout methodDeclaration expression

                let constructor = {
                    DeclaringType = CliDeclaringType layout.MethodOuterType
                    Name = ".ctor"
                    GenericArity = 0
                    IsInstance = true
                    ParameterTypes = [
                        methodTypeParametersToTypeParameters expression.SequenceType
                    ]
                    ReturnType = CliVoid
                    TargetStableId = Some layout.OuterConstructorStableId
                }

                let invoke = {
                    DeclaringType = CliDeclaringType layout.MethodOuterType
                    Name = "Invoke"
                    GenericArity = 0
                    IsInstance = true
                    ParameterTypes = [
                        methodTypeParametersToTypeParameters expression.CancellationTokenType
                    ]
                    ReturnType = methodTypeParametersToTypeParameters expression.OutputTaskType
                    TargetStableId = Some layout.OuterInvokeStableId
                }

                let converterType =
                    CliGenericType(
                        expression.ConverterTypeReference,
                        [
                            expression.CancellationTokenType
                            expression.OutputTaskType
                        ]
                    )

                let converterConstructor = {
                    DeclaringType = CliDeclaringType converterType
                    Name = ".ctor"
                    GenericArity = 0
                    IsInstance = true
                    ParameterTypes = [
                        CliObject
                        CliNativeInt
                    ]
                    ReturnType = CliVoid
                    TargetStableId = None
                }

                let fromConverter = {
                    DeclaringType = CliDeclaringType expression.OutputFunctionType
                    Name = "FromConverter"
                    GenericArity = 0
                    IsInstance = false
                    ParameterTypes = [
                        CliGenericType(
                            expression.ConverterTypeReference,
                            [
                                CliTypeParameter 0
                                CliTypeParameter 1
                            ]
                        )
                    ]
                    ReturnType =
                        CliGenericType(
                            expression.FSharpFunctionTypeReference,
                            [
                                CliTypeParameter 0
                                CliTypeParameter 1
                            ]
                        )
                    TargetStableId = None
                }

                [
                    LoadArgument(methodArgumentIndex kind expression.SequenceParameterIndex)
                    NewObject constructor
                    LoadFunctionPointer invoke
                    NewObject converterConstructor
                    CallMethod fromConverter
                ]

            let taskTryFinallyInstructions
                (methodDeclaration: TypedMethodDeclaration)
                kind
                (expression: TypedTaskTryFinallyExpression)
                =
                let layout = taskTryFinallyHelperLayout methodDeclaration expression

                let constructor = {
                    DeclaringType = CliDeclaringType layout.MethodType
                    Name = ".ctor"
                    GenericArity = 0
                    IsInstance = true
                    ParameterTypes = [
                        expression.OutputTaskType
                        expression.CompensationType
                    ]
                    ReturnType = CliVoid
                    TargetStableId = Some layout.ConstructorStableId
                }

                let continueWait = {
                    DeclaringType = CliDeclaringType layout.MethodType
                    Name = "ContinueWait"
                    GenericArity = 0
                    IsInstance = true
                    ParameterTypes = [ expression.NonGenericTaskType ]
                    ReturnType = expression.OutputTaskType
                    TargetStableId = Some layout.ContinueWaitStableId
                }

                let continuationDelegateType =
                    CliGenericType(
                        expression.FuncTypeReference,
                        [
                            expression.NonGenericTaskType
                            expression.OutputTaskType
                        ]
                    )

                let continuationDelegateConstructor = {
                    DeclaringType = CliDeclaringType continuationDelegateType
                    Name = ".ctor"
                    GenericArity = 0
                    IsInstance = true
                    ParameterTypes = [
                        CliObject
                        CliNativeInt
                    ]
                    ReturnType = CliVoid
                    TargetStableId = None
                }

                let continuationDefinitionDelegateType =
                    CliGenericType(
                        expression.FuncTypeReference,
                        [
                            expression.NonGenericTaskType
                            CliMethodTypeParameter 0
                        ]
                    )

                let continueWith = {
                    DeclaringType = CliDeclaringType expression.NonGenericTaskType
                    Name = "ContinueWith"
                    GenericArity = 1
                    IsInstance = true
                    ParameterTypes = [
                        continuationDefinitionDelegateType
                        expression.CancellationTokenType
                        expression.TaskContinuationOptionsType
                        expression.TaskSchedulerType
                    ]
                    ReturnType =
                        CliGenericType(expression.TaskTypeReference, [ CliMethodTypeParameter 0 ])
                    TargetStableId = None
                }

                let cancellationTokenNone = {
                    DeclaringType = CliDeclaringType expression.CancellationTokenType
                    Name = "get_None"
                    GenericArity = 0
                    IsInstance = false
                    ParameterTypes = []
                    ReturnType = expression.CancellationTokenType
                    TargetStableId = None
                }

                let taskSchedulerDefault = {
                    DeclaringType = CliDeclaringType expression.TaskSchedulerType
                    Name = "get_Default"
                    GenericArity = 0
                    IsInstance = false
                    ParameterTypes = []
                    ReturnType = expression.TaskSchedulerType
                    TargetStableId = None
                }

                let unwrap = {
                    DeclaringType =
                        CliDeclaringType(CliNamedType expression.TaskExtensionsTypeReference)
                    Name = "Unwrap"
                    GenericArity = 1
                    IsInstance = false
                    ParameterTypes = [
                        CliGenericType(
                            expression.TaskTypeReference,
                            [
                                CliGenericType(
                                    expression.TaskTypeReference,
                                    [ CliMethodTypeParameter 0 ]
                                )
                            ]
                        )
                    ]
                    ReturnType =
                        CliGenericType(expression.TaskTypeReference, [ CliMethodTypeParameter 0 ])
                    TargetStableId = None
                }

                [
                    LoadArgument(methodArgumentIndex kind expression.WaitParameterIndex)
                    LoadArgument(methodArgumentIndex kind expression.WorkParameterIndex)
                    LoadArgument(methodArgumentIndex kind expression.CompensationParameterIndex)
                    NewObject constructor
                    LoadFunctionPointer continueWait
                    NewObject continuationDelegateConstructor
                    CallMethod cancellationTokenNone
                    LoadInt32(
                        int System.Threading.Tasks.TaskContinuationOptions.ExecuteSynchronously
                    )
                    CallMethod taskSchedulerDefault
                    CallGenericMethod(continueWith, [ expression.OutputTaskType ])
                    CallGenericMethod(unwrap, [ expression.ResultType ])
                ]

            let rec valueExpressionInstructions methodDeclaration freshLabel kind expression =
                let valueExpressionInstructions = valueExpressionInstructions methodDeclaration

                match expression with
                | TypedIntegerLiteral value -> [ LoadInt32 value ], []
                | TypedStringLiteral value -> [ LoadString value ], []
                | TypedNullLiteral -> [ LoadNull ], []
                | TypedUnitLiteral -> [], []
                | TypedReceiverReference -> [ LoadArgument 0 ], []
                | TypedParameterReference index ->
                    [ LoadArgument(methodArgumentIndex kind index) ], []
                | TypedLocalReference index -> [ LoadLocal index ], []
                | TypedLocalAssignment(localIndex, _, value) ->
                    let valueInstructions, valueLocals =
                        valueExpressionInstructions freshLabel kind value

                    valueInstructions
                    @ [ StoreLocal localIndex ],
                    valueLocals
                | TypedAddressOf(source, fields) ->
                    let sourceInstruction =
                        match source with
                        | TypedParameterAddress(index, CliByRef _) ->
                            LoadArgument(methodArgumentIndex kind index)
                        | TypedParameterAddress(index, _) ->
                            LoadArgumentAddress(methodArgumentIndex kind index)
                        | TypedLocalAddress(index, CliByRef _) -> LoadLocal index
                        | TypedLocalAddress(index, _) -> LoadLocalAddress index

                    sourceInstruction
                    :: (fields
                        |> List.map (fun field ->
                            LoadFieldAddress {
                                DeclaringType = CliDeclaringType field.DeclaringType
                                Name = field.Name
                                FieldType = field.FieldType
                                TargetStableId = field.TargetStableId
                            }
                        )),
                    []
                | TypedInstanceFieldGet(receiver, field) ->
                    let receiverInstructions, receiverLocals =
                        valueExpressionInstructions freshLabel kind receiver

                    receiverInstructions
                    @ [
                        LoadField {
                            DeclaringType = CliDeclaringType field.DeclaringType
                            Name = field.Name
                            FieldType = field.FieldType
                            TargetStableId = field.TargetStableId
                        }
                    ],
                    receiverLocals
                | TypedBooleanNegation(expression, range) ->
                    let expressionInstructions, expressionLocals =
                        valueExpressionInstructions freshLabel kind expression

                    [ MarkSequencePoint range ]
                    @ expressionInstructions
                    @ [
                        LoadInt32 0
                        CompareEqual
                        MarkHiddenSequencePoint
                    ],
                    expressionLocals
                | TypedEquality(left, right, _) ->
                    let leftInstructions, leftLocals =
                        valueExpressionInstructions freshLabel kind left

                    let rightInstructions, rightLocals =
                        valueExpressionInstructions freshLabel kind right

                    leftInstructions
                    @ rightInstructions
                    @ [ CompareEqual ],
                    leftLocals
                    @ rightLocals
                | TypedTryWith(body,
                               handlerLocalIndex,
                               handlerName,
                               catchType,
                               handler,
                               tryRange,
                               withRange,
                               bodyRange,
                               handlerRange,
                               _) ->
                    let tryStart = freshLabel ()
                    let tryEnd = freshLabel ()
                    let handlerStart = freshLabel ()
                    let handlerEnd = freshLabel ()
                    let endLabel = freshLabel ()

                    let bodyInstructions, bodyLocals =
                        valueExpressionInstructions freshLabel kind body

                    let handlerInstructions, handlerLocals =
                        valueExpressionInstructions freshLabel kind handler

                    let initialSequencePoint expression range =
                        match expression with
                        | TypedLet _
                        | TypedSequential _
                        | TypedConditional _
                        | TypedBooleanNegation _
                        | TypedTryWith _
                        | TypedNullMatch _
                        | TypedTypeTestMatch _ -> []
                        | _ -> [ MarkSequencePoint range ]

                    [
                        MarkLabel tryStart
                        MarkSequencePoint tryRange
                        Nop
                    ]
                    @ initialSequencePoint body bodyRange
                    @ bodyInstructions
                    @ [
                        Leave endLabel
                        MarkLabel tryEnd
                        MarkLabel handlerStart
                        StoreLocal handlerLocalIndex
                    ]
                    @ (
                        match handler with
                        | TypedTypeTestMatch _ -> []
                        | _ -> [
                            MarkSequencePoint withRange
                            Nop
                          ]
                    )
                    @ initialSequencePoint handler handlerRange
                    @ handlerInstructions
                    @ [
                        Leave endLabel
                        MarkLabel handlerEnd
                        MarkLabel endLabel
                        DefineCatchRegion(tryStart, tryEnd, handlerStart, handlerEnd, catchType)
                    ],
                    bodyLocals
                    @ [
                        {
                            Index = handlerLocalIndex
                            Name = handlerName
                            Type = catchType
                        }
                    ]
                    @ handlerLocals
                | TypedLet(localIndex, name, _, localType, value, body, bindingRange, bodyRange) ->
                    let valueInstructions, valueLocals =
                        valueExpressionInstructions freshLabel kind value

                    let bodyInstructions, bodyLocals =
                        valueExpressionInstructions freshLabel kind body

                    let bodySequencePoint =
                        match body with
                        | TypedLet _
                        | TypedSequential _
                        | TypedConditional _
                        | TypedBooleanNegation _
                        | TypedTryWith _
                        | TypedNullMatch _
                        | TypedTypeTestMatch _ -> []
                        | _ -> [ MarkSequencePoint bodyRange ]

                    [ MarkSequencePoint bindingRange ]
                    @ valueInstructions
                    @ [ StoreLocal localIndex ]
                    @ bodySequencePoint
                    @ bodyInstructions,
                    valueLocals
                    @ [
                        {
                            Index = localIndex
                            Name = name
                            Type = localType
                        }
                    ]
                    @ bodyLocals
                | TypedStaticMethodCall(target, genericArguments, arguments) ->
                    let loweredArguments =
                        arguments
                        |> List.map (valueExpressionInstructions freshLabel kind)

                    let declaringType =
                        match target.DeclaringType with
                        | CliNamedType typeReference when
                            String.IsNullOrEmpty(typeReference.AssemblyName)
                            && typeReference.DeclarationId.StartsWith(
                                "module:",
                                StringComparison.Ordinal
                            )
                            ->
                            CliNamedType {
                                typeReference with
                                    DeclarationId =
                                        moduleStableId
                                        + "/type:"
                                        + typeReference.DeclarationId
                            }
                        | cliType -> cliType

                    let omittedOptionalArguments =
                        List.replicate
                            (target.ParameterTypes.Length
                             - arguments.Length)
                            LoadNull

                    let methodReference = {
                        DeclaringType = CliDeclaringType declaringType
                        Name = target.Name
                        GenericArity = target.GenericArity
                        IsInstance = false
                        ParameterTypes = target.ParameterTypes
                        ReturnType = target.ReturnType
                        TargetStableId = Some target.StableId
                    }

                    let callInstruction =
                        if List.isEmpty genericArguments then
                            CallMethod methodReference
                        else
                            CallGenericMethod(methodReference, genericArguments)

                    let intrinsicSequencePoints =
                        if
                            target.StableId.EndsWith("|intrinsic|isNull", StringComparison.Ordinal)
                        then
                            [
                                MarkHiddenSequencePoint
                                Nop
                                MarkHiddenSequencePoint
                                Nop
                                MarkHiddenSequencePoint
                                Nop
                            ]
                        else
                            []

                    (loweredArguments
                     |> List.collect fst)
                    @ omittedOptionalArguments
                    @ [ callInstruction ]
                    @ intrinsicSequencePoints,
                    (loweredArguments
                     |> List.collect snd)
                | TypedObjectConstruction(target, arguments) ->
                    let loweredArguments =
                        arguments
                        |> List.map (valueExpressionInstructions freshLabel kind)

                    let argumentInstructions =
                        match target.ParamArrayElementType with
                        | None ->
                            loweredArguments
                            |> List.collect fst
                        | Some elementType ->
                            let fixedArgumentCount =
                                target.ParameterTypes.Length
                                - 1

                            let fixedArguments, variadicArguments =
                                loweredArguments
                                |> List.splitAt fixedArgumentCount

                            (fixedArguments
                             |> List.collect fst)
                            @ [
                                LoadInt32 variadicArguments.Length
                                NewArray elementType
                            ]
                            @ (variadicArguments
                               |> List.mapi (fun index (instructions, _) -> [
                                   Duplicate
                                   LoadInt32 index
                                   yield! instructions
                                   StoreArrayElementReference
                               ])
                               |> List.collect id)

                    let constructorReference = {
                        DeclaringType = CliDeclaringType target.DeclaringType
                        Name = ".ctor"
                        GenericArity = 0
                        IsInstance = true
                        ParameterTypes = target.ParameterTypes
                        ReturnType = CliVoid
                        TargetStableId = Some target.StableId
                    }

                    argumentInstructions
                    @ [ NewObject constructorReference ],
                    (loweredArguments
                     |> List.collect snd)
                | TypedDefaultValue(valueType, localIndex) ->
                    [
                        LoadLocalAddress localIndex
                        InitializeObject valueType
                        LoadLocal localIndex
                    ],
                    [
                        {
                            Index = localIndex
                            Name = "defaultValue"
                            Type = valueType
                        }
                    ]
                | TypedValueTaskOfUnit expression ->
                    valueTaskOfUnitInstructions methodDeclaration kind expression, []
                | TypedAsyncWhile expression ->
                    asyncWhileInstructions methodDeclaration kind expression, []
                | TypedFunctionApplication(functionType,
                                           domainType,
                                           rangeType,
                                           functionExpression,
                                           argumentExpression) ->
                    let functionInstructions, functionLocals =
                        valueExpressionInstructions freshLabel kind functionExpression

                    let argumentInstructions, argumentLocals =
                        match domainType, argumentExpression with
                        | CliNamedType typeReference, TypedUnitLiteral when
                            typeReference.AssemblyName = "FSharp.Core"
                            && typeReference.TypeName.Namespace = "Microsoft.FSharp.Core"
                            && typeReference.TypeName.Name = "Unit"
                            ->
                            [ LoadNull ], []
                        | _ -> valueExpressionInstructions freshLabel kind argumentExpression

                    let invoke = {
                        DeclaringType = CliDeclaringType functionType
                        Name = "Invoke"
                        GenericArity = 0
                        IsInstance = true
                        ParameterTypes = [ CliTypeParameter 0 ]
                        ReturnType = CliTypeParameter 1
                        TargetStableId = None
                    }

                    functionInstructions
                    @ argumentInstructions
                    @ [ CallVirtualMethod invoke ],
                    functionLocals
                    @ argumentLocals
                | TypedInstanceMethodCall(target, receiver, arguments) ->
                    let loweredArguments =
                        arguments
                        |> List.map (valueExpressionInstructions freshLabel kind)

                    let methodReference = {
                        DeclaringType = CliDeclaringType target.DeclaringType
                        Name = target.Name
                        GenericArity = 0
                        IsInstance = true
                        ParameterTypes = target.ParameterTypes
                        ReturnType = target.ReturnType
                        TargetStableId = None
                    }

                    let isValueTypeReceiver =
                        match target.DeclaringType with
                        | CliNamedType typeReference
                        | CliGenericType(typeReference, _) -> typeReference.IsValueType
                        | CliInt32
                        | CliBoolean
                        | CliNativeInt -> true
                        | CliString
                        | CliObject
                        | CliVoid
                        | CliByRef _
                        | CliArray _
                        | CliTypeParameter _
                        | CliMethodTypeParameter _ -> false

                    let receiverInstructions, receiverLocals, callInstruction =
                        if isValueTypeReceiver then
                            match receiver with
                            | TypedInstanceFieldGet(TypedReceiverReference, field) ->
                                [
                                    LoadArgument 0
                                    LoadFieldAddress {
                                        DeclaringType = CliDeclaringType field.DeclaringType
                                        Name = field.Name
                                        FieldType = field.FieldType
                                        TargetStableId = field.TargetStableId
                                    }
                                ],
                                [],
                                CallMethod methodReference
                            | TypedParameterReference index ->
                                [ LoadArgumentAddress(methodArgumentIndex kind index) ],
                                [],
                                CallMethod methodReference
                            | TypedLocalReference index ->
                                [ LoadLocalAddress index ], [], CallMethod methodReference
                            | _ ->
                                invalidOp
                                    "a value-type instance call requires an addressable receiver"
                        else
                            let receiverInstructions, receiverLocals =
                                valueExpressionInstructions freshLabel kind receiver

                            receiverInstructions, receiverLocals, CallVirtualMethod methodReference

                    receiverInstructions
                    @ (loweredArguments
                       |> List.collect fst)
                    @ [ callInstruction ],
                    receiverLocals
                    @ (loweredArguments
                       |> List.collect snd)
                | TypedUpcast(sourceType, _, _, expression) ->
                    let expressionInstructions, expressionLocals =
                        valueExpressionInstructions freshLabel kind expression

                    let conversionInstructions =
                        match sourceType with
                        | CliInt32
                        | CliBoolean
                        | CliNativeInt
                        | CliTypeParameter _
                        | CliMethodTypeParameter _ -> [ Box sourceType ]
                        | CliNamedType typeReference
                        | CliGenericType(typeReference, _) when typeReference.IsValueType -> [
                            Box sourceType
                          ]
                        | CliString
                        | CliObject
                        | CliVoid
                        | CliNamedType _
                        | CliGenericType _
                        | CliByRef _
                        | CliArray _ -> []

                    expressionInstructions
                    @ conversionInstructions,
                    expressionLocals
                | TypedSequential expressions ->
                    let expressionCount = expressions.Length

                    let loweredExpressions =
                        expressions
                        |> List.mapi (fun index (expression, expressionType, expressionRange) ->
                            let instructions, locals =
                                valueExpressionInstructions freshLabel kind expression

                            let sequencePoint =
                                match expression with
                                | TypedUnitLiteral -> [
                                    MarkSequencePoint expressionRange
                                    Nop
                                  ]
                                | TypedConditional _
                                | TypedBooleanNegation _
                                | TypedLet _
                                | TypedSequential _
                                | TypedTryWith _
                                | TypedNullMatch _
                                | TypedTypeTestMatch _ -> []
                                | _ -> [ MarkSequencePoint expressionRange ]

                            sequencePoint
                            @ instructions
                            @ (if
                                   index < expressionCount
                                           - 1
                                   && expressionType
                                      <> CliVoid
                               then
                                   [ Pop ]
                               else
                                   []),
                            locals
                        )

                    loweredExpressions
                    |> List.collect fst,
                    loweredExpressions
                    |> List.collect snd
                | TypedConditional(condition,
                                   ifTrue,
                                   ifFalse,
                                   conditionRange,
                                   ifTrueRange,
                                   ifFalseRange) ->
                    let falseLabel = freshLabel ()
                    let endLabel = freshLabel ()

                    let conditionInstructions, conditionLocals, conditionPrefix =
                        match condition with
                        | TypedConditional(andLeft,
                                           andRight,
                                           TypedIntegerLiteral 0,
                                           andLeftRange,
                                           andRightRange,
                                           syntheticFalseRange) when
                            syntheticFalseRange.Start = syntheticFalseRange.End
                            ->
                            let andFalseLabel = freshLabel ()
                            let andEndLabel = freshLabel ()

                            let andLeftInstructions, andLeftLocals =
                                valueExpressionInstructions freshLabel kind andLeft

                            let andRightInstructions, andRightLocals =
                                valueExpressionInstructions freshLabel kind andRight

                            [ MarkSequencePoint andLeftRange ]
                            @ andLeftInstructions
                            @ [
                                BranchIfFalse andFalseLabel
                                MarkSequencePoint andRightRange
                            ]
                            @ andRightInstructions
                            @ [
                                Branch andEndLabel
                                MarkLabel andFalseLabel
                                LoadInt32 0
                                MarkLabel andEndLabel
                                MarkHiddenSequencePoint
                                Nop
                                MarkHiddenSequencePoint
                                Nop
                                MarkHiddenSequencePoint
                                Nop
                                MarkHiddenSequencePoint
                                Nop
                            ],
                            andLeftLocals
                            @ andRightLocals,
                            [
                                MarkSequencePoint conditionRange
                                Nop
                            ]
                        | _ ->
                            let instructions, locals =
                                valueExpressionInstructions freshLabel kind condition

                            let boundary =
                                match instructions with
                                | MarkSequencePoint _ :: _
                                | MarkHiddenSequencePoint :: _ -> [ Nop ]
                                | _ -> []

                            instructions,
                            locals,
                            [
                                MarkSequencePoint conditionRange
                                Nop
                                MarkHiddenSequencePoint
                            ]
                            @ boundary

                    let ifTrueInstructions, ifTrueLocals =
                        valueExpressionInstructions freshLabel kind ifTrue

                    let ifFalseInstructions, ifFalseLocals =
                        valueExpressionInstructions freshLabel kind ifFalse

                    let ifTrueSequencePoint =
                        match ifTrue with
                        | TypedSequential _
                        | TypedUnitLiteral -> []
                        | _ -> [ MarkSequencePoint ifTrueRange ]

                    let ifFalseSequencePoint =
                        match ifFalse with
                        | TypedSequential _
                        | TypedUnitLiteral -> []
                        | _ -> [ MarkSequencePoint ifFalseRange ]

                    let joinInstructions =
                        match ifFalse with
                        | TypedUnitLiteral -> [
                            MarkHiddenSequencePoint
                            Branch endLabel
                            MarkLabel falseLabel
                            MarkHiddenSequencePoint
                            Nop
                            MarkLabel endLabel
                          ]
                        | _ ->
                            [
                                Branch endLabel
                                MarkLabel falseLabel
                            ]
                            @ ifFalseSequencePoint
                            @ ifFalseInstructions
                            @ [ MarkLabel endLabel ]

                    conditionPrefix
                    @ conditionInstructions
                    @ [ BranchIfFalse falseLabel ]
                    @ ifTrueSequencePoint
                    @ ifTrueInstructions
                    @ joinInstructions,
                    conditionLocals
                    @ ifTrueLocals
                    @ ifFalseLocals
                | TypedPatternMatch expression ->
                    let endLabel = freshLabel ()

                    let inputInstructions, inputLocals =
                        valueExpressionInstructions freshLabel kind expression.Input

                    let decisionHiddenPointCount =
                        expression.Clauses
                        |> List.collect (fun clause ->
                            clause.Operations
                            |> List.choose (
                                function
                                | TypedPatternTypeTest(input, targetType, _, _) ->
                                    Some(
                                        TypeIdentity.inlineBody input,
                                        TypeIdentity.cliType targetType
                                    )
                                | TypedPatternBinding _ -> None
                            )
                        )
                        |> List.groupBy fst
                        |> List.sumBy (fun (_, tests) ->
                            tests
                            |> List.map snd
                            |> List.distinct
                            |> List.length
                            |> fun targetCount ->
                                max
                                    0
                                    (targetCount
                                     - 1)
                        )
                        |> (+) 1

                    let decisionSequencePoints = [
                        for _ in 1..decisionHiddenPointCount do
                            MarkHiddenSequencePoint
                            Nop
                    ]

                    let operationInstructions failureLabel =
                        function
                        | TypedPatternTypeTest(input, targetType, localIndex, localName) ->
                            let instructions, locals =
                                valueExpressionInstructions freshLabel kind input

                            instructions
                            @ [
                                IsInstance targetType
                                StoreLocal localIndex
                                LoadLocal localIndex
                                BranchIfFalse failureLabel
                            ],
                            locals
                            @ [
                                {
                                    Index = localIndex
                                    Name = localName
                                    Type = targetType
                                }
                            ]
                        | TypedPatternBinding(input, inputType, localIndex, name) ->
