                    @ (clauseBodySets
                       |> List.collect id)
                    @ [ MarkLabel endLabel ],
                    inputLocals
                    @ [
                        {
                            Index = expression.InputLocalIndex
                            Name = "$fsharp2MatchInput"
                            Type = expression.InputType
