                                            {
                                                Name = "source"
                                                Type = nonGenericTaskType
                                                Attributes = []
                                            }
                                            {
                                                Name = "state"
                                                Type = CliObject
                                                Attributes = []
                                            }
                                        ]
                                        Locals = [
                                            {
                                                Index = 0
                                                Name = "awaiter"
                                                Type = taskAwaiterType
                                            }
                                            {
                                                Index = 1
                                                Name = "cancellationError"
                                                Type = expression.OperationCanceledExceptionType
                                            }
                                            {
                                                Index = 2
                                                Name = "error"
                                                Type = expression.ExceptionType
                                            }
                                            {
                                                Index = 3
                                                Name = "result"
                                                Type = taskUnitType
                                            }
                                        ]
                                        ReturnType = taskUnitType
                                        Instructions = continuationInstructions
                                        EmitDefaultSequencePoint = true
                                        MaxStack = 2
                                        DependencyIds =
                                            instructionDependencyIds continuationInstructions
                                            @ (cliTypeDependencyIds nonGenericTaskType)
                                            @ (cliTypeDependencyIds taskUnitType)
                                            |> List.distinct
                                        SemanticFingerprint =
                                            Fingerprint.parts [
                                                layout.ContinuationStableId
                                                methodImplementationHash methodDeclaration
                                            ]
                                        DocumentIndex = typed.DocumentIndex
                                        DocumentChecksum = typed.SourceChecksum
                                        Range = expression.Range
                                    }

                                    {
                                        SchemaVersion = querySchema
                                        StableId = layout.StableId
                                        Namespace = String.Empty
                                        Name = layout.Name
                                        IsPublic = false
                                        EnclosingTypeStableId = Some moduleDeclaration.StableId
                                        Kind = ClosureContainer
                                        GenericParameters = methodDeclaration.GenericParameters
                                        Attributes = []
                                        LiteralFields = []
                                        InstanceFields = []
                                        StaticFields = []
                                        Properties = []
                                        Methods = [ continuationMethod ]
                                    }
                                )
                            )
                        | TypedMethod _
                        | TypedLiteralField _
                        | TypedTypeAbbreviation _
                        | TypedStaticType _
                        | TypedObjectType _
                        | TypedStructType _ -> []
                    )
                )

            let asyncWhileHelperTypes =
                modulesWithContentHashes
                |> List.collect (fun (typed, declarationsWithContentHashes) ->
                    let rec nestedModuleMethods (moduleDeclaration: TypedNestedModuleDeclaration) =
                        moduleDeclaration.Methods
                        @ (moduleDeclaration.Extensions
                           |> List.collect (fun typeDeclaration ->
                               typeDeclaration.Methods
                               |> List.map _.Method
                           ))
                        @ (moduleDeclaration.Modules
                           |> List.collect nestedModuleMethods)

                    let declarationMethods =
                        function
                        | TypedMethod methodDeclaration -> [ methodDeclaration ]
                        | TypedNestedModule moduleDeclaration ->
                            nestedModuleMethods moduleDeclaration
                        | TypedStaticType typeDeclaration -> typeDeclaration.Methods
                        | TypedObjectType typeDeclaration ->
                            typeDeclaration.Methods
                            |> List.map _.Method
                        | TypedLiteralField _
                        | TypedTypeAbbreviation _
                        | TypedStructType _ -> []

                    declarationsWithContentHashes
                    |> List.collect (fun (declaration, _) ->
                        declaration
                        |> declarationMethods
                        |> List.collect (fun methodDeclaration ->
                            match methodDeclaration.Body with
                            | TypedAsyncWhile expression ->
                                let layout = asyncWhileHelperLayout methodDeclaration expression

                                let objectConstructor = {
                                    DeclaringType =
                                        CoreDeclaringType {
                                            Namespace = "System"
                                            Name = "Object"
                                        }
                                    Name = ".ctor"
                                    GenericArity = 0
                                    IsInstance = true
                                    ParameterTypes = []
                                    ReturnType = CliVoid
                                    TargetStableId = None
                                }

                                let builderType =
                                    CliNamedType expression.AsyncBuilderTypeReference

                                let defaultAsyncBuilder = {
                                    DeclaringType =
                                        CliDeclaringType(
                                            CliNamedType
                                                expression.ExtraTopLevelOperatorsTypeReference
                                        )
                                    Name = "get_DefaultAsyncBuilder"
                                    GenericArity = 0
                                    IsInstance = false
                                    ParameterTypes = []
                                    ReturnType = builderType
                                    TargetStableId = None
                                }

                                let zero = {
                                    DeclaringType = CliDeclaringType builderType
                                    Name = "Zero"
                                    GenericArity = 0
                                    IsInstance = true
                                    ParameterTypes = []
                                    ReturnType = expression.AsyncUnitType
                                    TargetStableId = None
                                }

                                let bind = {
                                    DeclaringType = CliDeclaringType builderType
                                    Name = "Bind"
                                    GenericArity = 2
                                    IsInstance = true
                                    ParameterTypes = [
                                        CliGenericType(
                                            expression.AsyncTypeReference,
                                            [ CliMethodTypeParameter 0 ]
                                        )
                                        CliGenericType(
                                            expression.FSharpFunctionTypeReference,
                                            [
                                                CliMethodTypeParameter 0
                                                CliGenericType(
                                                    expression.AsyncTypeReference,
                                                    [ CliMethodTypeParameter 1 ]
                                                )
                                            ]
                                        )
                                    ]
                                    ReturnType =
                                        CliGenericType(
                                            expression.AsyncTypeReference,
                                            [ CliMethodTypeParameter 1 ]
                                        )
                                    TargetStableId = None
                                }

                                let predicateFunctionType =
                                    CliGenericType(
                                        expression.FSharpFunctionTypeReference,
                                        [
                                            expression.UnitType
                                            CliBoolean
                                        ]
                                    )

                                let whileMethod = {
                                    DeclaringType = CliDeclaringType builderType
                                    Name = "While"
                                    GenericArity = 0
                                    IsInstance = true
                                    ParameterTypes = [
                                        predicateFunctionType
                                        expression.AsyncUnitType
                                    ]
                                    ReturnType = expression.AsyncUnitType
                                    TargetStableId = None
                                }

                                let fieldReference declaringType stableId name fieldType = {
                                    DeclaringType = CliDeclaringType declaringType
                                    Name = name
                                    FieldType = fieldType
                                    TargetStableId = Some stableId
                                }

                                let stateGuardField =
                                    fieldReference
                                        layout.StateType
                                        (layout.StateStableId
                                         + "/field:guard")
                                        "guard"
                                        expression.AsyncBooleanType

                                let stateComputationField =
                                    fieldReference
                                        layout.StateType
                                        (layout.StateStableId
                                         + "/field:computation")
                                        "computation"
                                        expression.AsyncUnitType

                                let stateKeepGoingField =
                                    fieldReference
                                        layout.StateType
                                        (layout.StateStableId
                                         + "/field:keepGoing")
                                        "keepGoing"
                                        CliBoolean

                                let delayGuardField =
                                    fieldReference
                                        layout.DelayType
                                        (layout.DelayStableId
                                         + "/field:guard")
                                        "guard"
                                        expression.AsyncBooleanType

                                let delayComputationField =
                                    fieldReference
                                        layout.DelayType
                                        (layout.DelayStableId
                                         + "/field:computation")
                                        "computation"
                                        expression.AsyncUnitType

                                let predicateStateField =
                                    fieldReference
                                        layout.PredicateType
                                        (layout.PredicateStableId
                                         + "/field:state")
                                        "state"
                                        layout.StateType

                                let bindStateField =
                                    fieldReference
                                        layout.BindType
                                        (layout.BindStableId
                                         + "/field:state")
                                        "state"
                                        layout.StateType

                                let constructorReference stableId declaringType parameterTypes = {
                                    DeclaringType = CliDeclaringType declaringType
                                    Name = ".ctor"
                                    GenericArity = 0
                                    IsInstance = true
                                    ParameterTypes = parameterTypes
                                    ReturnType = CliVoid
                                    TargetStableId =
                                        Some(
                                            stableId
                                            + "/constructor"
                                        )
                                }

                                let invokeReference
                                    stableId
                                    declaringType
                                    parameterType
                                    returnType
                                    =
                                    {
                                        DeclaringType = CliDeclaringType declaringType
                                        Name = "Invoke"
                                        GenericArity = 0
                                        IsInstance = true
                                        ParameterTypes = [ parameterType ]
                                        ReturnType = returnType
                                        TargetStableId =
                                            Some(
                                                stableId
                                                + "/method:Invoke"
                                            )
                                    }

                                let converterType inputType outputType =
                                    CliGenericType(
                                        expression.ConverterTypeReference,
                                        [
                                            inputType
                                            outputType
                                        ]
                                    )

                                let functionType inputType outputType =
                                    CliGenericType(
                                        expression.FSharpFunctionTypeReference,
                                        [
                                            inputType
                                            outputType
                                        ]
                                    )

                                let converterConstructor inputType outputType = {
                                    DeclaringType =
                                        CliDeclaringType(converterType inputType outputType)
                                    Name = ".ctor"
                                    GenericArity = 0
                                    IsInstance = true
                                    ParameterTypes = [
                                        CliObject
                                        CliNativeInt
                                    ]
                                    ReturnType = CliVoid
                                    TargetStableId = None
                                }

                                let fromConverter inputType outputType = {
                                    DeclaringType =
                                        CliDeclaringType(functionType inputType outputType)
                                    Name = "FromConverter"
                                    GenericArity = 0
                                    IsInstance = false
                                    ParameterTypes = [
                                        CliGenericType(
                                            expression.ConverterTypeReference,
                                            [
                                                CliTypeParameter 0
                                                CliTypeParameter 1
                                            ]
                                        )
                                    ]
                                    ReturnType =
                                        CliGenericType(
                                            expression.FSharpFunctionTypeReference,
                                            [
                                                CliTypeParameter 0
                                                CliTypeParameter 1
                                            ]
                                        )
                                    TargetStableId = None
                                }

                                let closureFunctionInstructions
                                    stableId
                                    closureType
                                    inputType
                                    outputType
                                    parameterTypes
                                    captureInstructions
                                    =
                                    captureInstructions
                                    @ [
                                        NewObject(
                                            constructorReference
                                                stableId
                                                closureType
                                                parameterTypes
                                        )
                                        LoadFunctionPointer(
                                            invokeReference
                                                stableId
                                                closureType
                                                inputType
                                                outputType
                                        )
                                        NewObject(converterConstructor inputType outputType)
                                        CallMethod(fromConverter inputType outputType)
                                    ]

                                let methodFragment
                                    stableId
                                    name
                                    kind
                                    parameters
                                    locals
                                    returnType
                                    instructions
                                    =
                                    {
                                        SchemaVersion = querySchema
                                        StableId = stableId
                                        Name = name
                                        Kind = kind
                                        GenericParameters = []
                                        Constraints = []
                                        GenericParameterConstraints = []
                                        Attributes = []
                                        Parameters = parameters
                                        Locals = locals
                                        ReturnType = returnType
                                        Instructions = instructions
                                        EmitDefaultSequencePoint = true
                                        MaxStack = 8
                                        DependencyIds =
                                            instructionDependencyIds instructions
                                            @ (cliTypeDependencyIds returnType)
                                            |> List.distinct
                                        SemanticFingerprint =
                                            Fingerprint.parts [
                                                stableId
                                                methodImplementationHash methodDeclaration
                                                yield! instructionDependencyIds instructions
                                            ]
                                        DocumentIndex = typed.DocumentIndex
                                        DocumentChecksum = typed.SourceChecksum
                                        Range = expression.Range
                                    }

                                let fieldFragment stableId name fieldType = {
                                    SchemaVersion = querySchema
                                    StableId = stableId
                                    Name = name
                                    Type = fieldType
                                    Attributes = []
                                    SemanticFingerprint =
                                        Fingerprint.parts [
                                            stableId
                                            TypeIdentity.cliType fieldType
                                        ]
                                }

                                let typeFragment stableId name fields methods = {
                                    SchemaVersion = querySchema
                                    StableId = stableId
                                    Namespace = typed.Namespace
                                    Name = name
                                    IsPublic = false
                                    EnclosingTypeStableId = None
                                    Kind = ClosureContainer
                                    GenericParameters = []
                                    Attributes = []
                                    LiteralFields = []
                                    InstanceFields = fields
                                    StaticFields = []
                                    Properties = []
                                    Methods = methods
                                }

                                let stateConstructorInstructions = [
                                    LoadArgument 0
                                    CallMethod objectConstructor
                                    LoadArgument 0
                                    LoadArgument 1
                                    StoreField stateGuardField
                                    LoadArgument 0
                                    LoadArgument 2
                                    StoreField stateComputationField
                                    LoadArgument 0
                                    LoadInt32 1
                                    StoreField stateKeepGoingField
                                    Return
                                ]

                                let stateConstructor =
                                    methodFragment
                                        (layout.StateStableId
                                         + "/constructor")
                                        ".ctor"
                                        ClosureConstructor
                                        [
                                            {
                                                Name = "guard"
                                                Type = expression.AsyncBooleanType
                                                Attributes = []
                                            }
                                            {
                                                Name = "computation"
                                                Type = expression.AsyncUnitType
                                                Attributes = []
                                            }
                                        ]
                                        []
                                        CliVoid
                                        stateConstructorInstructions

                                let stateType =
                                    typeFragment layout.StateStableId layout.StateName [
                                        fieldFragment
                                            (layout.StateStableId
                                             + "/field:guard")
                                            "guard"
                                            expression.AsyncBooleanType
                                        fieldFragment
                                            (layout.StateStableId
                                             + "/field:computation")
                                            "computation"
                                            expression.AsyncUnitType
                                        fieldFragment
                                            (layout.StateStableId
                                             + "/field:keepGoing")
                                            "keepGoing"
                                            CliBoolean
                                    ] [ stateConstructor ]

                                let simpleCaptureConstructor
                                    stableId
                                    captureName
                                    captureType
                                    captureField
                                    =
                                    let instructions = [
                                        LoadArgument 0
                                        CallMethod objectConstructor
                                        LoadArgument 0
                                        LoadArgument 1
                                        StoreField captureField
                                        Return
                                    ]

                                    methodFragment
                                        (stableId
                                         + "/constructor")
                                        ".ctor"
                                        ClosureConstructor
                                        [
                                            {
                                                Name = captureName
                                                Type = captureType
                                                Attributes = []
                                            }
                                        ]
                                        []
                                        CliVoid
                                        instructions

                                let delayConstructorInstructions = [
                                    LoadArgument 0
                                    CallMethod objectConstructor
                                    LoadArgument 0
                                    LoadArgument 1
                                    StoreField delayGuardField
                                    LoadArgument 0
                                    LoadArgument 2
                                    StoreField delayComputationField
                                    Return
                                ]

                                let delayConstructor =
                                    methodFragment
                                        (layout.DelayStableId
                                         + "/constructor")
                                        ".ctor"
                                        ClosureConstructor
                                        [
                                            {
                                                Name = "guard"
                                                Type = expression.AsyncBooleanType
                                                Attributes = []
                                            }
                                            {
                                                Name = "computation"
                                                Type = expression.AsyncUnitType
                                                Attributes = []
                                            }
                                        ]
                                        []
                                        CliVoid
                                        delayConstructorInstructions

                                let stateConstructorReference =
                                    constructorReference layout.StateStableId layout.StateType [
                                        expression.AsyncBooleanType
                                        expression.AsyncUnitType
                                    ]

                                let delayInvokeInstructions = [
                                    CallMethod defaultAsyncBuilder
                                    StoreLocal 1
                                    LoadArgument 0
                                    LoadField delayGuardField
                                    LoadArgument 0
                                    LoadField delayComputationField
                                    NewObject stateConstructorReference
                                    StoreLocal 0
                                    LoadLocal 1

                                    yield!
                                        closureFunctionInstructions
                                            layout.PredicateStableId
                                            layout.PredicateType
                                            expression.UnitType
                                            CliBoolean [ layout.StateType ] [ LoadLocal 0 ]

                                    LoadLocal 1
                                    LoadLocal 0
                                    LoadField stateGuardField

                                    yield!
                                        closureFunctionInstructions
                                            layout.BindStableId
                                            layout.BindType
                                            CliBoolean
                                            expression.AsyncUnitType [ layout.StateType ] [
                                                LoadLocal 0
                                            ]

                                    CallGenericMethod(
                                        bind,
                                        [
                                            CliBoolean
                                            expression.UnitType
                                        ]
                                    )
                                    CallMethod whileMethod
                                    Return
                                ]

                                let delayInvoke =
                                    methodFragment
                                        (layout.DelayStableId
                                         + "/method:Invoke")
                                        "Invoke"
                                        ClosureInvoke
                                        [
                                            {
                                                Name = "unitVar"
                                                Type = expression.UnitType
                                                Attributes = []
                                            }
                                        ]
                                        [
                                            {
                                                Index = 0
                                                Name = "state"
                                                Type = layout.StateType
                                            }
                                            {
                                                Index = 1
                                                Name = "builder"
                                                Type = builderType
                                            }
                                        ]
                                        expression.AsyncUnitType
                                        delayInvokeInstructions

                                let delayType =
                                    typeFragment layout.DelayStableId layout.DelayName [
                                        fieldFragment
                                            (layout.DelayStableId
                                             + "/field:guard")
                                            "guard"
                                            expression.AsyncBooleanType
                                        fieldFragment
                                            (layout.DelayStableId
                                             + "/field:computation")
                                            "computation"
                                            expression.AsyncUnitType
                                    ] [
                                        delayConstructor
                                        delayInvoke
                                    ]

                                let predicateConstructor =
                                    simpleCaptureConstructor
                                        layout.PredicateStableId
                                        "state"
                                        layout.StateType
                                        predicateStateField

                                let predicateInvokeInstructions = [
                                    LoadArgument 0
                                    LoadField predicateStateField
                                    LoadField stateKeepGoingField
                                    Return
                                ]

                                let predicateInvoke =
                                    methodFragment
                                        (layout.PredicateStableId
                                         + "/method:Invoke")
                                        "Invoke"
                                        ClosureInvoke
                                        [
                                            {
                                                Name = "unitVar"
                                                Type = expression.UnitType
                                                Attributes = []
                                            }
                                        ]
                                        []
                                        CliBoolean
                                        predicateInvokeInstructions

                                let predicateType =
                                    typeFragment layout.PredicateStableId layout.PredicateName [
                                        fieldFragment
                                            (layout.PredicateStableId
                                             + "/field:state")
                                            "state"
                                            layout.StateType
                                    ] [
                                        predicateConstructor
                                        predicateInvoke
                                    ]

                                let unitConstructorInstructions = [
                                    LoadArgument 0
                                    CallMethod objectConstructor
                                    Return
                                ]

                                let unitConstructor =
                                    methodFragment
                                        (layout.UnitStableId
                                         + "/constructor")
                                        ".ctor"
                                        ClosureConstructor
                                        []
                                        []
                                        CliVoid
                                        unitConstructorInstructions

                                let unitInvokeInstructions = [
                                    CallMethod defaultAsyncBuilder
                                    CallMethod zero
                                    Return
                                ]

                                let unitInvoke =
                                    methodFragment
                                        (layout.UnitStableId
                                         + "/method:Invoke")
                                        "Invoke"
                                        ClosureInvoke
                                        [
                                            {
                                                Name = "unitVar"
                                                Type = expression.UnitType
                                                Attributes = []
                                            }
                                        ]
                                        []
                                        expression.AsyncUnitType
                                        unitInvokeInstructions

                                let unitType =
                                    typeFragment layout.UnitStableId layout.UnitName [] [
                                        unitConstructor
                                        unitInvoke
                                    ]

                                let bindConstructor =
                                    simpleCaptureConstructor
                                        layout.BindStableId
                                        "state"
                                        layout.StateType
                                        bindStateField

                                let falseLabel = 0

                                let bindInvokeInstructions = [
                                    LoadArgument 1
                                    BranchIfFalse falseLabel
                                    CallMethod defaultAsyncBuilder
                                    LoadArgument 0
                                    LoadField bindStateField
                                    LoadField stateComputationField

                                    yield!
                                        closureFunctionInstructions
                                            layout.UnitStableId
                                            layout.UnitClosureType
                                            expression.UnitType
                                            expression.AsyncUnitType [] []

                                    CallGenericMethod(
                                        bind,
                                        [
                                            expression.UnitType
                                            expression.UnitType
                                        ]
                                    )
                                    Return
                                    MarkLabel falseLabel
                                    LoadArgument 0
                                    LoadField bindStateField
                                    LoadInt32 0
                                    StoreField stateKeepGoingField
                                    CallMethod defaultAsyncBuilder
                                    CallMethod zero
                                    Return
                                ]

                                let bindInvoke =
                                    methodFragment
                                        (layout.BindStableId
                                         + "/method:Invoke")
                                        "Invoke"
                                        ClosureInvoke
                                        [
                                            {
                                                Name = "guardResult"
                                                Type = CliBoolean
                                                Attributes = []
                                            }
                                        ]
                                        []
                                        expression.AsyncUnitType
                                        bindInvokeInstructions

                                let bindType =
                                    typeFragment layout.BindStableId layout.BindName [
                                        fieldFragment
                                            (layout.BindStableId
                                             + "/field:state")
                                            "state"
                                            layout.StateType
                                    ] [
                                        bindConstructor
                                        bindInvoke
                                    ]

                                [
                                    stateType
                                    delayType
                                    predicateType
                                    bindType
                                    unitType
                                ]
                            | _ -> []
                        )
                    )
                )

            let staticTypes =
                modulesWithContentHashes
                |> List.map (fun (typed, declarationsWithContentHashes) ->
                    let documentIndex = typed.DocumentIndex

                    declarationsWithContentHashes
                    |> List.choose (fun (declaration, typeContentHash) ->
                        match declaration with
                        | TypedStaticType typeDeclaration ->
                            let methods =
                                typeDeclaration.Methods
                                |> List.map (fun methodDeclaration ->
                                    let kind =
                                        if typeDeclaration.IsPublic then
                                            StaticInlineMemberStub
                                        else
                                            InternalStaticInlineMemberStub

                                    let contentHash =
                                        Fingerprint.parts [
                                            typeContentHash
                                            methodDeclaration.ExportFingerprint
                                        ]

                                    methodFragment
                                        kind
                                        documentIndex
                                        typed.SourceChecksum
                                        methodDeclaration.StableId
                                        contentHash
                                        methodDeclaration
                                )

                            Some {
                                SchemaVersion = querySchema
                                StableId = typeDeclaration.StableId
                                Namespace = typed.Namespace
                                Name = typeDeclaration.Name
                                IsPublic = typeDeclaration.IsPublic
                                EnclosingTypeStableId = None
                                Kind = StaticMemberContainer
                                GenericParameters = []
                                Attributes = []
                                LiteralFields = []
                                InstanceFields = []
                                StaticFields = []
                                Properties = []
                                Methods = methods
                            }
                        | TypedMethod _
                        | TypedLiteralField _
                        | TypedNestedModule _
                        | TypedTypeAbbreviation _
                        | TypedObjectType _
                        | TypedStructType _ -> None
                    )
                )
                |> List.collect id

            let cancellableTaskSequentialHelperTypes =
                modulesWithContentHashes
                |> List.collect (fun (typed, declarationsWithContentHashes) ->
                    let rec nestedModuleMethods (moduleDeclaration: TypedNestedModuleDeclaration) = [
                        yield!
                            moduleDeclaration.Methods
                            |> List.map (fun methodDeclaration ->
                                methodDeclaration, Some moduleDeclaration.StableId
                            )

                        yield!
                            moduleDeclaration.Extensions
                            |> List.collect (fun typeDeclaration ->
                                typeDeclaration.Methods
                                |> List.map (fun objectMethodDeclaration ->
                                    objectMethodDeclaration.Method, Some typeDeclaration.StableId
                                )
                            )

                        yield!
                            moduleDeclaration.Modules
                            |> List.collect nestedModuleMethods
                    ]

                    let declarationMethods =
                        function
                        | TypedMethod methodDeclaration -> [ methodDeclaration, None ]
                        | TypedNestedModule moduleDeclaration ->
                            nestedModuleMethods moduleDeclaration
                        | TypedStaticType typeDeclaration ->
                            typeDeclaration.Methods
                            |> List.map (fun methodDeclaration ->
                                methodDeclaration, Some typeDeclaration.StableId
                            )
                        | TypedObjectType typeDeclaration ->
                            typeDeclaration.Methods
                            |> List.map (fun objectMethodDeclaration ->
                                objectMethodDeclaration.Method, Some typeDeclaration.StableId
                            )
                        | TypedLiteralField _
                        | TypedTypeAbbreviation _
                        | TypedStructType _ -> []

                    declarationsWithContentHashes
                    |> List.collect (fun (declaration, _) ->
                        declaration
                        |> declarationMethods
                        |> List.collect (fun (methodDeclaration, enclosingTypeStableId) ->
                            match methodDeclaration.Body with
                            | TypedCancellableTaskSequential sourceExpression ->
                                let layout =
                                    cancellableTaskSequentialHelperLayout
                                        methodDeclaration
                                        sourceExpression

                                let expression = layout.DefinitionExpression

                                let objectType =
                                    CoreDeclaringType {
                                        Namespace = "System"
                                        Name = "Object"
                                    }

                                let objectConstructor = {
                                    DeclaringType = objectType
                                    Name = ".ctor"
                                    GenericArity = 0
                                    IsInstance = true
                                    ParameterTypes = []
                                    ReturnType = CliVoid
                                    TargetStableId = None
                                }

                                let sequenceField = {
                                    DeclaringType = CliDeclaringType layout.DefinitionOuterType
                                    Name = "sequence"
                                    FieldType = expression.SequenceType
                                    TargetStableId = Some layout.SequenceFieldStableId
                                }

                                let cancellationTokenField = {
                                    DeclaringType = CliDeclaringType layout.DefinitionMapperType
                                    Name = "cancellationToken"
                                    FieldType = expression.CancellationTokenType
                                    TargetStableId = Some layout.CancellationTokenFieldStableId
                                }

                                let enumeratorType =
                                    CliGenericType(
                                        expression.EnumeratorTypeReference,
                                        [ expression.InputFunctionType ]
                                    )

                                let resultsType =
                                    CliGenericType(
                                        expression.ListTypeReference,
                                        [ expression.ElementType ]
                                    )

                                let enumeratorField = {
                                    DeclaringType = CliDeclaringType layout.DefinitionMapperType
                                    Name = "enumerator"
                                    FieldType = enumeratorType
                                    TargetStableId = Some layout.EnumeratorFieldStableId
                                }

                                let resultsField = {
                                    DeclaringType = CliDeclaringType layout.DefinitionMapperType
                                    Name = "results"
                                    FieldType = resultsType
                                    TargetStableId = Some layout.ResultsFieldStableId
                                }

                                let delayTaskField = {
                                    DeclaringType = CliDeclaringType layout.DefinitionDelayType
                                    Name = "task"
                                    FieldType = expression.InputFunctionType
                                    TargetStableId = Some layout.DelayTaskFieldStableId
                                }

                                let delayCancellationTokenField = {
                                    DeclaringType = CliDeclaringType layout.DefinitionDelayType
                                    Name = "cancellationToken"
                                    FieldType = expression.CancellationTokenType
                                    TargetStableId =
                                        Some layout.DelayCancellationTokenFieldStableId
                                }

                                let methodFragment
                                    stableId
                                    name
                                    kind
                                    parameters
                                    returnType
                                    instructions
                                    =
                                    {
                                        SchemaVersion = querySchema
                                        StableId = stableId
                                        Name = name
                                        Kind = kind
                                        GenericParameters = []
                                        Constraints = []
                                        GenericParameterConstraints = []
                                        Attributes = []
                                        Parameters = parameters
                                        Locals = []
                                        ReturnType = returnType
                                        Instructions = instructions
                                        EmitDefaultSequencePoint = false
                                        MaxStack = 5
                                        DependencyIds =
                                            instructionDependencyIds instructions
                                            |> List.distinct
                                        SemanticFingerprint =
                                            Fingerprint.parts [
                                                stableId
                                                methodImplementationHash methodDeclaration

                                                yield!
                                                    instructions
                                                    |> instructionDependencyIds
