                                    Namespace = String.Empty
                                    Name = typeReference.TypeName.Name
                                    IsPublic = false
                                    EnclosingTypeStableId = Some enclosingTypeStableId
                                    Kind = ObjectExpressionContainer
                                    GenericParameters = []
                                    Attributes = []
                                    LiteralFields = []
                                    InstanceFields = []
                                    StaticFields = []
                                    Properties = []
                                    Methods =
                                        constructor
                                        :: overrideMethods
