                        | TypedTypeAbbreviation _
                        | TypedStaticType _
                        | TypedStructType _ -> []
                    )
                )
                |> List.collect id

            let functionLambdaClosureTypes =
                modulesWithContentHashes
                |> List.collect (fun (typed, declarationsWithContentHashes) ->
                    let documentIndex = typed.DocumentIndex

                    let moduleTypeStableId =
                        moduleStableId
                        + "/type:"
                        + typed.StableId

                    let isNested = typed.ContainerKind = ModuleSource

                    let declarationMethods =
                        function
                        | TypedMethod methodDeclaration -> [ methodDeclaration ]
                        | TypedStaticType typeDeclaration -> typeDeclaration.Methods
                        | TypedObjectType typeDeclaration ->
                            typeDeclaration.Methods
                            |> List.map _.Method
                        | TypedLiteralField _
                        | TypedNestedModule _
                        | TypedTypeAbbreviation _
                        | TypedStructType _ -> []

                    declarationsWithContentHashes
                    |> List.collect (fun (declaration, _) ->
                        declaration
                        |> declarationMethods
                        |> List.collect (fun methodDeclaration ->
                            methodDeclaration.Body
                            |> functionLambdaExpressions
                            |> List.map (fun expression ->
                                let closureStableId =
                                    match expression.ClosureType with
                                    | CliNamedType typeReference
                                    | CliGenericType(typeReference, _) ->
                                        typeReference.DeclarationId
                                    | _ ->
                                        invalidOp
                                            "an F# function lambda closure must be a named CLI type"

                                let constructorStableId =
                                    closureStableId
                                    + "/constructor"

                                let invokeStableId =
                                    closureStableId
                                    + "/method:Invoke"

                                let captures: TypedFunctionLambdaCapture list =
                                    expression.Captures
                                    |> List.map (fun capture -> {
                                        capture with
                                            Type =
                                                methodTypeParametersToTypeParameters
                                                    capture.Type
                                            Field = mapTypedFieldAddress capture.Field
                                    })

                                let objectConstructor = {
                                    DeclaringType =
                                        CoreDeclaringType {
                                            Namespace = "System"
                                            Name = "Object"
                                        }
                                    Name = ".ctor"
                                    GenericArity = 0
                                    IsInstance = true
                                    ParameterTypes = []
                                    ReturnType = CliVoid
                                    TargetStableId = None
                                }

                                let captureFieldReference capture = {
                                    DeclaringType = CliDeclaringType capture.Field.DeclaringType
                                    Name = capture.Field.Name
                                    FieldType = capture.Field.FieldType
                                    TargetStableId = capture.Field.TargetStableId
                                }

                                let constructorInstructions = [
                                    LoadArgument 0
                                    CallMethod objectConstructor

                                    for index, capture in
                                        captures
                                        |> List.indexed do
                                        LoadArgument 0
                                        LoadArgument(index + 1)
                                        StoreField(captureFieldReference capture)

                                    Return
                                ]

                                let constructor = {
                                    SchemaVersion = querySchema
                                    StableId = constructorStableId
                                    Name = ".ctor"
                                    Kind = ClosureConstructor
                                    GenericParameters = []
                                    Constraints = []
                                    GenericParameterConstraints = []
                                    Attributes = []
                                    Parameters =
                                        captures
                                        |> List.map (fun capture -> {
                                            Name = capture.Name
                                            Type = capture.Type
                                            Attributes = []
                                        })
                                    Locals = []
                                    ReturnType = CliVoid
                                    Instructions = constructorInstructions
                                    EmitDefaultSequencePoint = true
                                    MaxStack = 8
                                    DependencyIds =
                                        objectConstructor.DependencyId
                                        :: (captures
                                            |> List.map (
                                                captureFieldReference
                                                >> _.DependencyId
                                            ))
                                    SemanticFingerprint =
                                        Fingerprint.parts [
                                            constructorStableId
                                            objectConstructor.StableId

                                            yield!
                                                captures
                                                |> List.map (fun capture ->
                                                    Fingerprint.parts [
                                                        capture.Name
                                                        TypeIdentity.cliType capture.Type
                                                        capture.Field.Name
                                                    ]
                                                )
                                        ]
                                    DocumentIndex = documentIndex
                                    DocumentChecksum = typed.SourceChecksum
                                    Range = expression.LambdaRange
                                }

                                let invokeBody =
                                    expression.Body
                                    |> methodExpressionTypesToTypeParameters

                                let invokeDeclaration: TypedMethodDeclaration = {
                                    StableId = invokeStableId
                                    Name = "Invoke"
                                    IsPublic = false
                                    GenericParameters = []
                                    Constraints = []
                                    Attributes = []
                                    Parameters = [
                                        {
                                            Name = expression.ParameterName
                                            Type =
                                                methodTypeParametersToTypeParameters
                                                    expression.ParameterType
                                            Attributes = []
                                        }
                                    ]
                                    ReturnType =
                                        methodTypeParametersToTypeParameters
                                            expression.ReturnType
                                    Body = invokeBody
                                    EmitHiddenEntrySequencePoint = false
                                    ExportFingerprint =
                                        Fingerprint.parts [
                                            invokeStableId
                                            TypeIdentity.inlineBody invokeBody
                                        ]
                                    Range = expression.LambdaRange
                                }

                                let invoke =
                                    methodFragment
                                        ClosureInvoke
                                        documentIndex
                                        typed.SourceChecksum
                                        invokeStableId
                                        (methodImplementationHash invokeDeclaration)
                                        invokeDeclaration

                                {
                                    SchemaVersion = querySchema
                                    StableId = closureStableId
                                    Namespace =
                                        if isNested then String.Empty else typed.Namespace
                                    Name = expression.ClosureName
                                    IsPublic = false
                                    EnclosingTypeStableId =
                                        if isNested then Some moduleTypeStableId else None
                                    Kind = ClosureContainer
                                    GenericParameters = methodDeclaration.GenericParameters
                                    Attributes = []
                                    LiteralFields = []
                                    InstanceFields =
                                        captures
                                        |> List.map (fun capture -> {
                                            SchemaVersion = querySchema
                                            StableId =
                                                capture.Field.TargetStableId
                                                |> Option.defaultWith (fun () ->
                                                    closureStableId
                                                    + "/field:"
                                                    + capture.Name
                                                )
                                            Name = capture.Field.Name
                                            Type = capture.Type
                                            Attributes = []
                                            SemanticFingerprint =
                                                Fingerprint.parts [
                                                    capture.Name
                                                    TypeIdentity.cliType capture.Type
                                                ]
                                        })
                                    StaticFields = []
                                    Properties = []
                                    Methods = [
                                        constructor
                                        invoke
                                    ]
                                }
                            )
                        )
                    )
                )

            let delegateLambdaClosureTypes =
                modulesWithContentHashes
                |> List.collect (fun (typed, declarationsWithContentHashes) ->
                    let documentIndex = typed.DocumentIndex

                    let moduleTypeStableId =
                        moduleStableId
                        + "/type:"
                        + typed.StableId

                    let isNested = typed.ContainerKind = ModuleSource

                    let declarationMethods =
                        function
                        | TypedMethod methodDeclaration -> [ methodDeclaration ]
                        | TypedStaticType typeDeclaration -> typeDeclaration.Methods
                        | TypedObjectType typeDeclaration ->
                            typeDeclaration.Methods
                            |> List.map _.Method
                        | TypedLiteralField _
                        | TypedNestedModule _
                        | TypedTypeAbbreviation _
                        | TypedStructType _ -> []

                    declarationsWithContentHashes
                    |> List.collect (fun (declaration, _) ->
                        declaration
                        |> declarationMethods
                        |> List.collect (fun methodDeclaration ->
                            methodDeclaration.Body
                            |> delegateLambdaExpressions
                            |> List.map (fun expression ->
                                let closureStableId =
                                    match expression.ClosureType with
                                    | CliNamedType typeReference
                                    | CliGenericType(typeReference, _) ->
                                        typeReference.DeclarationId
                                    | _ ->
                                        invalidOp
                                            "a delegate lambda closure must be a named CLI type"

                                let constructorStableId =
                                    closureStableId
                                    + "/constructor"

                                let invokeStableId =
                                    closureStableId
                                    + "/method:Invoke"

                                let captures: TypedFunctionLambdaCapture list =
                                    expression.Captures
                                    |> List.map (fun capture -> {
                                        capture with
                                            Type =
                                                methodTypeParametersToTypeParameters
                                                    capture.Type
                                            Field = mapTypedFieldAddress capture.Field
                                    })

                                let objectConstructor = {
                                    DeclaringType =
                                        CoreDeclaringType {
                                            Namespace = "System"
                                            Name = "Object"
                                        }
                                    Name = ".ctor"
                                    GenericArity = 0
                                    IsInstance = true
                                    ParameterTypes = []
                                    ReturnType = CliVoid
                                    TargetStableId = None
                                }

                                let captureFieldReference capture = {
                                    DeclaringType = CliDeclaringType capture.Field.DeclaringType
                                    Name = capture.Field.Name
                                    FieldType = capture.Field.FieldType
                                    TargetStableId = capture.Field.TargetStableId
                                }

                                let constructorInstructions = [
                                    LoadArgument 0
                                    CallMethod objectConstructor

                                    for index, capture in
                                        captures
                                        |> List.indexed do
                                        LoadArgument 0
                                        LoadArgument(index + 1)
                                        StoreField(captureFieldReference capture)

                                    Return
                                ]

                                let constructor = {
                                    SchemaVersion = querySchema
                                    StableId = constructorStableId
                                    Name = ".ctor"
                                    Kind = ClosureConstructor
                                    GenericParameters = []
                                    Constraints = []
                                    GenericParameterConstraints = []
                                    Attributes = []
                                    Parameters =
                                        captures
                                        |> List.map (fun capture -> {
                                            Name = capture.Name
                                            Type = capture.Type
                                            Attributes = []
                                        })
                                    Locals = []
                                    ReturnType = CliVoid
                                    Instructions = constructorInstructions
                                    EmitDefaultSequencePoint = true
                                    MaxStack = 8
                                    DependencyIds =
                                        objectConstructor.DependencyId
                                        :: (captures
                                            |> List.map (
                                                captureFieldReference
                                                >> _.DependencyId
                                            ))
                                    SemanticFingerprint =
                                        Fingerprint.parts [
                                            constructorStableId
                                            objectConstructor.StableId

                                            yield!
                                                captures
                                                |> List.map (fun capture ->
                                                    Fingerprint.parts [
                                                        capture.Name
                                                        TypeIdentity.cliType capture.Type
                                                        capture.Field.Name
                                                    ]
                                                )
                                        ]
                                    DocumentIndex = documentIndex
                                    DocumentChecksum = typed.SourceChecksum
                                    Range = expression.LambdaRange
                                }

                                let invokeParameters: TypedParameter list =
                                    (expression.LambdaParameterNames,
                                     expression.LambdaParameterTypes)
                                    ||> List.map2 (fun name parameterType ->
                                        ({
                                            Name = name
                                            Type =
                                                methodTypeParametersToTypeParameters
                                                    parameterType
                                            Attributes = []
                                        }
                                        : TypedParameter)
                                    )

                                let invokeBody =
                                    expression.LambdaBody
                                    |> methodExpressionTypesToTypeParameters

                                let invokeDeclaration: TypedMethodDeclaration = {
                                    StableId = invokeStableId
                                    Name = "Invoke"
                                    IsPublic = false
                                    GenericParameters = []
                                    Constraints = []
                                    Attributes = []
                                    Parameters = invokeParameters
                                    ReturnType =
                                        methodTypeParametersToTypeParameters
                                            expression.LambdaReturnType
                                    Body = invokeBody
                                    EmitHiddenEntrySequencePoint = false
                                    ExportFingerprint =
                                        Fingerprint.parts [
                                            invokeStableId
                                            TypeIdentity.inlineBody invokeBody
                                        ]
                                    Range = expression.LambdaRange
                                }

                                let invoke =
                                    methodFragment
                                        ClosureInvoke
                                        documentIndex
                                        typed.SourceChecksum
                                        invokeStableId
                                        (methodImplementationHash invokeDeclaration)
                                        invokeDeclaration

                                {
                                    SchemaVersion = querySchema
                                    StableId = closureStableId
                                    Namespace =
                                        if isNested then String.Empty else typed.Namespace
                                    Name = expression.ClosureName
                                    IsPublic = false
                                    EnclosingTypeStableId =
                                        if isNested then Some moduleTypeStableId else None
                                    Kind = ClosureContainer
                                    GenericParameters = methodDeclaration.GenericParameters
                                    Attributes = []
                                    LiteralFields = []
                                    InstanceFields =
                                        captures
                                        |> List.map (fun capture -> {
                                            SchemaVersion = querySchema
                                            StableId =
                                                capture.Field.TargetStableId
                                                |> Option.defaultWith (fun () ->
                                                    closureStableId
                                                    + "/field:"
                                                    + capture.Name
                                                )
                                            Name = capture.Field.Name
                                            Type = capture.Type
                                            Attributes = []
                                            SemanticFingerprint =
                                                Fingerprint.parts [
                                                    capture.Name
                                                    TypeIdentity.cliType capture.Type
                                                ]
                                        })
                                    StaticFields = []
                                    Properties = []
                                    Methods = [
                                        constructor
                                        invoke
                                    ]
                                }
                            )
                        )
                    )
                )

            let structTypes =
                modulesWithContentHashes
                |> List.collect (fun (typed, declarationsWithContentHashes) ->
                    let enclosingTypeStableId =
                        moduleStableId
                        + "/type:"
                        + typed.StableId

                    declarationsWithContentHashes
                    |> List.choose (fun (declaration, typeContentHash) ->
                        match declaration with
                        | TypedStructType typeDeclaration ->
                            let attributes = [
                                yield!
                                    typeDeclaration.Attributes
                                    |> List.map customAttributeFragment

                                compilationMappingAttribute
                                    typeDeclaration.StableId
                                    ObjectTypeConstruct
                            ]

                            let fields =
                                typeDeclaration.Fields
                                |> List.map (fun field -> {
                                    SchemaVersion = querySchema
                                    StableId = field.StableId
                                    Name = field.Name
                                    Type = field.Type
                                    Attributes =
                                        field.Attributes
                                        |> List.map customAttributeFragment
                                    SemanticFingerprint = field.ExportFingerprint
                                })

                            let methods =
                                typeDeclaration.Methods
                                |> List.map (fun objectMethodDeclaration ->
                                    let kind, methodDeclaration =
                                        match objectMethodDeclaration with
                                        | TypedInstanceObjectMethod(_, methodDeclaration) when
                                            not methodDeclaration.IsPublic
                                            ->
                                            InternalInstanceInlineMember, methodDeclaration
                                        | TypedInstanceObjectMethod(_, methodDeclaration) ->
                                            InstanceInlineMember, methodDeclaration
                                        | TypedStaticObjectMethod methodDeclaration when
                                            not methodDeclaration.IsPublic
                                            ->
                                            InternalStaticInlineMemberStub, methodDeclaration
                                        | TypedStaticObjectMethod methodDeclaration ->
                                            StaticInlineMemberStub, methodDeclaration

                                    methodFragment
                                        kind
                                        typed.DocumentIndex
                                        typed.SourceChecksum
                                        methodDeclaration.StableId
                                        (methodImplementationHash methodDeclaration)
                                        methodDeclaration
                                )

                            Some {
                                SchemaVersion = querySchema
                                StableId = typeDeclaration.StableId
                                Namespace = String.Empty
                                Name = typeDeclaration.Name
                                IsPublic = true
                                EnclosingTypeStableId = Some enclosingTypeStableId
                                Kind = StructContainer
                                GenericParameters = typeDeclaration.GenericParameters
                                Attributes = attributes
                                LiteralFields = []
                                InstanceFields = fields
                                StaticFields = []
                                Properties = []
                                Methods = methods
                            }
                        | TypedMethod _
                        | TypedLiteralField _
                        | TypedNestedModule _
                        | TypedTypeAbbreviation _
                        | TypedStaticType _
                        | TypedObjectType _ -> None
                    )
                )

            let types =
                moduleTypes
                @ nestedModuleTypes
                @ valueTaskBindHelperTypes
                @ valueTaskApplyHelperTypes
                @ valueTaskZipHelperTypes
                @ coldTaskParallelZipClosureTypes
                @ valueTaskOfUnitHelperTypes
                @ asyncWhileHelperTypes
                @ staticTypes
                @ objectTypes
                @ cancellableTaskSequentialHelperTypes
                @ taskTryFinallyHelperTypes
                @ objectExpressionTypes
                @ structTypes
                @ closureTypes
                @ boundMemberClosureTypes
                @ unitLambdaClosureTypes
                @ functionLambdaClosureTypes
                @ delegateLambdaClosureTypes

            let lowered: LoweredCompilation = {
                SchemaVersion = querySchema
                StableId = assemblyStableId
                AssemblyName = assemblyName
                AssemblyVersion = assemblyVersion
                PublicFingerprint =
                    typedModules
                    |> List.map _.ExportFingerprint
                    |> String.concat "|"
                    |> Fingerprint.text
                Documents = documents
                AssemblyAttributes = assemblyAttributes
                Module = {
                    SchemaVersion = querySchema
                    StableId = moduleStableId
                    Name = moduleName
                    TypeAbbreviations = typeAbbreviations
                    Types = types
                }
            }

            lowerCache.Add(key, lowered)
            lowered, key

    member _.PrepareSource(language, defines, source) = prepareSource language defines source

    member _.LexicalDiagnostics(source: LexicalDocument) : CompilerDiagnostic seq =
        source.Diagnostics
        |> Seq.filter (fun diagnostic -> diagnostic.Severity = LexicalSeverity.Error)
        |> Seq.map (lexicalDiagnostic source)

    member _.OrderedLexicalDiagnostics
        (source: LexicalDocument)
        : (LexicalSeverity * CompilerDiagnostic) seq =
        source.Diagnostics
        |> Seq.map (fun diagnostic -> diagnostic.Severity, lexicalDiagnostic source diagnostic)

    member _.Compile
        (
            assemblyName: string,
            language: LanguageVersionIdentity,
            defines: string list,
            references: ReferenceTypeIndex,
            sources: SourceSnapshot list
        ) =
        let combine values =
            match values with
            | [ value ] -> value
            | _ ->
                values
                |> String.concat "|"
                |> Fingerprint.text

        let preparedSources =
            sources
            |> List.map (fun source -> (prepareSource language defines source).Document)

        let stateKey =
            assemblyName
            + "\n"
            + references.Fingerprint
            + "\n"
            + (preparedSources
               |> List.map _.LogicalPath
               |> String.concat "\n")

        let previousContentFingerprint =
            match lastSuccessfulContent.TryGetValue(stateKey) with
            | true, fingerprint -> fingerprint
            | false, _ -> String.Empty

        let before = {
            ParseHits = parseHits
            ParseMisses = parseMisses
            CheckHits = checkHits
            CheckMisses = checkMisses
            LowerHits = lowerHits
            LowerMisses = lowerMisses
            SyntaxProjections = syntaxProjections
        }

        let decision hitsBefore hitsAfter missesBefore missesAfter =
            let hitCount =
                hitsAfter
                - hitsBefore

            let missCount =
                missesAfter
                - missesBefore

            if
                hitCount > 0
                && missCount > 0
            then
                "partial"
            elif hitCount > 0 then
                "hit"
            else
                "miss"

        let rec parseAll
            documentIndex
            (parsed: (LexicalDocument * int * ParsedModule) list)
            (keys: string list)
            (remaining: LexicalDocument list)
            =
            match remaining with
            | [] -> Ok(List.rev parsed, List.rev keys)
            | source :: _ when
                source.Diagnostics
                |> Seq.exists (fun diagnostic -> diagnostic.Severity = LexicalSeverity.Error)
                ->
                source.Diagnostics
                |> Seq.find (fun diagnostic -> diagnostic.Severity = LexicalSeverity.Error)
                |> lexicalDiagnostic source
                |> Error
            | source :: tail ->
                match parse source with
                | Error diagnostic -> Error diagnostic
                | Ok(parsedModules, key) ->
                    let sourceModules =
                        parsedModules
                        |> List.map (fun parsedModule -> source, documentIndex, parsedModule)

                    parseAll
                        (documentIndex
                         + 1)
                        ((parsed, sourceModules)
                         ||> List.fold (fun state parsedModule ->
                             parsedModule
                             :: state
                         ))
                        (key
                         :: keys)
                        tail

        let checkAll (resolvedCompilation: ResolvedCompilation) =
            let rec checkModules (typed: TypedModule list) keys remaining =
                match remaining with
                | [] -> Ok(List.rev typed, List.rev keys)
                | resolvedModule :: tail ->
                    match check references (List.rev typed) resolvedModule with
                    | Error diagnostic -> Error diagnostic
                    | Ok(typedModule, key) ->
                        checkModules
                            (typedModule
                             :: typed)
                            (key
                             :: keys)
                            tail

            match checkModules [] [] resolvedCompilation.Modules with
            | Error diagnostic -> Error diagnostic
            | Ok(typedModules, keys) ->
                let typedCompilation: TypedCompilation = {
                    Modules = typedModules
                    ContentFingerprint =
                        resolvedCompilation.ContentFingerprint
                        :: (typedModules
                            |> List.collect (fun typedModule -> [
                                typedModule.StableId
                                typedModule.ExportFingerprint
                            ]))
                        |> Fingerprint.parts
                }

                Ok(typedCompilation, keys)

        let rec resolveAll
            visibleValues
            (resolved: ResolvedModule list)
            (remaining: (LexicalDocument * int * ParsedModule) list)
            =
            match remaining with
            | [] ->
                let modules = List.rev resolved

                let resolvedCompilation: ResolvedCompilation = {
                    Modules = modules
                    ContentFingerprint =
                        modules
                        |> List.map _.ContentFingerprint
                        |> combine
                }

                Ok resolvedCompilation
            | (source, documentIndex, parsedModule) :: tail ->
                let laterModuleNames =
                    tail
                    |> List.map (fun (_, _, laterModule) -> laterModule.Name)
                    |> Set.ofList

                match
                    resolve
                        references
                        source.LogicalPath
                        documentIndex
                        visibleValues
                        laterModuleNames
                        parsedModule
                with
                | Error diagnostic -> Error diagnostic
                | Ok resolvedModule ->
                    resolveAll
                        resolvedModule.VisibleValues
                        (resolvedModule
                         :: resolved)
                        tail

        let parseStarted = Stopwatch.GetTimestamp()

        match parseAll 0 [] [] preparedSources with
        | Error error -> Error error
        | Ok(parsedModules, parseKeys) ->
            let parseElapsedMicroseconds = elapsedMicroseconds parseStarted
            let checkStarted = Stopwatch.GetTimestamp()

            match resolveAll Map.empty [] parsedModules with
            | Error diagnostic -> Error diagnostic
            | Ok resolvedCompilation ->
                match checkAll resolvedCompilation with
                | Error diagnostic -> Error diagnostic
                | Ok(typedCompilation, checkKeys) ->
                    let checkElapsedMicroseconds = elapsedMicroseconds checkStarted
                    let lowerStarted = Stopwatch.GetTimestamp()
                    let loweredCompilation, lowerKey = lower assemblyName typedCompilation
                    let lowerElapsedMicroseconds = elapsedMicroseconds lowerStarted

                    let contentFingerprint =
                        references.Fingerprint
                        :: (parsedModules
                            |> List.distinctBy (fun (_, documentIndex, _) -> documentIndex)
                            |> List.map (fun (_, _, parsedModule) ->
                                parsedModule.ContentFingerprint
                            ))
                        |> combine

                    let invalidationReason =
                        if previousContentFingerprint.Length = 0 then
                            "no-prior-state"
                        elif previousContentFingerprint = contentFingerprint then
                            "unchanged"
                        else
                            "source-content-changed"

                    lastSuccessfulContent.[stateKey] <- contentFingerprint

                    Ok {
                        ResolvedCompilation = resolvedCompilation
                        TypedCompilation = typedCompilation
                        LoweredCompilation = loweredCompilation
                        QuerySchema = querySchema
                        NodeKind = if preparedSources.Length = 1 then "source" else "project"
                        ContentFingerprint = contentFingerprint
                        PreviousContentFingerprint = previousContentFingerprint
                        InvalidationReason = invalidationReason
                        ParseKey = combine parseKeys
                        CheckKey = combine checkKeys
                        LowerKey = lowerKey
                        DependencyCount =
                            loweredCompilation.Module.TypeAbbreviations.Length
                            + (loweredCompilation.Module.Types
                               |> List.sumBy (fun typeFragment ->
                                   typeFragment.Methods
                                   |> List.sumBy (fun methodFragment ->
                                       methodFragment.DependencyIds.Length
                                   )
                               ))
                        ParseDecision =
                            decision before.ParseHits parseHits before.ParseMisses parseMisses
                        CheckDecision =
                            decision before.CheckHits checkHits before.CheckMisses checkMisses
                        LowerDecision =
                            decision before.LowerHits lowerHits before.LowerMisses lowerMisses
                        ParseElapsedMicroseconds = parseElapsedMicroseconds
                        CheckElapsedMicroseconds = checkElapsedMicroseconds
                        LowerElapsedMicroseconds = lowerElapsedMicroseconds
                    }

    member _.Statistics = {
        ParseHits = parseHits
        ParseMisses = parseMisses
        CheckHits = checkHits
        CheckMisses = checkMisses
        LowerHits = lowerHits
        LowerMisses = lowerMisses
        SyntaxProjections = syntaxProjections
    }
